// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPolicyWebAuthn {
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool);
}

/// @title FrostSecp256k1: on-chain check of a FROST(secp256k1, SHA-256) signature (RFC 9591)
/// @notice A FROST signature is a plain Schnorr signature (R, z) under the group key PK:
///         z·G == R + c·PK with c = H2(R ‖ PK ‖ msg) (RFC 9591 §6.5: hash_to_field over
///         expand_message_xmd(SHA-256), DST "FROST-secp256k1-SHA256-v1chal"; points SEC1-compressed).
///         The EVM has no secp256k1 point multiplication, so the check uses ECRECOVER:
///         ecrecover(h, v, r, s) returns the address of r⁻¹·(s·Rr − h·G), where Rr is the point with
///         x = r and y-parity v−27. With r = PK.x, v from PK.y, s = −c·PK.x and h = −z·PK.x (mod n) it
///         returns the address of z·G − c·PK, which must equal R: we compare it with the address of
///         R, lifted from its compressed form with the modexp precompile. This is the construction
///         of V. Buterin, "You can *kinda* abuse ECRECOVER to do ECMUL in secp256k1 today"
///         (ethresear.ch, 2018), used by Chainlink's SchnorrSECP256K1.sol, noot/schnorr-verify and
///         Chronicle's Scribe. Unlike those, the challenge here is RFC 9591's (so signatures from any
///         RFC 9591 implementation verify) and R is a whole curve point lifted from x and parity,
///         not an address the signer supplies.
///         Caveats (docs/future/agents.md): like every ecrecover verifier it compares 160-bit
///         addresses; the group key's x must be below the curve order n (true except with ~2^-128
///         probability; the DKG refuses such a key).
library FrostSecp256k1 {
    uint256 internal constant N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
    uint256 internal constant P = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F;

    /// y of the curve point with this x and y-parity (ok = false when x is not on the curve).
    function liftX(uint256 x, uint256 parity) internal view returns (bool ok, uint256 y) {
        if (x >= P || parity > 1) return (false, 0);
        uint256 rhs = addmod(mulmod(mulmod(x, x, P), x, P), 7, P);
        y = _modexp(rhs, (P + 1) / 4, P); // P ≡ 3 (mod 4)
        if (mulmod(y, y, P) != rhs) return (false, 0);
        if (y & 1 != parity) y = P - y; // y != 0: secp256k1 has no point of order 2
        return (true, y);
    }

    /// RFC 9380 hash_to_field(msg, 1) for secp256k1's scalar field: expand_message_xmd with SHA-256,
    /// L = 48 bytes, reduced mod n. RFC 9591 uses it for H1, H2, H3 with DST = context ‖ tag.
    function hashToScalar(bytes memory message, bytes memory dst) internal pure returns (uint256) {
        bytes memory dstPrime = abi.encodePacked(dst, uint8(dst.length));
        bytes32 b0 = sha256(abi.encodePacked(bytes32(0), bytes32(0), message, uint16(48), uint8(0), dstPrime));
        bytes32 b1 = sha256(abi.encodePacked(b0, uint8(1), dstPrime));
        bytes32 b2 = sha256(abi.encodePacked(b0 ^ b1, uint8(2), dstPrime));
        // the 48 bytes b1 ‖ b2[0:16] as an integer, mod n
        return addmod(mulmod(uint256(b1), 1 << 128, N), uint256(b2) >> 128, N);
    }

    /// RFC 9591 H2 (the challenge) for R (33 bytes), the group key (x, parity) and the message.
    function challenge(bytes memory rEnc, uint256 pkX, uint256 pkParity, bytes memory message) internal pure returns (uint256) {
        return hashToScalar(abi.encodePacked(rEnc, uint8(2 + pkParity), pkX, message), "FROST-secp256k1-SHA256-v1chal");
    }

    /// True when `sig` (RFC 9591 serialization: compressed R ‖ z, 65 bytes) is a valid signature of
    /// `message` under the group key (pkX, pkParity = PK.y mod 2).
    function verify(uint256 pkX, uint256 pkParity, bytes memory message, bytes memory sig) internal view returns (bool) {
        if (sig.length != 65 || pkX == 0 || pkX >= N || pkParity > 1) return false;
        uint256 prefix = uint8(sig[0]);
        if (prefix != 2 && prefix != 3) return false;
        uint256 rx;
        uint256 z;
        assembly {
            rx := mload(add(sig, 33))
            z := mload(add(sig, 65))
        }
        if (z == 0 || z >= N) return false;
        (bool ok, uint256 ry) = liftX(rx, prefix - 2);
        if (!ok) return false;
        uint256 c = challenge(abi.encodePacked(uint8(prefix), rx), pkX, pkParity, message);
        if (c == 0) return false;
        address q = _zGminusCP(pkX, pkParity, z, c);
        return q != address(0) && q == address(uint160(uint256(keccak256(abi.encodePacked(rx, ry)))));
    }

    /// The address of z·G − c·PK: ecrecover(−z·x, v(PK), x, −c·x) = x⁻¹·(−c·x·PK + z·x·G).
    function _zGminusCP(uint256 pkX, uint256 pkParity, uint256 z, uint256 c) private pure returns (address) {
        return ecrecover(bytes32(N - mulmod(z, pkX, N)), uint8(27 + pkParity), bytes32(pkX), bytes32(N - mulmod(c, pkX, N)));
    }

    /// A compressed group key (33 bytes) -> (x, parity), checking it is a curve point with 0 < x < n.
    function parseKey(bytes memory key) internal view returns (bool ok, uint256 x, uint256 parity) {
        if (key.length != 33 || (uint8(key[0]) != 2 && uint8(key[0]) != 3)) return (false, 0, 0);
        assembly { x := mload(add(key, 33)) }
        parity = uint8(key[0]) - 2;
        if (x == 0 || x >= N) return (false, 0, 0);
        (ok,) = liftX(x, parity);
    }

    function _modexp(uint256 b, uint256 e, uint256 m) private view returns (uint256 r) {
        (bool ok, bytes memory out) = address(0x05).staticcall(abi.encode(uint256(32), uint256(32), uint256(32), b, e, m));
        require(ok && out.length == 32, "modexp");
        r = uint256(bytes32(out));
    }
}

/// @title FrostVerifier: FrostSecp256k1 as a contract anyone can call (and the tests use)
contract FrostVerifier {
    /// groupKey: SEC1-compressed (33 bytes); sig: R (33) ‖ z (32), RFC 9591's serialization.
    function verify(bytes calldata groupKey, bytes calldata message, bytes calldata sig) external view returns (bool) {
        (bool ok, uint256 x, uint256 parity) = FrostSecp256k1.parseKey(groupKey);
        return ok && FrostSecp256k1.verify(x, parity, message, sig);
    }

    /// RFC 9591's challenge H2(R ‖ PK ‖ msg), for cross-checking implementations.
    function challenge(bytes calldata rEnc, bytes calldata groupKey, bytes calldata message) external view returns (uint256) {
        (bool ok, uint256 x, uint256 parity) = FrostSecp256k1.parseKey(groupKey);
        require(ok && rEnc.length == 33, "key");
        return FrostSecp256k1.challenge(rEnc, x, parity, message);
    }
}

/// @title CosignCommittee: runners that co-sign large agent transactions
/// @notice Two ways to co-sign, both set by governance (the chain's gov module
///         through a MsgEVMCall proposal, or a SimpleMultisig):
///           - k-of-n separate ECDSA signatures (isValid): each member signs
///             the digest; signers in ascending order, no repeats. Simple and
///             checkable, k signatures of gas. Kept as the fallback.
///           - a FROST threshold signature (isValidFrost, RFC 9591): the
///             members ran a distributed key generation (no dealer;
///             `zetaphy cosign dkg1|dkg2|dkg3`) for a t-of-n group key; any t
///             of them make ONE 65-byte Schnorr signature in two rounds
///             (`zetaphy cosign commit | frost-sign | frost-aggregate`),
///             checked by FrostSecp256k1 at the cost of about one ecrecover
///             whatever t is. Which members signed is not visible on chain.
///         A member signs only after running Neuro's checks on the transaction.
contract CosignCommittee {
    uint256 public constant MAX_MEMBERS = 32;

    address public governance;
    mapping(address => bool) public isMember;
    address[] private memberList;
    uint256 public threshold;
    uint256 public frostKeyX;      // FROST group key: x (0 = none) ...
    uint256 public frostKeyParity; // ... and the parity of y

    event MembersSet(address[] members, uint256 threshold);
    event GovernanceChanged(address governance);
    event FrostKeySet(bytes groupKey);

    error NotGovernance();
    error BadMembers();
    error BadFrostKey();

    constructor(address governance_, address[] memory initialMembers, uint256 threshold_) {
        governance = governance_;
        _set(initialMembers, threshold_);
    }

    function setMembers(address[] calldata newMembers, uint256 threshold_) external {
        if (msg.sender != governance) revert NotGovernance();
        _set(newMembers, threshold_);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert NotGovernance();
        governance = g;
        emit GovernanceChanged(g);
    }

    /// The FROST group key (33 bytes, SEC1-compressed, from `zetaphy cosign dkg3`); empty removes it.
    function setFrostKey(bytes calldata groupKey) external {
        if (msg.sender != governance) revert NotGovernance();
        if (groupKey.length == 0) {
            frostKeyX = 0;
            frostKeyParity = 0;
        } else {
            (bool ok, uint256 x, uint256 parity) = FrostSecp256k1.parseKey(groupKey);
            if (!ok) revert BadFrostKey();
            frostKeyX = x;
            frostKeyParity = parity;
        }
        emit FrostKeySet(groupKey);
    }

    /// True when `sig` is the group's FROST signature (RFC 9591, 65 bytes) of the 32-byte digest.
    function isValidFrost(bytes32 digest, bytes calldata sig) external view returns (bool) {
        if (frostKeyX == 0) return false;
        return FrostSecp256k1.verify(frostKeyX, frostKeyParity, abi.encodePacked(digest), sig);
    }

    function members() external view returns (address[] memory) {
        return memberList;
    }

    /// True when at least `threshold` distinct members signed `digest` (65-byte ECDSA each, signers ascending).
    function isValid(bytes32 digest, bytes[] calldata sigs) external view returns (bool) {
        if (threshold == 0) return false;
        uint256 count;
        address last;
        for (uint256 i = 0; i < sigs.length; i++) {
            address s = _recover(digest, sigs[i]);
            if (s <= last) return false; // ascending: no signer counted twice
            last = s;
            if (isMember[s]) count++;
        }
        return count >= threshold;
    }

    function _set(address[] memory members_, uint256 threshold_) private {
        if (members_.length > MAX_MEMBERS || threshold_ == 0 || threshold_ > members_.length) revert BadMembers();
        for (uint256 i = 0; i < memberList.length; i++) isMember[memberList[i]] = false;
        delete memberList;
        for (uint256 i = 0; i < members_.length; i++) {
            if (members_[i] == address(0) || isMember[members_[i]]) revert BadMembers();
            isMember[members_[i]] = true;
            memberList.push(members_[i]);
        }
        threshold = threshold_;
        emit MembersSet(members_, threshold_);
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

interface ICosignCommittee {
    function isValid(bytes32 digest, bytes[] calldata sigs) external view returns (bool);
    function isValidFrost(bytes32 digest, bytes calldata sig) external view returns (bool);
}

/// @title AgentPolicyWallet: a wallet an AI agent runs inside guardrails (testnet)
/// @notice The owner (a person) holds the funds and sets the policy; the agent
///         key can only act inside it:
///           - spend caps per period, per token (address 0 = the native coin),
///             counting native value, ERC-20 transfer amounts and approvals;
///             a token without a cap cannot be moved by the agent at all;
///           - allow-listed recipients (native sends and ERC-20 transfers) and
///             contracts (any other call, and approval spenders);
///             transferFrom, increaseAllowance, setApprovalForAll and permit
///             are refused outright;
///           - above a per-token threshold ("cosignAbove"), an action either
///             waits in a timelock (queue, then executeQueued after `delay`;
///             the owner may cancel) or carries co-signatures of the runner
///             committee (CosignCommittee, set by governance) that ran Neuro
///             checks on it: k-of-n ECDSA (executeCosigned) or one FROST
///             threshold signature (executeCosignedFrost). Caps apply to all;
///           - emergency freeze: the owner's account, the owner's passkey
///             (WebAuthn, P-256 precompile via WebAuthnVerifier) or the
///             owner's ML-DSA-44 key (precompile 0x…0900) stops the agent at
///             once; passkey and PQ freezes are signed messages anyone can
///             relay. Only the owner's account unfreezes.
///         Every agent action logs (modelHash, promptHash) provenance.
///         The owner itself is not limited (ownerExecute), so it can always
///         take the funds back, frozen or not.
contract AgentPolicyWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    bytes4 private constant TRANSFER = 0xa9059cbb;
    bytes4 private constant APPROVE = 0x095ea7b3;
    bytes4 private constant TRANSFER_FROM = 0x23b872dd;
    bytes4 private constant INCREASE_ALLOWANCE = 0x39509351;
    bytes4 private constant SET_APPROVAL_FOR_ALL = 0xa22cb465;
    bytes4 private constant PERMIT = 0xd505accf;
    uint256 public constant MAX_DELAY = 30 days;

    struct Limit {
        bool set;
        uint256 perPeriod;
        uint256 cosignAbove; // amounts above this need the timelock or the committee
        uint256 spent;
        uint64 windowStart;
    }

    address public owner;
    address public agent;
    ICosignCommittee public committee;
    IPolicyWebAuthn public webauthn;

    bytes32 public pqKeyHash;   // owner's ML-DSA-44 key (0 = none)
    uint256 public passkeyX;    // owner's passkey (0,0 = none)
    uint256 public passkeyY;
    bytes32 public rpIdHash;

    bool public frozen;
    uint256 public freezeNonce;
    uint256 public cosignNonce;
    uint256 public period;
    uint256 public delay;
    uint256 public queueCount;

    mapping(address => Limit) public limits;
    mapping(address => bool) public allowedTarget;
    mapping(address => bool) public allowedRecipient;
    mapping(bytes32 => uint64) public queuedAt; // id -> ready time (0 = none)

    event AgentAction(address indexed to, uint256 value, bytes4 selector, address token, uint256 amount, bytes32 modelHash, bytes32 promptHash, uint8 path);
    event Queued(bytes32 indexed id, uint256 seq, address to, uint256 value, bytes data, bytes32 modelHash, bytes32 promptHash, uint64 readyAt);
    event Cancelled(bytes32 indexed id);
    event Frozen(address by, uint8 how);
    event Unfrozen();
    event LimitSet(address indexed token, uint256 perPeriod, uint256 cosignAbove);
    event AllowSet(address indexed who, bool target, bool recipient);
    event ConfigSet(address agent, address committee, uint256 period, uint256 delay);
    event EmergencyKeysSet(bytes32 pqKeyHash, uint256 passkeyX, uint256 passkeyY, bytes32 rpIdHash);
    event OwnerChanged(address owner);

    error NotOwner();
    error NotAgent();
    error IsFrozen();
    error NotAllowed(address who);
    error Forbidden(bytes4 selector);
    error NoLimit(address token);
    error OverCap(address token, uint256 spent, uint256 cap);
    error NeedsDelayOrCosign(address token, uint256 amount);
    error NotQueued();
    error NotReady();
    error BadCosign();
    error Expired();
    error BadEmergencyKey();
    error BadConfig();
    error CallFailed(bytes reason);

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyAgent() {
        if (msg.sender != agent) revert NotAgent();
        if (frozen) revert IsFrozen();
        _;
    }

    constructor(address owner_, address agent_, address committee_, address webauthn_, uint256 period_, uint256 delay_) payable {
        owner = owner_;
        webauthn = IPolicyWebAuthn(webauthn_);
        _config(agent_, committee_, period_, delay_);
    }

    receive() external payable {}

    // ------------------------------------------------------------- agent

    /// Within caps, allow-lists and below every cosignAbove: runs at once.
    function execute(address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes memory)
    {
        (address token, uint256 amount) = _classify(to, value, data);
        if (amount != 0 && !limits[token].set) revert NoLimit(token);
        if (amount > limits[token].cosignAbove) revert NeedsDelayOrCosign(token, amount);
        return _run(to, value, data, token, amount, modelHash, promptHash, 0);
    }

    /// Above a threshold, path 1: wait `delay`, during which the owner sees it and may cancel or freeze.
    function queue(address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes32 id)
    {
        _classify(to, value, data); // allow-lists checked now too, so a bad action fails early
        uint256 seq = ++queueCount;
        id = keccak256(abi.encode(seq, to, value, keccak256(data), modelHash, promptHash));
        uint64 readyAt = uint64(block.timestamp + delay);
        queuedAt[id] = readyAt;
        emit Queued(id, seq, to, value, data, modelHash, promptHash, readyAt);
    }

    function executeQueued(uint256 seq, address to, uint256 value, bytes calldata data, bytes32 modelHash, bytes32 promptHash)
        external onlyAgent returns (bytes memory)
    {
        bytes32 id = keccak256(abi.encode(seq, to, value, keccak256(data), modelHash, promptHash));
        uint64 readyAt = queuedAt[id];
        if (readyAt == 0) revert NotQueued();
        if (block.timestamp < readyAt) revert NotReady();
        delete queuedAt[id];
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 1);
    }

    /// The digest committee members sign for one large action (raw 32 bytes, no EIP-191 prefix;
    /// bound to this chain, this wallet and cosignNonce). src/cosign.js computes the same.
    function cosignDigest(address to, uint256 value, bytes calldata data, bytes32 reportHash, uint256 deadline)
        public view returns (bytes32)
    {
        return keccak256(abi.encode("ZETAPHY AgentCosign", block.chainid, address(this), cosignNonce, to, value,
            keccak256(data), reportHash, deadline));
    }

    /// Above a threshold, path 2: no wait, with the committee's co-signatures
    /// (reportHash = the Neuro report the runners checked).
    function executeCosigned(
        address to,
        uint256 value,
        bytes calldata data,
        bytes32 modelHash,
        bytes32 promptHash,
        bytes32 reportHash,
        uint256 deadline,
        bytes[] calldata sigs
    ) external onlyAgent returns (bytes memory) {
        if (block.timestamp > deadline) revert Expired();
        if (address(committee) == address(0) || !committee.isValid(cosignDigest(to, value, data, reportHash, deadline), sigs)) revert BadCosign();
        cosignNonce++;
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 2);
    }

    /// Path 2 with ONE FROST threshold signature of the same digest (any t of the committee's DKG
    /// group signed it in two rounds) instead of k separate ECDSA signatures.
    function executeCosignedFrost(
        address to,
        uint256 value,
        bytes calldata data,
        bytes32 modelHash,
        bytes32 promptHash,
        bytes32 reportHash,
        uint256 deadline,
        bytes calldata sig
    ) external onlyAgent returns (bytes memory) {
        if (block.timestamp > deadline) revert Expired();
        if (address(committee) == address(0) || !committee.isValidFrost(cosignDigest(to, value, data, reportHash, deadline), sig)) revert BadCosign();
        cosignNonce++;
        (address token, uint256 amount) = _classify(to, value, data);
        return _run(to, value, data, token, amount, modelHash, promptHash, 3);
    }

    // ------------------------------------------------------------- emergency freeze

    /// The 32 bytes the owner's passkey or ML-DSA key signs to freeze the wallet.
    function freezeChallenge() public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY freeze", block.chainid, address(this), freezeNonce));
    }

    function freeze() external onlyOwner {
        _freeze(0);
    }

    function freezeWithPasskey(IPolicyWebAuthn.Assertion calldata assertion) external {
        if (passkeyX == 0 && passkeyY == 0) revert BadEmergencyKey();
        if (!webauthn.verify(freezeChallenge(), assertion, passkeyX, passkeyY, rpIdHash, true)) revert BadEmergencyKey();
        _freeze(1);
    }

    function freezeWithPq(bytes calldata pqPublicKey, bytes calldata pqSig) external {
        if (pqKeyHash == bytes32(0) || keccak256(pqPublicKey) != pqKeyHash) revert BadEmergencyKey();
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(uint8(44), freezeChallenge(), pqPublicKey, pqSig));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadEmergencyKey();
        _freeze(2);
    }

    function unfreeze() external onlyOwner {
        frozen = false;
        emit Unfrozen();
    }

    // ------------------------------------------------------------- owner

    function ownerExecute(address to, uint256 value, bytes calldata data) external onlyOwner returns (bytes memory ret) {
        bool ok;
        (ok, ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
    }

    function cancel(bytes32 id) external onlyOwner {
        if (queuedAt[id] == 0) revert NotQueued();
        delete queuedAt[id];
        emit Cancelled(id);
    }

    function setLimit(address token, uint256 perPeriod, uint256 cosignAbove) external onlyOwner {
        Limit storage l = limits[token];
        l.set = true;
        l.perPeriod = perPeriod;
        l.cosignAbove = cosignAbove;
        emit LimitSet(token, perPeriod, cosignAbove);
    }

    function setAllowed(address who, bool target, bool recipient) external onlyOwner {
        allowedTarget[who] = target;
        allowedRecipient[who] = recipient;
        emit AllowSet(who, target, recipient);
    }

    function setConfig(address agent_, address committee_, uint256 period_, uint256 delay_) external onlyOwner {
        _config(agent_, committee_, period_, delay_);
    }

    function setEmergencyKeys(bytes32 pqKeyHash_, uint256 x, uint256 y, bytes32 rpIdHash_) external onlyOwner {
        pqKeyHash = pqKeyHash_;
        passkeyX = x;
        passkeyY = y;
        rpIdHash = rpIdHash_;
        emit EmergencyKeysSet(pqKeyHash_, x, y, rpIdHash_);
    }

    function setOwner(address o) external onlyOwner {
        if (o == address(0)) revert BadConfig();
        owner = o;
        emit OwnerChanged(o);
    }

    /// What is left of a token's cap in the current period.
    function remaining(address token) external view returns (uint256) {
        Limit storage l = limits[token];
        if (!l.set) return 0;
        uint256 spent = block.timestamp >= l.windowStart + period ? 0 : l.spent;
        return spent >= l.perPeriod ? 0 : l.perPeriod - spent;
    }

    // ------------------------------------------------------------- internals

    function _config(address agent_, address committee_, uint256 period_, uint256 delay_) private {
        if (period_ == 0 || delay_ > MAX_DELAY) revert BadConfig();
        agent = agent_;
        committee = ICosignCommittee(committee_);
        period = period_;
        delay = delay_;
        emit ConfigSet(agent_, committee_, period_, delay_);
    }

    function _freeze(uint8 how) private {
        frozen = true;
        freezeNonce++;
        emit Frozen(msg.sender, how);
    }

    /// Which token an action moves and how much, after the allow-list checks.
    function _classify(address to, uint256 value, bytes calldata data) private view returns (address token, uint256 amount) {
        if (data.length == 0) {
            if (!allowedRecipient[to] && !allowedTarget[to]) revert NotAllowed(to);
            return (address(0), value);
        }
        bytes4 sel = data.length >= 4 ? bytes4(data[0:4]) : bytes4(0);
        if (sel == TRANSFER_FROM || sel == INCREASE_ALLOWANCE || sel == SET_APPROVAL_FOR_ALL || sel == PERMIT) revert Forbidden(sel);
        if (sel == TRANSFER || sel == APPROVE) {
            if (value != 0 || data.length < 68) revert Forbidden(sel);
            (address who, uint256 amt) = abi.decode(data[4:68], (address, uint256));
            if (sel == TRANSFER ? !allowedRecipient[who] : !allowedTarget[who]) revert NotAllowed(who);
            if (!limits[to].set) revert NoLimit(to);
            return (to, amt);
        }
        if (!allowedTarget[to]) revert NotAllowed(to);
        return (address(0), value);
    }

    function _run(address to, uint256 value, bytes calldata data, address token, uint256 amount, bytes32 modelHash, bytes32 promptHash, uint8 path)
        private returns (bytes memory ret)
    {
        if (amount != 0) {
            Limit storage l = limits[token];
            if (!l.set) revert NoLimit(token);
            if (block.timestamp >= l.windowStart + period) {
                l.windowStart = uint64(block.timestamp);
                l.spent = 0;
            }
            uint256 spent = l.spent + amount;
            if (spent > l.perPeriod) revert OverCap(token, spent, l.perPeriod);
            l.spent = spent;
        }
        bool ok;
        (ok, ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit AgentAction(to, value, data.length >= 4 ? bytes4(data[0:4]) : bytes4(0), token, amount, modelHash, promptHash, path);
    }
}

contracts/AgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// A deterministic policy checker: given an action an agent recorded, the
/// agent's constitution (the document whose keccak256 the agent registered)
/// and optional evidence, says whether the action broke the policy, who was
/// harmed and how much. It must be a pure function of its inputs.
interface IPolicyChecker {
    struct ActionView {
        uint256 agentId;
        address target;
        uint256 value;
        bytes32 dataHash;
        bytes32 modelHash;
        bytes32 promptHash;
        uint64 time;
    }

    function check(ActionView calldata action, bytes calldata constitution, bytes calldata evidence)
        external view returns (bool violated, address victim, uint256 damage);
}

/// @title AgentRegistry: AI agents with an identity, a bond and liability (testnet)
/// @notice An agent is registered by its operator (who answers for it) with:
///           - the EVM account it transacts from (for human/agent labels),
///           - an ML-DSA-44 public key (only its keccak256 is stored; the key
///             rides in calldata, as in QuantumWallet) that signs every action
///             it records, checked by ZETAPHY's precompile at 0x…0900,
///           - a bond in testnet ZETAPHY (at least minBond),
///           - a constitution: the keccak256 of its policy document, and an
///             optional deterministic checker contract for that policy.
///         Each recorded action carries provenance: the hash of the model
///         (weights or model id + version) and of the prompt that produced it.
///
///         Claims, when an action broke the policy:
///           - checker path: anyone shows the constitution document; the
///             agent's checker decides deterministically, and the damage (at
///             most the bond) is paid to the victim the checker names, at once;
///           - committee path: a claimant posts claimDeposit and an evidence
///             hash; governance's claims committee votes; threshold "yes"
///             pays the claimed amount (at most the bond) to the claimant and
///             returns the deposit; threshold "no", or no decision within
///             VOTE_PERIOD, rejects it and the deposit goes to the operator.
///         The operator can take the bond back only UNBOND_DELAY after asking,
///         with no open claim; claims on an action are open for CLAIM_WINDOW.
contract AgentRegistry {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint8 public constant PQ_VARIANT = 44;
    uint256 public constant UNBOND_DELAY = 7 days;
    uint256 public constant CLAIM_WINDOW = 30 days;
    uint256 public constant VOTE_PERIOD = 7 days;
    uint256 public constant MAX_COMMITTEE = 32;

    struct Agent {
        address operator;
        address account;
        bytes32 pqKeyHash;
        bytes32 constitution;
        address checker;
        uint256 bond;
        uint64 unbondAt;   // 0 = not unbonding
        uint64 actions;    // per-agent sequence, in every action digest (no replay)
        uint32 openClaims;
    }

    struct Action {
        uint256 agentId;
        address target;
        uint256 value;
        bytes32 dataHash;
        bytes32 modelHash;
        bytes32 promptHash;
        bytes32 constitution; // the agent's constitution when it acted
        address checker;      // and its checker
        uint64 time;
        bool slashed;         // a checker claim was paid (one payout per action)
    }

    enum ClaimState { None, Open, Upheld, Rejected }

    struct Claim {
        uint256 actionId;
        address claimant;
        uint256 amount;
        uint256 deposit;
        bytes32 evidenceHash;
        uint64 opened;
        uint16 yes;
        uint16 no;
        ClaimState state;
    }

    address public governance;
    uint256 public minBond;
    uint256 public claimDeposit;

    uint256 public agentCount;
    mapping(uint256 => Agent) public agents;
    mapping(address => uint256) public agentOfAccount; // account -> agent id (0 = none)

    uint256 public actionCount;
    mapping(uint256 => Action) public actions;

    uint256 public claimCount;
    mapping(uint256 => Claim) public claims;
    mapping(uint256 => mapping(address => bool)) public voted;

    mapping(address => bool) public isCommittee;
    address[] private committee;
    uint256 public committeeThreshold;

    event AgentRegistered(uint256 indexed id, address indexed operator, address indexed account, bytes32 pqKeyHash, bytes32 constitution, address checker, uint256 bond);
    event AgentUpdated(uint256 indexed id, bytes32 pqKeyHash, bytes32 constitution, address checker);
    event BondAdded(uint256 indexed id, uint256 amount, uint256 bond);
    event UnbondRequested(uint256 indexed id, uint64 at);
    event BondWithdrawn(uint256 indexed id, uint256 amount);
    event ActionRecorded(uint256 indexed agentId, uint256 indexed actionId, ActionInput action);
    event Slashed(uint256 indexed agentId, uint256 indexed actionId, address indexed to, uint256 amount);
    event ClaimFiled(uint256 indexed claimId, uint256 indexed actionId, address indexed claimant, uint256 amount, bytes32 evidenceHash);
    event ClaimVoted(uint256 indexed claimId, address indexed member, bool uphold);
    event ClaimClosed(uint256 indexed claimId, ClaimState state, uint256 paid);
    event CommitteeSet(address[] members, uint256 threshold);
    event ParamsSet(uint256 minBond, uint256 claimDeposit);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotOperator();
    error BondTooLow();
    error BadAccount();
    error AccountTaken();
    error NoAgent();
    error Inactive();
    error WrongKey();
    error BadPq();
    error Unbonding();
    error NotYet();
    error OpenClaims();
    error NoAction();
    error ClaimWindowOver();
    error BadConstitution();
    error NoChecker();
    error NotViolated();
    error AlreadySlashed();
    error BadDeposit();
    error NotCommittee();
    error AlreadyVoted();
    error ClaimNotOpen();
    error BadCommittee();
    error TransferFailed();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_, uint256 minBond_, uint256 claimDeposit_) {
        governance = governance_;
        minBond = minBond_;
        claimDeposit = claimDeposit_;
        emit ParamsSet(minBond_, claimDeposit_);
    }

    // ------------------------------------------------------------- agents

    function register(address account, bytes32 pqKeyHash, bytes32 constitution, address checker) external payable returns (uint256 id) {
        if (msg.value < minBond) revert BondTooLow();
        if (account == address(0) || pqKeyHash == bytes32(0)) revert BadAccount();
        if (agentOfAccount[account] != 0) revert AccountTaken();
        id = ++agentCount;
        agents[id] = Agent({operator: msg.sender, account: account, pqKeyHash: pqKeyHash, constitution: constitution,
            checker: checker, bond: msg.value, unbondAt: 0, actions: 0, openClaims: 0});
        agentOfAccount[account] = id;
        emit AgentRegistered(id, msg.sender, account, pqKeyHash, constitution, checker, msg.value);
    }

    /// New key, constitution or checker. Past actions keep the constitution
    /// and checker they were recorded under.
    function update(uint256 id, bytes32 pqKeyHash, bytes32 constitution, address checker) external {
        Agent storage a = _operated(id);
        if (pqKeyHash == bytes32(0)) revert BadAccount();
        a.pqKeyHash = pqKeyHash;
        a.constitution = constitution;
        a.checker = checker;
        emit AgentUpdated(id, pqKeyHash, constitution, checker);
    }

    function addBond(uint256 id) external payable {
        Agent storage a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        a.bond += msg.value;
        emit BondAdded(id, msg.value, a.bond);
    }

    /// Stops new actions; the bond can be withdrawn UNBOND_DELAY later.
    function requestUnbond(uint256 id) external {
        Agent storage a = _operated(id);
        if (a.unbondAt != 0) revert Unbonding();
        a.unbondAt = uint64(block.timestamp + UNBOND_DELAY);
        emit UnbondRequested(id, a.unbondAt);
    }

    function withdrawBond(uint256 id) external {
        Agent storage a = _operated(id);
        if (a.unbondAt == 0 || block.timestamp < a.unbondAt) revert NotYet();
        if (a.openClaims != 0) revert OpenClaims();
        uint256 amount = a.bond;
        a.bond = 0;
        delete agentOfAccount[a.account];
        emit BondWithdrawn(id, amount);
        _pay(a.operator, amount);
    }

    /// Active = bonded at least minBond and not unbonding.
    function isActive(uint256 id) public view returns (bool) {
        Agent storage a = agents[id];
        return a.operator != address(0) && a.unbondAt == 0 && a.bond >= minBond;
    }

    /// For label readers: the active agent an account belongs to (0 = none).
    function activeAgentOf(address account) external view returns (uint256) {
        uint256 id = agentOfAccount[account];
        return id != 0 && isActive(id) ? id : 0;
    }

    // ------------------------------------------------------------- actions

    /// What an agent did (or is about to do), with its provenance.
    struct ActionInput {
        address target;
        uint256 value;
        bytes32 dataHash;   // keccak256 of the calldata (or of an off-chain action's description)
        bytes32 modelHash;  // keccak256 of the model weights, or of "provider/model-id@version"
        bytes32 promptHash; // keccak256 of the full prompt (system + user) that produced the action
    }

    /// The 32 bytes the agent's ML-DSA-44 key signs for its next action.
    function actionDigest(uint256 id, ActionInput calldata x) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY AgentAction", block.chainid, address(this), id, agents[id].actions,
            x.target, x.value, x.dataHash, x.modelHash, x.promptHash));
    }

    /// Records one action with its provenance. Anyone may submit it (a relay);
    /// only the agent's ML-DSA key can have signed it.
    function recordAction(uint256 id, ActionInput calldata x, bytes calldata pqPublicKey, bytes calldata pqSig)
        external returns (uint256 actionId)
    {
        Agent storage a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        if (!isActive(id)) revert Inactive();
        if (keccak256(pqPublicKey) != a.pqKeyHash) revert WrongKey();
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(PQ_VARIANT, actionDigest(id, x), pqPublicKey, pqSig));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) revert BadPq();
        a.actions++;
        actionId = ++actionCount;
        Action storage r = actions[actionId];
        r.agentId = id;
        r.target = x.target;
        r.value = x.value;
        r.dataHash = x.dataHash;
        r.modelHash = x.modelHash;
        r.promptHash = x.promptHash;
        r.constitution = a.constitution;
        r.checker = a.checker;
        r.time = uint64(block.timestamp);
        emit ActionRecorded(id, actionId, x);
    }

    // ------------------------------------------------------------- claims: deterministic checker

    /// Shows the constitution an action was recorded under; if the agent's
    /// checker finds a violation, the damage (at most the bond) goes to the
    /// victim the checker names. Anyone may call it; one payout per action.
    function claimByChecker(uint256 actionId, bytes calldata constitution, bytes calldata evidence) external returns (uint256 paid) {
        Action storage act = _claimable(actionId);
        if (act.checker == address(0)) revert NoChecker();
        if (act.slashed) revert AlreadySlashed();
        if (keccak256(constitution) != act.constitution) revert BadConstitution();
        IPolicyChecker.ActionView memory v = IPolicyChecker.ActionView({agentId: act.agentId, target: act.target,
            value: act.value, dataHash: act.dataHash, modelHash: act.modelHash, promptHash: act.promptHash, time: act.time});
        (bool violated, address victim, uint256 damage) = IPolicyChecker(act.checker).check(v, constitution, evidence);
        if (!violated || victim == address(0) || damage == 0) revert NotViolated();
        act.slashed = true;
        paid = _slash(act.agentId, actionId, victim, damage);
    }

    // ------------------------------------------------------------- claims: committee vote

    function fileClaim(uint256 actionId, uint256 amount, bytes32 evidenceHash) external payable returns (uint256 claimId) {
        Action storage act = _claimable(actionId);
        if (msg.value != claimDeposit) revert BadDeposit();
        claimId = ++claimCount;
        claims[claimId] = Claim({actionId: actionId, claimant: msg.sender, amount: amount, deposit: msg.value,
            evidenceHash: evidenceHash, opened: uint64(block.timestamp), yes: 0, no: 0, state: ClaimState.Open});
        agents[act.agentId].openClaims++;
        emit ClaimFiled(claimId, actionId, msg.sender, amount, evidenceHash);
    }

    function vote(uint256 claimId, bool uphold) external {
        if (!isCommittee[msg.sender]) revert NotCommittee();
        Claim storage c = claims[claimId];
        if (c.state != ClaimState.Open || block.timestamp > c.opened + VOTE_PERIOD) revert ClaimNotOpen();
        if (voted[claimId][msg.sender]) revert AlreadyVoted();
        voted[claimId][msg.sender] = true;
        if (uphold) c.yes++; else c.no++;
        emit ClaimVoted(claimId, msg.sender, uphold);
        if (c.yes >= committeeThreshold) _close(claimId, true);
        else if (c.no >= committeeThreshold) _close(claimId, false);
    }

    /// After VOTE_PERIOD without a decision, anyone may close the claim as rejected.
    function expireClaim(uint256 claimId) external {
        Claim storage c = claims[claimId];
        if (c.state != ClaimState.Open) revert ClaimNotOpen();
        if (block.timestamp <= c.opened + VOTE_PERIOD) revert NotYet();
        _close(claimId, false);
    }

    // ------------------------------------------------------------- governance

    function setCommittee(address[] calldata members, uint256 threshold) external onlyGovernance {
        if (members.length > MAX_COMMITTEE || threshold == 0 || threshold > members.length) revert BadCommittee();
        for (uint256 i = 0; i < committee.length; i++) isCommittee[committee[i]] = false;
        delete committee;
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == address(0) || isCommittee[members[i]]) revert BadCommittee();
            isCommittee[members[i]] = true;
            committee.push(members[i]);
        }
        committeeThreshold = threshold;
        emit CommitteeSet(members, threshold);
    }

    function committeeMembers() external view returns (address[] memory) {
        return committee;
    }

    function setParams(uint256 minBond_, uint256 claimDeposit_) external onlyGovernance {
        minBond = minBond_;
        claimDeposit = claimDeposit_;
        emit ParamsSet(minBond_, claimDeposit_);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _operated(uint256 id) private view returns (Agent storage a) {
        a = agents[id];
        if (a.operator == address(0)) revert NoAgent();
        if (a.operator != msg.sender) revert NotOperator();
    }

    function _claimable(uint256 actionId) private view returns (Action storage act) {
        act = actions[actionId];
        if (act.agentId == 0) revert NoAction();
        if (block.timestamp > act.time + CLAIM_WINDOW) revert ClaimWindowOver();
        if (agents[act.agentId].bond == 0) revert Inactive(); // bond withdrawn or slashed away: nothing to claim
    }

    function _close(uint256 claimId, bool upheld) private {
        Claim storage c = claims[claimId];
        uint256 agentId = actions[c.actionId].agentId;
        Agent storage a = agents[agentId];
        a.openClaims--;
        uint256 paid;
        if (upheld) {
            c.state = ClaimState.Upheld;
            paid = _slash(agentId, c.actionId, c.claimant, c.amount);
            _pay(c.claimant, c.deposit);
        } else {
            c.state = ClaimState.Rejected;
            _pay(a.operator, c.deposit);
        }
        emit ClaimClosed(claimId, c.state, paid);
    }

    function _slash(uint256 agentId, uint256 actionId, address to, uint256 amount) private returns (uint256 paid) {
        Agent storage a = agents[agentId];
        paid = amount < a.bond ? amount : a.bond;
        a.bond -= paid;
        emit Slashed(agentId, actionId, to, paid);
        _pay(to, paid);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}

/// @title ConstitutionChecker: a deterministic checker for simple agent policies
/// @notice The constitution document is
///           abi.encode(address principal, uint256 maxValuePerAction,
///                      address[] allowedTargets, bytes32[] allowedModels)
///         and an action violates it when its value is above the cap, its
///         target is not allowed (an empty list allows none), or its model is
///         not allowed (an empty list allows any). The victim is the
///         principal; the damage is the action's value (the part above the
///         cap, for a cap violation).
contract ConstitutionChecker is IPolicyChecker {
    function check(ActionView calldata action, bytes calldata constitution, bytes calldata)
        external pure returns (bool violated, address victim, uint256 damage)
    {
        (address principal, uint256 maxValue, address[] memory targets, bytes32[] memory models) =
            abi.decode(constitution, (address, uint256, address[], bytes32[]));
        if (!_allowed(action.target, action.modelHash, targets, models)) return (true, principal, action.value);
        if (action.value > maxValue) return (true, principal, action.value - maxValue);
        return (false, address(0), 0);
    }

    function _allowed(address target, bytes32 model, address[] memory targets, bytes32[] memory models) private pure returns (bool) {
        bool targetOk;
        for (uint256 i = 0; i < targets.length; i++) if (targets[i] == target) targetOk = true;
        bool modelOk = models.length == 0;
        for (uint256 i = 0; i < models.length; i++) if (models[i] == model) modelOk = true;
        return targetOk && modelOk;
    }
}

contracts/BridgeAirlock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnerRecords {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IGuardInbound {
    function inbound(bytes32 route, address to, uint256 amount) external;
    function guardian(address who) external view returns (bool);
}

/// ThreatRegistry's views (Reason as its uint8 value). is*Held: once the flag is
/// the registry's holdDelay old (e.g. 10 minutes), or at once through its fast
/// lane or a guardian's holdNow. is*Enforced: once the flag is the registry's
/// enforceDelay old, or at once through its fast lane.
interface IThreatFlags {
    function isAddressEnforced(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractEnforced(address who) external view returns (bool, uint8);
    function isAddressHeld(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// NeuroControl (Neuro's stop switch); only `paused()` is used here.
interface INeuroControl {
    function paused() external view returns (bool);
}

/// A lane says who decides what it attests (NeuroLane: its runner records;
/// HyperlaneLane: its Mailbox). Lanes whose controllers are the same address
/// are one lane as far as independence goes.
interface ILaneInfo {
    function laneController() external view returns (address);
}

/// @title BridgeAirlock: nothing enters ZETAPHY on one bridge's word (stage 3)
/// @notice Defence in depth for incoming assets:
///   1. Several independent "lanes" (Hyperlane, IBC, the Neuro runner lane...)
///      must each attest the SAME transfer. One hacked bridge alone cannot
///      create money.
///   2. Even then the transfer waits in quarantine. During it, vetoers (the
///      Neuro lane by quorum, or a guardian) can stop it.
///   3. Markers: keys governance names (setMarker), typically the bridge
///      monitor's own low-privilege key, can mark an address (trip). A
///      transfer from or to a marked address is not released until governance
///      lifts the mark (untrip). Why an address is marked is decided off-chain
///      by the marker; the airlock keeps no list of what it watches.
///   4. Vaccine: with a ThreatRegistry set, a transfer whose source sender or
///      source contract (on its chain), or whose ZETAPHY recipient (address or
///      code), is flagged by the Neuro runners is not released:
///        - flagged, within the registry's holdDelay (e.g. 10 minutes): not
///          held yet, so a 2-runner quorum alone cannot freeze anyone's
///          transfers at once; governance or a guardian can holdNow(key)
///          meanwhile (the registry's fast lane holds at once too).
///        - held (past holdDelay, fast lane or holdNow), not enforced yet:
///          release reverts with ThreatHeld. It comes out once the flag is
///          cleared (same quorum, or an upheld appeal) or governance protects
///          the key; nothing else releases it.
///        - enforced (past the registry's enforceDelay, or at once through its
///          fast lane): refused, release reverts with ThreatFlagged, as long as
///          the flag stands. The transfer stays, so it still comes out if the
///          flag is cleared or the key protected.
///      For a hold that outlives any flag, the Neuro lane or a guardian vetoes.
///      The coins stay locked in the source chain's LockBox meanwhile: it has no
///      refund path, so a held (or vetoed) transfer is not paid back there.
///      deploy-bridge therefore protects the bridge's own keys and the source
///      LockBox in the registry, so runners cannot hold every transfer at once.
///   Released transfers still pass BridgeGuard's daily limits.
///   Independence: each lane names its controller (laneController(): NeuroLane
///   its runner records, HyperlaneLane its Mailbox; a plain key is its own).
///   independentLanes() counts distinct controllers, and BridgeGuard enables
///   this airlock's route only while it is 2 or more.
contract BridgeAirlock {
    struct Transfer {
        uint64 readyFrom;    // when the threshold was reached; quarantine counts from here
        uint8 attestations;
        bool released;
        bool vetoed;
    }

    IGuardInbound public immutable guard;
    bytes32 public immutable route;     // this airlock's route in BridgeGuard
    address public governance;
    uint8 public threshold;             // distinct lanes that must agree
    uint64 public quarantine;           // seconds a transfer waits after enough lanes agreed
    mapping(address => bool) public isLane;
    address[] private laneList;         // the lanes now on, in no particular order
    uint256 public constant MAX_LANES = 16;
    mapping(address => bool) public isVetoer;
    /// Keys that may mark addresses (trip). See trip(): a marker can only mark.
    mapping(address => bool) public isMarker;
    uint256 public markerCount;         // markers now on
    /// Who marked an address (zero: not marked). A mark counts while its
    /// marker is a marker, or was removed by a guardian (markerRevoked);
    /// governance removing a marker (setMarker) lifts all of its marks at once
    /// (see tripped()).
    mapping(address => address) public trippedBy;
    /// Markers a guardian removed (emergencyRemoveMarker): they mark no more,
    /// but the marks they made still count until governance decides
    /// (setMarker, untrip).
    mapping(address => bool) public markerRevoked;
    mapping(bytes32 => Transfer) public transfers;
    mapping(bytes32 => mapping(address => bool)) public attestedBy;
    /// By controller (laneControllerOf at attest time): two lanes with one
    /// controller count once, so the threshold means independent lanes.
    mapping(bytes32 => mapping(address => bool)) public attestedByController;
    IThreatFlags public threats;        // zero: no vaccine check

    event LaneSet(address lane, bool on);
    event GovernanceSet(address governance);
    event ThresholdSet(uint8 threshold);
    event QuarantineSet(uint64 quarantine);
    event Untripped(address indexed who);
    event VetoerSet(address who, bool on);
    event MarkerSet(address marker, bool on);
    /// The transfer's details too, so a monitor sees two lanes that disagree
    /// about one source deposit (same chain, contract and nonce; another id).
    event Attested(bytes32 indexed id, address indexed lane, uint8 count, uint256 srcChainId, address srcContract,
        uint256 indexed srcNonce, address sender, address to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by, string reason);
    event Released(bytes32 indexed id, address indexed to, uint256 amount);
    event Tripped(address indexed who, address indexed by);
    event ThreatsSet(address registry);

    error NotGovernance();
    error NotLane();
    error NotVetoer();
    error NotMarker();
    error NotGuardian();
    error Twice();
    error NotReady();
    error Blocked();
    /// what: 1 source sender, 2 source contract, 3 ZETAPHY recipient (enforced flag)
    error ThreatFlagged(uint8 what);
    /// the same, for a held flag that is not enforced yet: held until it is cleared
    error ThreatHeld(uint8 what);

    constructor(IGuardInbound guard_, bytes32 route_, address governance_, uint8 threshold_, uint64 quarantine_) {
        require(threshold_ >= 2, "need 2+ independent lanes");
        guard = guard_;
        route = route_;
        governance = governance_;
        threshold = threshold_;
        quarantine = quarantine_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setLane(address lane, bool on) external onlyGov {
        if (on && !isLane[lane]) {
            require(lane != address(0) && laneList.length < MAX_LANES, "lane");
            laneList.push(lane);
        } else if (!on && isLane[lane]) {
            for (uint256 i = 0; i < laneList.length; i++) {
                if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
            }
        }
        isLane[lane] = on;
        emit LaneSet(lane, on);
    }
    function setVetoer(address who, bool on) external onlyGov { isVetoer[who] = on; emit VetoerSet(who, on); }
    /// Names (or removes) a marker: typically the bridge monitor's own key, which
    /// holds no other role. Governance removes a lost or misused marker key here.
    /// Removing one lifts its marks, also after a guardian's emergencyRemoveMarker.
    function setMarker(address marker, bool on) external onlyGov {
        if (on != isMarker[marker]) {
            if (on) markerCount += 1;
            else markerCount -= 1;
        }
        isMarker[marker] = on;
        markerRevoked[marker] = false;
        emit MarkerSet(marker, on);
    }
    /// Raising the threshold later does not hold back transfers that already reached the old one.
    function setThreshold(uint8 t) external onlyGov { require(t >= 2, "need 2+"); threshold = t; emit ThresholdSet(t); }
    function setQuarantine(uint64 q) external onlyGov { quarantine = q; emit QuarantineSet(q); }
    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    /// The ThreatRegistry whose flags hold transfers (zero turns the check off).
    function setThreats(IThreatFlags r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }
    /// Governance can lift a mark set by mistake.
    function untrip(address who) external onlyGov { delete trippedBy[who]; emit Untripped(who); }

    // ---- emergency: BridgeGuard's guardians act at once, but only to reduce risk ----
    // Governance is meant to be the ZetaphyTimelock (48 h). Adding a lane or a
    // marker, lowering the threshold or the quarantine, lifting a mark, a new
    // registry or governance all wait that delay. These four only make release
    // harder, so a guardian of the guard (a multisig, BridgeGuard.setGuardian)
    // makes them at once. (A guardian removing a marker stops it from marking
    // but keeps the marks it made: only governance, through setMarker or
    // untrip, lifts marks.)
    uint64 public constant MAX_QUARANTINE = 30 days;

    function emergencyRemoveLane(address lane) external {
        _guardian();
        if (!isLane[lane]) revert NotLane();
        for (uint256 i = 0; i < laneList.length; i++) {
            if (laneList[i] == lane) { laneList[i] = laneList[laneList.length - 1]; laneList.pop(); break; }
        }
        isLane[lane] = false;
        emit LaneSet(lane, false);
    }

    function emergencyRemoveMarker(address marker) external {
        _guardian();
        if (!isMarker[marker]) revert NotMarker();
        isMarker[marker] = false;
        markerRevoked[marker] = true;
        markerCount -= 1;
        emit MarkerSet(marker, false);
    }

    /// More independent lanes must agree (at most MAX_LANES; above the lane count nothing is released).
    function emergencyRaiseThreshold(uint8 t) external {
        _guardian();
        require(t > threshold && t <= MAX_LANES, "raise only");
        threshold = t;
        emit ThresholdSet(t);
    }

    /// A longer quarantine (at most MAX_QUARANTINE), more time to veto.
    function emergencyRaiseQuarantine(uint64 q) external {
        _guardian();
        require(q > quarantine && q <= MAX_QUARANTINE, "raise only");
        quarantine = q;
        emit QuarantineSet(q);
    }

    /// Governance, or a guardian of the guard (a guard without guardian() has none).
    function _guardian() private view {
        if (msg.sender == governance) return;
        (bool ok, bytes memory ret) = address(guard).staticcall(abi.encodeCall(IGuardInbound.guardian, (msg.sender)));
        if (!ok || ret.length < 32 || !abi.decode(ret, (bool))) revert NotGuardian();
    }

    /// Marked by a marker that is still on, or that a guardian removed.
    /// setMarker(m, false) lifts every mark m made (setting m on again would
    /// bring them back).
    function tripped(address who) public view returns (bool) {
        address m = trippedBy[who];
        return m != address(0) && (isMarker[m] || markerRevoked[m]);
    }

    /// The lanes now on.
    function lanes() external view returns (address[] memory) { return laneList; }
    function laneCount() external view returns (uint256) { return laneList.length; }

    /// Who decides what a lane attests: its laneController(), or the lane itself
    /// (a key, or a contract that does not say).
    function laneControllerOf(address lane) public view returns (address) {
        if (lane.code.length == 0) return lane;
        try ILaneInfo(lane).laneController() returns (address c) { return c == address(0) ? lane : c; } catch { return lane; }
    }

    /// Lanes with distinct controllers. BridgeGuard will not enable this
    /// airlock's route while it is below 2: one controller behind two lane
    /// contracts is still one bridge's word.
    function independentLanes() external view returns (uint256 n) {
        uint256 len = laneList.length;
        address[] memory seen = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            address c = laneControllerOf(laneList[i]);
            bool dup = false;
            for (uint256 j = 0; j < n; j++) if (seen[j] == c) { dup = true; break; }
            if (!dup) seen[n++] = c;
        }
    }

    /// The id every lane computes for one transfer seen on the source chain:
    /// the source contract's own running number, not a tx hash or log
    /// position, which can change if the source chain reorganises.
    function transferId(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount)
        public pure returns (bytes32)
    {
        return keccak256(abi.encode(srcChainId, srcContract, srcNonce, sender, to, amount));
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        if (!isLane[msg.sender]) revert NotLane();
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        if (attestedBy[id][msg.sender]) revert Twice();
        attestedBy[id][msg.sender] = true;
        Transfer storage t = transfers[id];
        address c = laneControllerOf(msg.sender);
        if (!attestedByController[id][c]) {
            attestedByController[id][c] = true;
            t.attestations += 1;
        }
        if (t.readyFrom == 0 && t.attestations >= threshold) t.readyFrom = uint64(block.timestamp);
        emit Attested(id, msg.sender, t.attestations, srcChainId, srcContract, srcNonce, sender, to, amount);
    }

    function veto(bytes32 id, string calldata reason) external {
        if (!isVetoer[msg.sender]) revert NotVetoer();
        Transfer storage t = transfers[id];
        if (t.released) revert Blocked();
        t.vetoed = true;
        emit Vetoed(id, msg.sender, reason);
    }

    /// A marker marks `who`: release() then refuses (Blocked) every transfer
    /// whose source sender or ZETAPHY recipient is `who`, until governance
    /// untrips it. That is all a marker can do: it cannot attest, veto,
    /// release, mint, pause or move any funds, and a mark loses nothing (the
    /// transfer stays and comes out once the mark is lifted). So a stolen or
    /// misused marker key can at worst delay some addresses' transfers until
    /// governance removes the marker (setMarker), which lifts all its marks.
    /// A mark that counts is kept by its first marker (another marker's
    /// mark does not replace it).
    function trip(address who) external {
        if (!isMarker[msg.sender]) revert NotMarker();
        if (tripped(who)) return;
        trippedBy[who] = msg.sender;
        emit Tripped(who, msg.sender);
    }

    /// Anyone may release a transfer that passed every check.
    function release(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        bytes32 id = transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        Transfer storage t = transfers[id];
        if (t.released || t.vetoed || tripped(sender) || tripped(to)) revert Blocked();
        if (t.attestations < threshold || t.readyFrom == 0 || block.timestamp < t.readyFrom + quarantine) revert NotReady();
        uint8 what = flaggedParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatFlagged(what);
        what = heldParty(srcChainId, srcContract, sender, to);
        if (what != 0) revert ThreatHeld(what);
        t.released = true;
        guard.inbound(route, to, amount);
        emit Released(id, to, amount);
    }

    /// 0 when no party of this transfer has an enforced flag, else which one
    /// has (see ThreatFlagged). NeuroLane watchers ask this before they attest.
    function flaggedParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, true);
    }

    /// 0 when no party of this transfer is held, else which one is (the
    /// registry's is*Held views: past holdDelay, fast lane or holdNow). A
    /// transfer with a held party is not released; NeuroLane watchers ask this
    /// before they release.
    function heldParty(uint256 srcChainId, address srcContract, address sender, address to) public view returns (uint8) {
        return _party(srcChainId, srcContract, sender, to, false);
    }

    function _party(uint256 srcChainId, address srcContract, address sender, address to, bool enforced) private view returns (uint8) {
        IThreatFlags r = threats;
        if (address(r) == address(0)) return 0;
        bool f;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, sender) : r.isAddressHeld(srcChainId, sender);
        if (f) return 1;
        (f, ) = enforced ? r.isAddressEnforced(srcChainId, srcContract) : r.isAddressHeld(srcChainId, srcContract);
        if (f) return 2;
        (f, ) = enforced ? r.isContractEnforced(to) : r.isContractHeld(to);
        if (f) return 3;
        return 0;
    }

    function status(bytes32 id) external view returns (uint8 attestations, bool released, bool vetoed, uint64 readyAt) {
        Transfer storage t = transfers[id];
        return (t.attestations, t.released, t.vetoed, t.readyFrom == 0 ? 0 : t.readyFrom + quarantine);
    }
}

/// @title NeuroLane: Neuro runners as one of the airlock's bridges
/// @notice Runners watch the source chain's LockBox and each attest the
///         transfers they see. When `quorum` distinct proven runners attest
///         the same transfer, this lane attests it to the airlock. Runners
///         can also vote to veto a transfer still in quarantine.
///         While Neuro is paused (NeuroControl, if set) nothing is attested;
///         vetoes still work, since holding money back is always safe.
contract NeuroLane {
    IRunnerRecords public immutable runners;
    BridgeAirlock public immutable airlock;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    INeuroControl public immutable control; // zero: no pause check

    mapping(bytes32 => uint8) public votes;
    mapping(bytes32 => mapping(address => bool)) public votedBy;
    mapping(bytes32 => bool) public done;

    event RunnerAttested(bytes32 indexed id, address indexed runner, uint8 votes);

    /// The runner records decide what this lane attests (BridgeAirlock.independentLanes).
    function laneController() external view returns (address) { return address(runners); }
    event RunnerVetoVote(bytes32 indexed id, address indexed runner, uint8 votes);

    error NotRunner();
    error Twice();
    error NeuroPaused();

    constructor(IRunnerRecords runners_, BridgeAirlock airlock_, uint8 quorum_, uint32 minAgreed_, INeuroControl control_) {
        require(quorum_ >= 2, "quorum");
        runners = runners_;
        airlock = airlock_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        control = control_;
    }

    function _runner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external {
        _runner();
        if (address(control) != address(0) && control.paused()) revert NeuroPaused();
        bytes32 id = airlock.transferId(srcChainId, srcContract, srcNonce, sender, to, amount);
        bytes32 key = keccak256(abi.encode("attest", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerAttested(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.attest(srcChainId, srcContract, srcNonce, sender, to, amount);
        }
    }

    function voteVeto(bytes32 id, string calldata reason) external {
        _runner();
        bytes32 key = keccak256(abi.encode("veto", id));
        if (votedBy[key][msg.sender] || done[key]) revert Twice();
        votedBy[key][msg.sender] = true;
        uint8 v = ++votes[key];
        emit RunnerVetoVote(id, msg.sender, v);
        if (v >= quorum) {
            done[key] = true;
            airlock.veto(id, reason);
        }
    }
}

/// @title LockBox: the source-chain side of the Neuro lane (test / testnet)
/// @notice Locks native coin and emits what the lanes need to attest. Lanes
///         attest (chainid, this contract, nonce, sender, to, amount).
contract LockBox {
    uint256 public nonce;
    event Locked(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount);

    function lock(address to) external payable {
        require(msg.value > 0 && to != address(0), "lock");
        emit Locked(nonce++, msg.sender, to, msg.value);
    }
}

contracts/BridgeGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// ThreatRegistry's hold view for code on ZETAPHY (Reason as its uint8 value):
/// true once a flag on its address or code is the registry's holdDelay old, or at
/// once through the registry's fast lane or a guardian's holdNow.
interface IContractThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// BridgeAirlock's count of lanes with distinct controllers.
interface IIndependentLanes {
    function independentLanes() external view returns (uint256);
}

/// @title BridgedToken: a token that exists on ZETAPHY only through a bridge
/// @notice Only its BridgeGuard can mint (assets arriving) or burn (leaving).
contract BridgedToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    address public immutable guard;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory n, string memory s, uint8 d, address guard_) {
        name = n; symbol = s; decimals = d; guard = guard_;
    }

    modifier onlyGuard() { require(msg.sender == guard, "only guard"); _; }

    function mint(address to, uint256 v) external onlyGuard { totalSupply += v; balanceOf[to] += v; emit Transfer(address(0), to, v); }
    function burn(address from, uint256 v) external onlyGuard {
        require(balanceOf[from] >= v, "balance");
        balanceOf[from] -= v; totalSupply -= v; emit Transfer(from, address(0), v);
    }
    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v); return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v; balanceOf[to] += v; emit Transfer(f, to, v);
    }
}

/// @title BridgeGuard: limits and a stop button for every bridge route (stage 3)
/// @notice A bridge adapter (Hyperlane warp route, IBC hook, ...) never mints
///         or burns directly: it asks this guard, which enforces
///           - a daily limit per route and direction, so a hacked bridge can
///             lose at most one day's limit, not everything;
///           - a pause that only guardians can pull and only governance can
///             release. Pausing stops the bridges, never the chain.
///           - vaccine (with a ThreatRegistry set): no coins to, or out of, an
///             address or contract the registry holds (is*Held: a flag that is
///             holdDelay old, e.g. 10 minutes, or held at once by the fast lane or
///             a guardian's holdNow; two runners alone cannot freeze anyone at
///             once). This is a hold, not a loss:
///               - inbound: the mint is QUEUED, not reverted (InboundHeld, an id
///                 in `held`). The adapter's message is delivered, so nothing
///                 depends on an adapter retrying. Anyone calls releaseHeld(id)
///                 once the hold ends (the flag cleared, or governance protects
///                 the key); it then passes the pause, the route (still enabled)
///                 and the route's daily limit like any inbound. Governance can
///                 dropHeld(id) a queued mint (e.g. from a hacked adapter).
///               - outbound: the call reverts (the burn simply did not happen;
///                 the holder keeps the coins).
///             The adapter itself is NOT checked: governance chose it and can
///             disable its route; a runner flag on its code hash or address must
///             not be able to freeze a whole route.
///         Opening gates (a route stays closed until they hold):
///           - an audit on record: setAudit(https url, sha256 of the report)
///             before any route can be enabled;
///           - the route's adapter is a BridgeAirlock with at least 2 lanes
///             whose controllers differ (independentLanes() >= 2);
///           - a hard cap, maxDailyLimit, over every route's daily limit and over all routes together per day. It
///             starts at 1,000 whole tokens (createToken), is lowered at once,
///             and is raised only by governance, at most x2 per step (or back up
///             to the cap before a lowerMaxDailyLimit cut), each step 7 days after
///             it was proposed: caps grow gradually and in public.
///         Outbound-only routes (setOutboundRoute): an adapter that only burns, e.g. a
///         HyperlaneOutbox sending the token back to its source chain. inbound() refuses
///         such a route, so it never mints and needs no airlock; enabling it still needs the
///         audit on record and a daily limit within the hard cap. An id is either kind, for good.
///         Governance should be the ZetaphyTimelock (proposers: the chain's gov
///         module or a multisig). Guardians act at once, but only to reduce risk:
///         pause, lowerMaxDailyLimit, cancelMaxDailyLimit, disableRoute.
contract BridgeGuard {
    struct Route {
        address adapter;      // the only caller allowed for this route
        uint128 dailyLimit;   // per direction, in token units
        uint128 inToday;
        uint128 outToday;
        uint64 day;
        bool enabled;
    }

    BridgedToken public token;
    address public governance;
    mapping(address => bool) public guardian;
    bool public paused;
    mapping(bytes32 => Route) public routes;
    IContractThreats public threats; // zero: no vaccine check
    address[] private guardianList;  // everyone ever made a guardian (guardians() filters the current ones)

    /// The audit the bridge opened on: where to read it and the sha256 of the report.
    string public auditUrl;
    bytes32 public auditSha256;
    /// Hard cap over every route's daily limit (token units).
    uint128 public maxDailyLimit;
    uint128 public pendingMaxDailyLimit;
    uint64 public pendingMaxAt;      // when the pending raise may be applied (0: none)
    uint64 public constant CAP_DELAY = 7 days;
    /// The highest cap before lowerMaxDailyLimit cut it (0: none). Governance may
    /// propose a raise back up to it in one step (still CAP_DELAY), so a guardian's
    /// emergency cut (even to 0) is never undone only by x2 steps of 7 days each.
    uint128 public restoreMaxDailyLimit;
    uint128 public constant STARTER_UNITS = 1000; // whole tokens: the cap at createToken
    /// Every route together, per direction and day: the hard cap binds the
    /// guard, so more routes cannot multiply it.
    uint128 public totalInToday;
    uint128 public totalOutToday;
    uint64 public totalDay;

    /// Inbound mints held by the vaccine, waiting for releaseHeld.
    struct HeldMint {
        bytes32 route;
        address to;
        uint256 amount;
        bool done;       // released or dropped
    }
    HeldMint[] public held;
    /// Routes that only burn (setOutboundRoute): inbound() refuses them.
    mapping(bytes32 => bool) public outboundOnly;

    event RouteSet(bytes32 indexed id, address adapter, uint128 dailyLimit, bool enabled);
    event GovernanceSet(address governance);
    event AuditSet(string url, bytes32 sha256);
    event MaxDailyLimitProposed(uint128 value, uint64 at);
    event MaxDailyLimitSet(uint128 value);
    event MaxDailyLimitCancelled();
    event GuardianSet(address indexed who, bool allowed);
    event Paused(address indexed by);
    event Unpaused();
    event Inbound(bytes32 indexed route, address indexed to, uint256 amount);
    event Outbound(bytes32 indexed route, address indexed from, uint256 amount);
    event ThreatsSet(address registry);
    event InboundHeld(uint256 indexed id, bytes32 indexed route, address indexed to, uint256 amount);
    event HeldReleased(uint256 indexed id, address indexed to, uint256 amount);
    event HeldDropped(uint256 indexed id);
    event OutboundOnly(bytes32 indexed id);

    error NotGovernance();
    error NotGuardian();
    error NotAdapter();
    error BridgePaused();
    error OverLimit(uint256 remaining);
    error FlaggedContract(address who);
    error NoHeld();
    error AuditMissing();
    error NeedLanes(uint256 independent);
    error OverCap(uint128 cap);
    error CapStep(uint128 most);
    error TooEarly(uint64 at);
    error NoPending();
    error RouteKind();

    constructor(address governance_) {
        governance = governance_;
    }

    /// One-time: the guard deploys and owns its token.
    function createToken(string calldata n, string calldata s, uint8 d) external returns (BridgedToken) {
        if (msg.sender != governance) revert NotGovernance();
        require(address(token) == address(0), "token exists");
        require(d <= 30, "decimals");
        token = new BridgedToken(n, s, d, address(this));
        maxDailyLimit = uint128(uint256(STARTER_UNITS) * (uint256(10) ** d));
        emit MaxDailyLimitSet(maxDailyLimit);
        return token;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool allowed) external onlyGov {
        if (allowed && !guardian[who]) {
            bool known = false;
            for (uint256 i = 0; i < guardianList.length; i++) if (guardianList[i] == who) { known = true; break; }
            if (!known) { require(guardianList.length < 32, "guardians"); guardianList.push(who); }
        }
        guardian[who] = allowed;
        emit GuardianSet(who, allowed);
    }

    /// The current guardians.
    function guardians() external view returns (address[] memory out) {
        uint256 n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) n++;
        out = new address[](n);
        n = 0;
        for (uint256 i = 0; i < guardianList.length; i++) if (guardian[guardianList[i]]) out[n++] = guardianList[i];
    }

    /// The audit report the bridge opens on (an https url and the report's sha256).
    function setAudit(string calldata url, bytes32 sha) external onlyGov {
        bytes memory u = bytes(url);
        require(sha != bytes32(0) && u.length > 8 && u.length <= 200 && u[0] == "h" && u[1] == "t" && u[2] == "t" && u[3] == "p"
            && u[4] == "s" && u[5] == ":" && u[6] == "/" && u[7] == "/", "audit: https url and sha256");
        auditUrl = url;
        auditSha256 = sha;
        emit AuditSet(url, sha);
    }

    /// Lowering the cap applies at once (and cancels a pending raise); a raise
    /// (at most x2 of the cap, or up to restoreMaxDailyLimit) waits CAP_DELAY,
    /// then anyone applies it.
    function proposeMaxDailyLimit(uint128 v) external onlyGov {
        if (v <= maxDailyLimit) {
            maxDailyLimit = v;
            pendingMaxAt = 0;
            pendingMaxDailyLimit = 0;
            emit MaxDailyLimitSet(v);
            return;
        }
        uint256 most = uint256(maxDailyLimit) * 2;
        if (restoreMaxDailyLimit > most) most = restoreMaxDailyLimit;
        if (v > most) revert CapStep(uint128(most));
        pendingMaxDailyLimit = v;
        pendingMaxAt = uint64(block.timestamp) + CAP_DELAY;
        emit MaxDailyLimitProposed(v, pendingMaxAt);
    }

    function applyMaxDailyLimit() external {
        uint64 at = pendingMaxAt;
        if (at == 0) revert NoPending();
        if (block.timestamp < at) revert TooEarly(at);
        maxDailyLimit = pendingMaxDailyLimit;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        if (maxDailyLimit >= restoreMaxDailyLimit) restoreMaxDailyLimit = 0;
        emit MaxDailyLimitSet(maxDailyLimit);
    }

    /// Governance or a guardian: drop a pending raise (reducing risk never waits).
    function cancelMaxDailyLimit() external {
        _govOrGuardian();
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitCancelled();
    }

    // ---- emergency: guardians act at once, but only to reduce risk ----
    // With governance behind a timelock (ZetaphyTimelock, 48 h), everything that
    // raises risk or changes rules (enable a route, raise a cap, unpause, new
    // guardians, audit, registry, governance) waits the delay. These calls only
    // shrink what can cross, so a guardian (a multisig) makes them at once.

    /// Lower the hard cap (never raise it) and drop a pending raise.
    function lowerMaxDailyLimit(uint128 v) external {
        _govOrGuardian();
        if (v >= maxDailyLimit) revert CapStep(maxDailyLimit);
        if (maxDailyLimit > restoreMaxDailyLimit) restoreMaxDailyLimit = maxDailyLimit;
        maxDailyLimit = v;
        pendingMaxAt = 0;
        pendingMaxDailyLimit = 0;
        emit MaxDailyLimitSet(v);
    }

    /// Close a route (its adapter and limit are kept; enabling it again is governance's).
    function disableRoute(bytes32 id) external {
        _govOrGuardian();
        Route storage r = routes[id];
        r.enabled = false;
        emit RouteSet(id, r.adapter, r.dailyLimit, false);
    }

    function _govOrGuardian() private view {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
    }
    /// The ThreatRegistry whose flags refuse coins (zero turns the check off).
    function setThreats(IContractThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Enabling needs the audit on record, a daily limit within the hard cap and
    /// an adapter that is a BridgeAirlock with 2+ independent lanes. Disabling (or
    /// setting a closed route up) needs none of them: closing always works.
    function setRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        if (outboundOnly[id]) revert RouteKind();
        if (enabled) {
            if (dailyLimit > maxDailyLimit) revert OverCap(maxDailyLimit);
            if (auditSha256 == bytes32(0)) revert AuditMissing();
            uint256 n = _independentLanes(adapter);
            if (n < 2) revert NeedLanes(n);
        }
        Route storage r = routes[id];
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// An outbound-only route: its adapter may only burn (outbound); inbound() refuses it.
    /// Enabling needs the audit on record and a daily limit within the hard cap, and an
    /// adapter that is a contract; an id used by an inbound route is refused (RouteKind).
    function setOutboundRoute(bytes32 id, address adapter, uint128 dailyLimit, bool enabled) external onlyGov {
        Route storage r = routes[id];
        if (!outboundOnly[id]) {
            if (r.adapter != address(0)) revert RouteKind();
            outboundOnly[id] = true;
            emit OutboundOnly(id);
        }
        if (enabled) {
            if (dailyLimit > maxDailyLimit) revert OverCap(maxDailyLimit);
            if (auditSha256 == bytes32(0)) revert AuditMissing();
            if (adapter.code.length == 0) revert NotAdapter();
        }
        r.adapter = adapter;
        r.dailyLimit = dailyLimit;
        r.enabled = enabled;
        emit RouteSet(id, adapter, dailyLimit, enabled);
    }

    /// Any guardian (or governance) can stop all bridges at once.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    /// Restarting needs governance: a stolen guardian key can only stop things.
    function unpause() external onlyGov {
        paused = false;
        emit Unpaused();
    }

    /// A held recipient: the mint is queued (InboundHeld), not reverted, and
    /// counts against the daily limit only when it is released.
    function inbound(bytes32 id, address to, uint256 amount) external {
        Route storage r = _use(id, amount, true);
        if (_isHeld(to)) {
            held.push(HeldMint(id, to, amount, false));
            emit InboundHeld(held.length - 1, id, to, amount);
            return;
        }
        _total(amount, true);
        r.inToday += uint128(amount);
        token.mint(to, amount);
        emit Inbound(id, to, amount);
    }

    /// Anyone: mint a queued inbound once its recipient is no longer held.
    /// Passes the pause, the route being enabled and its daily limit, as inbound does.
    function releaseHeld(uint256 hid) external {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        HeldMint storage h = held[hid];
        if (paused) revert BridgePaused();
        Route storage r = routes[h.route];
        if (!r.enabled || outboundOnly[h.route]) revert NotAdapter();
        _clean(h.to);
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint128 lim = _limit(r);
        if (r.inToday + h.amount > lim) revert OverLimit(lim > r.inToday ? lim - r.inToday : 0);
        _total(h.amount, true);
        h.done = true;
        r.inToday += uint128(h.amount);
        token.mint(h.to, h.amount);
        emit HeldReleased(hid, h.to, h.amount);
        emit Inbound(h.route, h.to, h.amount);
    }

    /// Governance drops a queued mint (e.g. one a hacked adapter sent).
    function dropHeld(uint256 hid) external onlyGov {
        if (hid >= held.length || held[hid].done) revert NoHeld();
        held[hid].done = true;
        emit HeldDropped(hid);
    }

    function heldCount() external view returns (uint256) {
        return held.length;
    }

    function outbound(bytes32 id, address from, uint256 amount) external {
        Route storage r = _use(id, amount, false);
        _clean(from);
        _total(amount, false);
        r.outToday += uint128(amount);
        token.burn(from, amount);
        emit Outbound(id, from, amount);
    }

    function remaining(bytes32 id) external view returns (uint256 inLeft, uint256 outLeft) {
        Route storage r = routes[id];
        bool fresh = r.day != uint64(block.timestamp / 1 days);
        uint128 lim = _limit(r);
        uint128 i = fresh ? 0 : r.inToday;
        uint128 o = fresh ? 0 : r.outToday;
        inLeft = lim > i ? lim - i : 0;
        outLeft = lim > o ? lim - o : 0;
    }

    /// A route's daily limit, never above the hard cap.
    function _limit(Route storage r) private view returns (uint128) {
        return r.dailyLimit < maxDailyLimit ? r.dailyLimit : maxDailyLimit;
    }

    /// The hard cap over all routes together (per direction, per day).
    function _total(uint256 amount, bool isIn) private {
        uint64 today = uint64(block.timestamp / 1 days);
        if (totalDay != today) { totalDay = today; totalInToday = 0; totalOutToday = 0; }
        uint256 used = isIn ? totalInToday : totalOutToday;
        uint256 cap = maxDailyLimit;
        if (used + amount > cap) revert OverLimit(cap > used ? cap - used : 0);
        if (isIn) totalInToday = uint128(used + amount); else totalOutToday = uint128(used + amount);
    }

    function _independentLanes(address adapter) private view returns (uint256) {
        if (adapter.code.length == 0) return 0;
        (bool ok, bytes memory ret) = adapter.staticcall(abi.encodeCall(IIndependentLanes.independentLanes, ()));
        if (!ok || ret.length < 32) return 0;
        return abi.decode(ret, (uint256));
    }

    /// Vaccine: holds back a party (the coins' owner) that the registry holds.
    function _clean(address who) private view {
        if (_isHeld(who)) revert FlaggedContract(who);
    }

    function _isHeld(address who) private view returns (bool f) {
        IContractThreats t = threats;
        if (address(t) == address(0)) return false;
        (f, ) = t.isContractHeld(who);
    }

    function _use(bytes32 id, uint256 amount, bool isIn) private returns (Route storage r) {
        if (paused) revert BridgePaused();
        r = routes[id];
        if (!r.enabled || msg.sender != r.adapter || (isIn && outboundOnly[id])) revert NotAdapter();
        uint64 today = uint64(block.timestamp / 1 days);
        if (r.day != today) { r.day = today; r.inToday = 0; r.outToday = 0; }
        uint256 used = isIn ? r.inToday : r.outToday;
        uint256 lim = _limit(r);
        if (used + amount > lim) revert OverLimit(lim > used ? lim - used : 0);
    }
}

contracts/BugBounty.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IBBRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IBBReputation {
    function record(address worker, uint8 kind, bytes32 ref) external;
}

interface IBBIssuance {
    function draw(uint256 amount) external returns (uint256 paid);
}

/// @title BugBounty: bug-hunting jobs for browsers, paid after runners verify
/// @notice A sponsor posts a bounty on a testnet contract: the hash of a fuzz SPEC (the
///         contract's init code, the functions to call, the setup, and the invariant, e.g.
///         "the attacker must not end with more than it started"; see
///         zetaphy-hub/bounties/*.json) and a reward. Browsers fuzz the contract in an
///         in-memory EVM (the same EthereumJS EVM the contract tests use) and, on a finding:
///           1. `commitFinding`: keccak(findingHash, finder, salt, bountyId) and a deposit.
///              Findings are numbered in commit order, so whoever committed first is first;
///              watching someone's reveal cannot help a copier, whose commit is later.
///           2. `revealFinding` (a later block, within `revealWindow`): the finding itself
///              (the call sequence) is calldata of this transaction and in the event, so the
///              runners need no server to read it.
///           3. Bonded NeuroJobs runners with a track record (the bar ThreatRegistry uses:
///              active, at least `minAgreed` accepted verdicts, no more rejected than
///              accepted) replay it against the spec (`zetaphy bounty verify`) and `attest`.
///              `quorum` matching attestations accept or reject it.
///           4. `claim`: the earliest accepted finding (every earlier one rejected or never
///              revealed) gets the reward, plus the bounty's subsidy from UsefulIssuance, plus
///              its deposit back. Later accepted duplicates get their deposit back.
///         A rejected finding's deposit goes to the bounty's reward. Outcomes feed
///         WorkerReputation (bugValid / bugInvalid). Governance only sets the subsidy of a
///         bounty and the deposit; it cannot take a bounty's reward, which only goes to a
///         verified finding or back to the sponsor after the bounty ended.
contract BugBounty {
    uint8 internal constant BUG_VALID = 4;
    uint8 internal constant BUG_INVALID = 5;
    uint256 public constant MAX_FINDINGS = 32;

    enum State { None, Committed, Revealed, Accepted, Rejected, Paid, Closed }

    struct Bounty {
        address sponsor;
        uint64 deadline;     // last moment to commit a finding
        bool paid;
        bool refunded;
        uint128 reward;
        uint128 subsidy;     // drawn from UsefulIssuance on payout (set by governance)
        bytes32 specHash;    // keccak256 of the spec file
        string specURI;
        uint256[] findings;
    }

    struct Finding {
        uint256 bounty;
        address finder;
        uint64 committedAt;
        uint64 commitBlock;
        uint64 revealedAt;
        State state;
        uint8 yes;
        uint8 no;
        uint128 deposit;
        bytes32 commitment;
        bytes32 findingHash;
    }

    IBBRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    address public governance;
    IBBReputation public reputation;
    IBBIssuance public issuance;
    uint128 public findingDeposit;
    uint32 public revealWindow;
    uint32 public judgeWindow;

    Bounty[] private _bounties;
    Finding[] private _findings;
    mapping(uint256 => mapping(address => bool)) public attested;
    mapping(address => uint256) public owed;

    event BountyPosted(uint256 indexed id, address indexed sponsor, bytes32 specHash, string specURI, uint256 reward, uint64 deadline);
    event SubsidySet(uint256 indexed id, uint256 subsidy);
    event FindingCommitted(uint256 indexed findingId, uint256 indexed bounty, address indexed finder);
    event FindingRevealed(uint256 indexed findingId, uint256 indexed bounty, address indexed finder, bytes finding);
    event Attested(uint256 indexed findingId, address indexed runner, bool valid);
    event FindingJudged(uint256 indexed findingId, bool valid);
    event BountyPaid(uint256 indexed id, uint256 indexed findingId, address indexed finder, uint256 amount);
    event BountyRefunded(uint256 indexed id, uint256 amount);
    event Withdrawn(address indexed to, uint256 amount);

    error NotGovernance();
    error NotRunner();
    error BadValue();
    error BadBounty();
    error BadFinding();
    error Closed();
    error TooEarly();
    error TooMany();
    error BadReveal();
    error AlreadyVoted();
    error Nothing();

    constructor(IBBRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_, IBBReputation reputation_,
        IBBIssuance issuance_, uint128 findingDeposit_, uint32 revealWindow_, uint32 judgeWindow_)
    {
        if (quorum_ == 0 || revealWindow_ == 0 || judgeWindow_ == 0) revert BadValue();
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
        reputation = reputation_;
        issuance = issuance_;
        findingDeposit = findingDeposit_;
        revealWindow = revealWindow_;
        judgeWindow = judgeWindow_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    /// UsefulIssuance.draw pays through here.
    receive() external payable {}

    // ---------------------------------------------------------------- bounties

    function post(bytes32 specHash, string calldata specURI, uint64 duration) external payable returns (uint256 id) {
        if (msg.value == 0 || specHash == bytes32(0) || duration == 0 || bytes(specURI).length > 256) revert BadValue();
        id = _bounties.length;
        Bounty storage b = _bounties.push();
        b.sponsor = msg.sender;
        b.deadline = uint64(block.timestamp + duration);
        b.reward = uint128(msg.value);
        b.specHash = specHash;
        b.specURI = specURI;
        emit BountyPosted(id, msg.sender, specHash, specURI, msg.value, b.deadline);
    }

    function setSubsidy(uint256 id, uint128 subsidy) external onlyGovernance {
        _bounty(id).subsidy = subsidy;
        emit SubsidySet(id, subsidy);
    }

    function setFindingDeposit(uint128 d) external onlyGovernance {
        findingDeposit = d;
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
    }

    // ---------------------------------------------------------------- findings

    /// keccak(abi.encode(findingHash, finder, salt, bountyId)): bound to the finder, so a copy is useless.
    function commitmentOf(bytes32 findingHash, address finder, bytes32 salt, uint256 bountyId) public pure returns (bytes32) {
        return keccak256(abi.encode(findingHash, finder, salt, bountyId));
    }

    function commitFinding(uint256 bountyId, bytes32 commitment) external payable returns (uint256 fid) {
        Bounty storage b = _bounty(bountyId);
        if (b.paid || b.refunded || block.timestamp > b.deadline) revert Closed();
        if (msg.value != findingDeposit || commitment == bytes32(0)) revert BadValue();
        if (b.findings.length >= MAX_FINDINGS) revert TooMany();
        fid = _findings.length;
        _findings.push(Finding({
            bounty: bountyId, finder: msg.sender, committedAt: uint64(block.timestamp), commitBlock: uint64(block.number),
            revealedAt: 0, state: State.Committed, yes: 0, no: 0, deposit: uint128(msg.value), commitment: commitment, findingHash: bytes32(0)
        }));
        b.findings.push(fid);
        emit FindingCommitted(fid, bountyId, msg.sender);
    }

    function revealFinding(uint256 fid, bytes calldata finding, bytes32 salt) external {
        Finding storage f = _finding(fid);
        if (msg.sender != f.finder) revert BadFinding();
        if (f.state != State.Committed) revert Closed();
        if (block.number <= f.commitBlock) revert TooEarly();
        if (block.timestamp > f.committedAt + revealWindow) revert Closed();
        bytes32 h = keccak256(finding);
        if (commitmentOf(h, msg.sender, salt, f.bounty) != f.commitment) revert BadReveal();
        f.findingHash = h;
        f.revealedAt = uint64(block.timestamp);
        f.state = State.Revealed;
        emit FindingRevealed(fid, f.bounty, msg.sender, finding);
    }

    /// A proven runner's verdict on a revealed finding (it replayed it against the spec).
    function attest(uint256 fid, bool valid) external {
        Finding storage f = _finding(fid);
        if (f.state != State.Revealed) revert Closed();
        if (block.timestamp > f.revealedAt + judgeWindow) revert Closed();
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed || msg.sender == f.finder) revert NotRunner();
        if (attested[fid][msg.sender]) revert AlreadyVoted();
        attested[fid][msg.sender] = true;
        emit Attested(fid, msg.sender, valid);
        if (valid) f.yes++;
        else f.no++;
        if (f.yes >= quorum) {
            f.state = State.Accepted;
            emit FindingJudged(fid, true);
            _rep(f.finder, BUG_VALID, fid);
        } else if (f.no >= quorum) {
            f.state = State.Rejected;
            _bounties[f.bounty].reward += f.deposit; // the deposit of a wrong finding grows the reward
            emit FindingJudged(fid, false);
            _rep(f.finder, BUG_INVALID, fid);
        }
    }

    /// Pays an accepted finding: the reward if it is the earliest valid one, else its deposit.
    function claim(uint256 fid) external {
        Finding storage f = _finding(fid);
        if (f.state != State.Accepted) revert Closed();
        Bounty storage b = _bounties[f.bounty];
        f.state = State.Paid;
        if (b.paid || b.refunded) {
            owed[f.finder] += f.deposit; // a later duplicate: its deposit back
            return;
        }
        for (uint256 i = 0; i < b.findings.length; i++) {
            uint256 other = b.findings[i];
            if (other == fid) break;
            if (!_settledOut(_findings[other])) revert TooEarly(); // an earlier finding is still open
        }
        b.paid = true;
        uint256 amount = b.reward;
        if (b.subsidy > 0 && address(issuance) != address(0)) {
            uint256 before = address(this).balance;
            try issuance.draw(b.subsidy) returns (uint256) {} catch {}
            amount += address(this).balance - before;
        }
        owed[f.finder] += amount + f.deposit;
        emit BountyPaid(f.bounty, fid, f.finder, amount);
    }

    /// After the judging window: an unjudged finding's deposit goes back (runners did not
    /// decide in time), and an unrevealed one is closed (its deposit grows the reward).
    function close(uint256 fid) external {
        Finding storage f = _finding(fid);
        if (f.state == State.Committed) {
            if (block.timestamp <= f.committedAt + revealWindow) revert TooEarly();
            _bounties[f.bounty].reward += f.deposit;
        } else if (f.state == State.Revealed) {
            if (block.timestamp <= f.revealedAt + judgeWindow) revert TooEarly();
            owed[f.finder] += f.deposit;
        } else {
            revert Closed();
        }
        f.state = State.Closed;
    }

    /// The sponsor takes an unpaid reward back once nobody can still win it.
    function refund(uint256 bountyId) external {
        Bounty storage b = _bounty(bountyId);
        if (b.paid || b.refunded) revert Closed();
        if (block.timestamp <= uint256(b.deadline) + revealWindow + judgeWindow) revert TooEarly();
        for (uint256 i = 0; i < b.findings.length; i++) {
            State s = _findings[b.findings[i]].state;
            if (s == State.Accepted) revert TooEarly(); // a winner can still claim
        }
        b.refunded = true;
        owed[b.sponsor] += b.reward;
        emit BountyRefunded(bountyId, b.reward);
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: a}("");
        if (!ok) revert Nothing();
        emit Withdrawn(msg.sender, a);
    }

    // ---------------------------------------------------------------- reads

    function bountyCount() external view returns (uint256) {
        return _bounties.length;
    }

    function getBounty(uint256 id) external view returns (Bounty memory) {
        return _bounty(id);
    }

    function findingCount() external view returns (uint256) {
        return _findings.length;
    }

    function getFinding(uint256 fid) external view returns (Finding memory) {
        return _finding(fid);
    }

    // ---------------------------------------------------------------- internals

    function _bounty(uint256 id) internal view returns (Bounty storage) {
        if (id >= _bounties.length) revert BadBounty();
        return _bounties[id];
    }

    function _finding(uint256 fid) internal view returns (Finding storage) {
        if (fid >= _findings.length) revert BadFinding();
        return _findings[fid];
    }

    function _settledOut(Finding storage f) internal view returns (bool) {
        if (f.state == State.Rejected || f.state == State.Closed) return true;
        // committed and never revealed in time: out, even before anyone calls close()
        return f.state == State.Committed && block.timestamp > f.committedAt + revealWindow;
    }

    function _rep(address w, uint8 kind, uint256 fid) internal {
        if (address(reputation) == address(0)) return;
        try reputation.record(w, kind, bytes32(fid)) {} catch {}
    }
}

contracts/ComputeMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunnersView {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// @title ComputeMarket: pay node runners in ZETAPHY for AI work (stage 4)
/// @notice Model output (tier 2+) is not deterministic, so it cannot be
///         settled by 2-of-3 agreement like Neuro tier 1. Instead: escrow.
///         The requester pays up front; a runner with a NeuroJobs track
///         record takes the task and delivers a result (hash + URI); the
///         requester accepts or rejects within REVIEW. Silence pays the
///         runner. Both sides' reject counts are public, so runners can avoid
///         requesters who reject everything, and requesters can avoid runners
///         who deliver junk.
contract ComputeMarket {
    uint64 public constant REVIEW = 1 days;

    enum Status { None, Open, Taken, Delivered, Paid, Refunded }

    struct Task {
        address requester;
        address runner;
        Status status;
        uint64 deadline;     // delivery due
        uint64 deliveredAt;
        bytes32 model;       // e.g. "llama-3.1-8b-instruct-q4"
        bytes32 inputHash;
        bytes32 resultHash;
        uint256 price;
        string inputURI;
        string resultURI;
    }

    IRunnersView public immutable runners;
    uint32 public immutable minAgreed;
    Task[] internal tasks;
    mapping(address => uint256) public credit;
    mapping(address => uint32) public runnerDone;
    mapping(address => uint32) public runnerRejected;
    mapping(address => uint32) public requesterRejections;

    event Requested(uint256 indexed id, bytes32 indexed model, uint256 price, uint64 deadline);
    event Taken(uint256 indexed id, address indexed runner);
    event Delivered(uint256 indexed id, bytes32 resultHash, string resultURI);
    event Settled(uint256 indexed id, Status status);

    error BadValue();
    error BadState();
    error NotAllowed();
    error TooEarly();
    error Nothing();

    constructor(IRunnersView runners_, uint32 minAgreed_) {
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function request(bytes32 model, bytes32 inputHash, string calldata inputURI, uint64 seconds_) external payable returns (uint256 id) {
        if (msg.value == 0 || model == bytes32(0) || seconds_ == 0 || seconds_ > 7 days || bytes(inputURI).length > 256) revert BadValue();
        id = tasks.length;
        Task storage t = tasks.push();
        t.requester = msg.sender;
        t.status = Status.Open;
        t.deadline = uint64(block.timestamp) + seconds_;
        t.model = model;
        t.inputHash = inputHash;
        t.inputURI = inputURI;
        t.price = msg.value;
        emit Requested(id, model, msg.value, t.deadline);
    }

    function take(uint256 id) external {
        Task storage t = _task(id, Status.Open);
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed || msg.sender == t.requester) revert NotAllowed();
        if (block.timestamp >= t.deadline) revert BadState();
        t.runner = msg.sender;
        t.status = Status.Taken;
        emit Taken(id, msg.sender);
    }

    function deliver(uint256 id, bytes32 resultHash, string calldata resultURI) external {
        Task storage t = _task(id, Status.Taken);
        if (msg.sender != t.runner) revert NotAllowed();
        if (block.timestamp > t.deadline || resultHash == bytes32(0) || bytes(resultURI).length > 256) revert BadValue();
        t.resultHash = resultHash;
        t.resultURI = resultURI;
        t.deliveredAt = uint64(block.timestamp);
        t.status = Status.Delivered;
        emit Delivered(id, resultHash, resultURI);
    }

    function accept(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        _pay(id, t);
    }

    function reject(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (msg.sender != t.requester) revert NotAllowed();
        if (block.timestamp > t.deliveredAt + REVIEW) revert BadState();
        runnerRejected[t.runner] += 1;
        requesterRejections[t.requester] += 1;
        _refund(id, t);
    }

    /// The runner is paid once the review window passes without a rejection.
    function claim(uint256 id) external {
        Task storage t = _task(id, Status.Delivered);
        if (block.timestamp <= t.deliveredAt + REVIEW) revert TooEarly();
        _pay(id, t);
    }

    /// Requester gets the money back if nobody took the task, or nothing was delivered in time.
    function cancel(uint256 id) external {
        if (id >= tasks.length) revert BadState();
        Task storage t = tasks[id];
        if (msg.sender != t.requester) revert NotAllowed();
        bool open = t.status == Status.Open;
        bool late = t.status == Status.Taken && block.timestamp > t.deadline;
        if (!open && !late) revert BadState();
        _refund(id, t);
    }

    function withdraw() external {
        uint256 a = credit[msg.sender];
        if (a == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        require(ok, "transfer failed");
    }

    function taskCount() external view returns (uint256) { return tasks.length; }

    function getTask(uint256 id) external view returns (Task memory) {
        if (id >= tasks.length) revert BadState();
        return tasks[id];
    }

    function _task(uint256 id, Status want) private view returns (Task storage t) {
        if (id >= tasks.length) revert BadState();
        t = tasks[id];
        if (t.status != want) revert BadState();
    }

    function _pay(uint256 id, Task storage t) private {
        t.status = Status.Paid;
        credit[t.runner] += t.price;
        runnerDone[t.runner] += 1;
        emit Settled(id, Status.Paid);
    }

    function _refund(uint256 id, Task storage t) private {
        t.status = Status.Refunded;
        credit[t.requester] += t.price;
        emit Settled(id, Status.Refunded);
    }
}

contracts/DataDAO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title DataDAO: labelled data for Neuro's model, rewarded by measured improvement (testnet)
/// @notice Contributors register labelled data (its sha256/keccak hash + where to get it +
///         row count + licence). The weekly ML training job (GitHub Actions, no server) measures
///         how much each contributor's data improves the model on held-out rows
///         (zetaphy-neuro/ml/dao/attribute.js: leave-one-contributor-out or a Shapley estimate)
///         and turns that into a merkle root of (round, account, amount). The poster (a
///         governance-chosen address, e.g. a multisig that checked the job's report) posts the
///         root with the hash and URI of the job's report. Claims open after `vetoDelay`, during
///         which governance can veto a wrong root; what is not claimed before `claimPeriod`
///         ends goes back to the pool. Rewards are testnet ZETAPHY from `fund()`.
contract DataDAO {
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_LICENSE = 32;

    struct Submission {
        address contributor;
        uint64 at;
        uint32 rows;
        bool excluded;       // governance: bad / copied / unlicensed data
        bytes32 dataHash;
        string uri;
        string license;      // SPDX id, e.g. "MIT", "CC0-1.0"
    }

    struct Round {
        bytes32 root;
        uint128 total;
        uint128 claimed;
        uint64 postedAt;
        uint64 claimFrom;
        uint64 expires;
        bool vetoed;
        bool swept;
        bytes32 reportHash;  // hash of the attribution report (metrics per contributor)
        string reportUri;
    }

    address public governance;
    address public poster;
    uint64 public vetoDelay = 2 days;
    uint64 public claimPeriod = 60 days;
    uint256 public reserved;            // promised to posted, live rounds

    Submission[] private _subs;
    mapping(bytes32 => uint256) public idOfHash; // dataHash -> id (1-based)
    Round[] private _rounds;
    mapping(uint256 => mapping(address => bool)) public claimed;

    event Submitted(uint256 indexed id, address indexed contributor, bytes32 dataHash, uint32 rows, string uri, string license);
    event Excluded(uint256 indexed id, bool excluded);
    event RoundPosted(uint256 indexed round, bytes32 root, uint256 total, bytes32 reportHash, string reportUri);
    event RoundVetoed(uint256 indexed round);
    event Claimed(uint256 indexed round, address indexed account, uint256 amount);
    event Swept(uint256 indexed round, uint256 amount);
    event Funded(address indexed from, uint256 amount);
    event PosterSet(address poster);
    event GovernanceSet(address governance);
    event DelaysSet(uint64 vetoDelay, uint64 claimPeriod);

    error NotGovernance();
    error NotPoster();
    error BadInput();
    error Duplicate();
    error NotEnoughFunds();
    error BadRound();
    error NotOpen();
    error AlreadyClaimed();
    error BadProof();
    error SendFailed();

    constructor(address governance_, address poster_) {
        governance = governance_;
        poster = poster_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    receive() external payable { emit Funded(msg.sender, msg.value); }
    function fund() external payable { emit Funded(msg.sender, msg.value); }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setPoster(address p) external onlyGov { poster = p; emit PosterSet(p); }
    function setDelays(uint64 vetoFor, uint64 period) external onlyGov {
        if (vetoFor > 30 days || period < 7 days || period > 365 days) revert BadInput();
        (vetoDelay, claimPeriod) = (vetoFor, period);
        emit DelaysSet(vetoFor, period);
    }

    // ------------------------------------------------------------------ data

    function submit(bytes32 dataHash, string calldata uri, uint32 rows, string calldata license) external returns (uint256 id) {
        if (dataHash == bytes32(0) || rows == 0 || bytes(uri).length == 0 || bytes(uri).length > MAX_URI
            || bytes(license).length == 0 || bytes(license).length > MAX_LICENSE) revert BadInput();
        if (idOfHash[dataHash] != 0) revert Duplicate();
        _subs.push(Submission(msg.sender, uint64(block.timestamp), rows, false, dataHash, uri, license));
        id = _subs.length;
        idOfHash[dataHash] = id;
        emit Submitted(id, msg.sender, dataHash, rows, uri, license);
    }

    function exclude(uint256 id, bool on) external onlyGov {
        if (id == 0 || id > _subs.length) revert BadInput();
        _subs[id - 1].excluded = on;
        emit Excluded(id, on);
    }

    function submissionCount() external view returns (uint256) { return _subs.length; }

    function submission(uint256 id) external view returns (address contributor, uint64 at, uint32 rows, bool excluded, bytes32 dataHash, string memory uri, string memory license) {
        Submission storage s = _subs[id - 1];
        return (s.contributor, s.at, s.rows, s.excluded, s.dataHash, s.uri, s.license);
    }

    // ------------------------------------------------------------------ rewards

    function available() public view returns (uint256) {
        return address(this).balance - reserved;
    }

    function postRound(bytes32 root, uint128 total, bytes32 reportHash, string calldata reportUri) external returns (uint256 round) {
        if (msg.sender != poster) revert NotPoster();
        if (root == bytes32(0) || total == 0 || bytes(reportUri).length > MAX_URI) revert BadInput();
        if (total > available()) revert NotEnoughFunds();
        reserved += total;
        uint64 nowT = uint64(block.timestamp);
        _rounds.push(Round(root, total, 0, nowT, nowT + vetoDelay, nowT + vetoDelay + claimPeriod, false, false, reportHash, reportUri));
        round = _rounds.length;
        emit RoundPosted(round, root, total, reportHash, reportUri);
    }

    function veto(uint256 round) external onlyGov {
        Round storage r = _round(round);
        if (r.vetoed || block.timestamp >= r.claimFrom) revert NotOpen();
        r.vetoed = true;
        reserved -= r.total;
        emit RoundVetoed(round);
    }

    /// Leaf: keccak256(keccak256(abi.encode(this, chainid, round, account, amount))); pairs hashed sorted.
    function leafOf(uint256 round, address account, uint256 amount) public view returns (bytes32) {
        return keccak256(bytes.concat(keccak256(abi.encode(address(this), block.chainid, round, account, amount))));
    }

    /// Pays `account` its reward for `round` (anyone may send it; the coins go to the account).
    function claim(uint256 round, address account, uint256 amount, bytes32[] calldata proof) external {
        Round storage r = _round(round);
        if (r.vetoed || block.timestamp < r.claimFrom || block.timestamp >= r.expires) revert NotOpen();
        if (claimed[round][account]) revert AlreadyClaimed();
        bytes32 h = leafOf(round, account, amount);
        for (uint256 i; i < proof.length; i++) {
            bytes32 p = proof[i];
            h = h < p ? keccak256(abi.encode(h, p)) : keccak256(abi.encode(p, h));
        }
        if (h != r.root) revert BadProof();
        if (uint256(r.claimed) + amount > r.total) revert NotEnoughFunds();
        claimed[round][account] = true;
        r.claimed += uint128(amount);
        reserved -= amount;
        (bool ok,) = account.call{value: amount}("");
        if (!ok) revert SendFailed();
        emit Claimed(round, account, amount);
    }

    /// After the claim period, what was not claimed goes back to the pool.
    function sweep(uint256 round) external {
        Round storage r = _round(round);
        if (r.vetoed || r.swept || block.timestamp < r.expires) revert NotOpen();
        r.swept = true;
        uint256 left = r.total - r.claimed;
        reserved -= left;
        emit Swept(round, left);
    }

    function roundCount() external view returns (uint256) { return _rounds.length; }

    function rounds(uint256 round) external view returns (bytes32 root, uint256 total, uint256 claimedAmount, uint64 postedAt, uint64 claimFrom, uint64 expires, bool vetoed, bytes32 reportHash, string memory reportUri) {
        Round storage r = _round(round);
        return (r.root, r.total, r.claimed, r.postedAt, r.claimFrom, r.expires, r.vetoed, r.reportHash, r.reportUri);
    }

    function _round(uint256 round) private view returns (Round storage) {
        if (round == 0 || round > _rounds.length) revert BadRound();
        return _rounds[round - 1];
    }
}

contracts/DetectorPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IForesightTracks {
    function modelOwner(bytes32 modelId) external view returns (address);
    function tracks(bytes32 modelId) external view returns (uint32 n, uint32 unrevealed, uint64 brierSum);
}

/// @title DetectorPool: evolving scam detectors (testnet)
/// @notice A detector "organism" is a rule set or model (its spec's hash + URI, e.g. a
///         zetaphy-neuro/ml/detectors spec JSON) with an author, a testnet stake, a parent
///         (the organism it was mutated from, 0 for none) and a ForesightRegistry model id.
///         The organism forecasts resolved questions (RiskForecasts, the arena) through
///         ForesightRegistry with commit-reveal, so its record cannot be faked or copied.
///
///         Every round (anyone may call `scoreRound` once it ended), each living organism's
///         Brier scores from that round are read from ForesightRegistry:
///           - at least `minForecasts` scored and better than always-50% (Brier < 0.25): a
///             winner, paid from the slashed stakes plus `rewardPerRound` from the pool, in
///             proportion to (0.25 - Brier) x forecasts;
///           - worse than always-50%: a loser, `slashBps` of its stake is slashed, one strike;
///             at `maxStrikes` strikes, or a stake below `minStake`, it is retired (the rest
///             of its stake is returned to its author);
///           - fewer forecasts: no change, but after MAX_IDLE such rounds in a row it is retired
///             (stake returned, not slashed), so the pool only keeps detectors that keep working.
///         A mutation script (zetaphy-neuro/ml/detectors/mutate.js, run on a GitHub Actions
///         schedule) breeds new variants from the best organisms and registers them.
contract DetectorPool {
    uint256 public constant BPS = 10_000;
    uint256 public constant COIN_FLIP = 25_000_000; // Brier 0.25 at 1e8 scale
    uint256 public constant MAX_ALIVE = 64;
    uint256 public constant MAX_URI = 200;
    uint16 public constant MAX_IDLE = 4;     // retired (stake returned, no slash) after 4 idle rounds

    struct Organism {
        address author;
        uint32 parent;
        uint16 strikes;
        uint16 wins;
        uint16 idle;         // rounds in a row with too few forecasts
        bool alive;
        bool leaving;
        uint64 born;
        uint128 stake;
        bytes32 modelId;
        bytes32 specHash;
        uint32 lastN;        // Foresight track at the last round
        uint64 lastSum;
        uint64 lastBrier;    // the last round's mean Brier (1e8), 0 if not scored
        string uri;
    }

    address public governance;
    IForesightTracks public foresight;
    uint128 public minStake = 1 ether;
    uint16 public slashBps = 2000;
    uint16 public maxStrikes = 3;
    uint32 public minForecasts = 3;
    uint64 public roundLength = 7 days;
    uint128 public rewardPerRound = 10 ether;
    uint64 public roundEnd;
    uint32 public round = 1;
    uint256 public pool;        // funded rewards + slashed stakes not yet paid
    uint256 public totalStake;

    Organism[] private _orgs;
    uint32[] public aliveIds;
    mapping(bytes32 => uint32) public organismOfModel;
    mapping(address => uint256) public owed;

    event Born(uint32 indexed id, address indexed author, uint32 indexed parent, bytes32 modelId, bytes32 specHash, uint256 stake, string uri);
    event Won(uint32 indexed id, uint32 indexed round, uint256 brier, uint256 reward);
    event Slashed(uint32 indexed id, uint32 indexed round, uint256 brier, uint256 n, uint256 amount, uint16 strikes);
    event Retired(uint32 indexed id, uint32 indexed round, uint256 returned);
    event RoundScored(uint32 indexed round, uint256 winners, uint256 losers, uint256 paid, uint64 nextEnd);
    event Funded(address indexed from, uint256 amount);
    event ParamsSet(uint128 minStake, uint16 slashBps, uint16 maxStrikes, uint32 minForecasts, uint64 roundLength, uint128 rewardPerRound);
    event GovernanceSet(address governance);

    error NotGovernance();
    error BadInput();
    error NotModelOwner();
    error ModelInUse();
    error Full();
    error NotAuthor();
    error NotYet();
    error NothingOwed();
    error SendFailed();

    constructor(address governance_, IForesightTracks foresight_) {
        governance = governance_;
        foresight = foresight_;
        roundEnd = uint64(block.timestamp) + roundLength;
        _orgs.push(); // id 0 = none
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    receive() external payable { pool += msg.value; emit Funded(msg.sender, msg.value); }
    function fund() external payable { pool += msg.value; emit Funded(msg.sender, msg.value); }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }

    function setParams(uint128 stake, uint16 slash, uint16 strikes, uint32 minF, uint64 length, uint128 reward) external onlyGov {
        if (stake == 0 || slash > 5000 || strikes == 0 || minF == 0 || length < 1 hours || length > 90 days) revert BadInput();
        (minStake, slashBps, maxStrikes, minForecasts, roundLength, rewardPerRound) = (stake, slash, strikes, minF, length, reward);
        emit ParamsSet(stake, slash, strikes, minF, length, reward);
    }

    // ------------------------------------------------------------------ organisms

    function register(bytes32 modelId, bytes32 specHash, uint32 parent, string calldata uri) external payable returns (uint32 id) {
        if (msg.value < minStake || msg.value > type(uint128).max || specHash == bytes32(0) || bytes(uri).length > MAX_URI || parent >= _orgs.length) revert BadInput();
        if (foresight.modelOwner(modelId) != msg.sender) revert NotModelOwner();
        if (organismOfModel[modelId] != 0) revert ModelInUse();
        if (aliveIds.length >= MAX_ALIVE) revert Full();
        (uint32 n,, uint64 sum) = foresight.tracks(modelId);
        id = uint32(_orgs.length);
        _orgs.push(Organism(msg.sender, parent, 0, 0, 0, true, false, uint64(block.timestamp), uint128(msg.value), modelId, specHash, n, sum, 0, uri));
        organismOfModel[modelId] = id;
        aliveIds.push(id);
        totalStake += msg.value;
        emit Born(id, msg.sender, parent, modelId, specHash, msg.value, uri);
    }

    /// Leaves after the next round is scored (so a bad round cannot be dodged).
    function requestExit(uint32 id) external {
        Organism storage o = _orgs[id];
        if (o.author != msg.sender || !o.alive) revert NotAuthor();
        o.leaving = true;
    }

    function organismCount() external view returns (uint256) { return _orgs.length - 1; }
    function aliveCount() external view returns (uint256) { return aliveIds.length; }

    function organism(uint32 id) external view returns (address author, uint32 parent, bool alive, uint128 stake, uint16 strikes, uint16 wins, bytes32 modelId, bytes32 specHash, uint64 lastBrier, string memory uri) {
        Organism storage o = _orgs[id];
        return (o.author, o.parent, o.alive, o.stake, o.strikes, o.wins, o.modelId, o.specHash, o.lastBrier, o.uri);
    }

    // ------------------------------------------------------------------ rounds

    function scoreRound() external {
        if (block.timestamp < roundEnd) revert NotYet();
        uint256 len = aliveIds.length;
        uint256[] memory weight = new uint256[](len);
        uint256 totalWeight;
        uint256 slashed;
        uint256 winners;
        uint256 losers;
        for (uint256 i; i < len; i++) {
            (uint256 w, uint256 cut, bool lost) = _judge(aliveIds[i]);
            weight[i] = w;
            totalWeight += w;
            slashed += cut;
            if (w > 0) winners++;
            if (lost) losers++;
        }
        pool += slashed;
        uint256 paid;
        if (totalWeight > 0) {
            // slashed stakes are always passed on; the funded part is capped per round
            uint256 budget = rewardPerRound + slashed;
            if (budget > pool) budget = pool;
            for (uint256 i; i < len; i++) {
                if (weight[i] == 0) continue;
                uint256 r = (budget * weight[i]) / totalWeight;
                Organism storage o = _orgs[aliveIds[i]];
                owed[o.author] += r;
                paid += r;
                emit Won(aliveIds[i], round, o.lastBrier, r);
            }
            pool -= paid;
        }
        _retire();
        emit RoundScored(round, winners, losers, paid, uint64(block.timestamp) + roundLength);
        round++;
        roundEnd = uint64(block.timestamp) + roundLength;
    }

    /// One organism's round: its weight if it won, the stake cut if it lost.
    function _judge(uint32 id) private returns (uint256 w, uint256 cut, bool lost) {
        Organism storage o = _orgs[id];
        (uint32 n,, uint64 sum) = foresight.tracks(o.modelId);
        uint256 dn = n - o.lastN;
        uint256 dsum = sum - o.lastSum;
        (o.lastN, o.lastSum) = (n, sum);
        if (dn < minForecasts) { o.lastBrier = 0; o.idle++; return (0, 0, false); }
        o.idle = 0;
        uint256 mean = dsum / dn;
        o.lastBrier = uint64(mean);
        if (mean < COIN_FLIP) {
            o.strikes = 0;
            o.wins++;
            return ((COIN_FLIP - mean) * dn, 0, false);
        }
        if (mean > COIN_FLIP) {
            cut = (uint256(o.stake) * slashBps) / BPS;
            o.stake -= uint128(cut);
            totalStake -= cut;
            o.strikes++;
            emit Slashed(id, round, mean, dn, cut, o.strikes);
            return (0, cut, true);
        }
    }

    /// Retires organisms with too many strikes, too little stake, or that asked to leave.
    function _retire() private {
        for (uint256 i = aliveIds.length; i > 0; i--) {
            uint32 id = aliveIds[i - 1];
            Organism storage o = _orgs[id];
            if (o.strikes >= maxStrikes || o.stake < minStake || o.leaving || o.idle >= MAX_IDLE) {
                o.alive = false;
                uint256 back = o.stake;
                o.stake = 0;
                totalStake -= back;
                owed[o.author] += back;
                aliveIds[i - 1] = aliveIds[aliveIds.length - 1];
                aliveIds.pop();
                emit Retired(id, round, back);
            }
        }
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingOwed();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }
}

contracts/FederatedRounds.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title FederatedRounds: commit-reveal inbox for Neuro's federated updates (testnet)
/// @notice Browsers send their clipped + noised update (zetaphy-neuro/ml/fl/codec.js
///         bytes) in two steps, so nobody can tailor an update to the others of
///         the same round:
///           1. commit phase: commit(round, keccak256(abi.encode(keccak256(payload), salt, sender)))
///           2. reveal phase: reveal(round, salt, payload) emits the payload.
///         The aggregator (a scheduled GitHub Actions job or a runner) reads
///         the Revealed events after the round; the transaction's sender is the
///         update's signer. No server, no storage of payloads (events only).
///
///         Round r covers blocks [start + r*period, start + (r+1)*period) with
///         period = commitBlocks + revealBlocks; the first commitBlocks of it
///         are the commit phase, the rest the reveal phase.
///
///         Limits (testnet): one commitment per address per round, at most
///         maxPerRound commitments per round, payload <= 16 KiB. Sybil
///         resistance is NOT provided here: robust aggregation bounds what a
///         minority of addresses can do (docs/future/federated.md).
contract FederatedRounds {
    uint256 public constant MAX_PAYLOAD = 16384;

    address public governance;
    bool public paused;
    uint64 public immutable start;
    uint64 public immutable commitBlocks;
    uint64 public immutable revealBlocks;
    uint32 public maxPerRound;

    mapping(uint256 => mapping(address => bytes32)) public commitmentOf;
    mapping(uint256 => mapping(address => bool)) public revealed;
    mapping(uint256 => uint32) public commits;
    mapping(uint256 => uint32) public reveals;

    event Committed(uint256 indexed round, address indexed sender, bytes32 commitment);
    event Revealed(uint256 indexed round, address indexed sender, bytes32 payloadHash, bytes payload);
    event Paused(bool paused);
    event MaxPerRound(uint32 value);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadValue();
    error WrongPhase();
    error AlreadyCommitted();
    error RoundFull();
    error BadReveal();
    error IsPaused();

    constructor(address governance_, uint64 start_, uint64 commitBlocks_, uint64 revealBlocks_, uint32 maxPerRound_) {
        if (governance_ == address(0) || commitBlocks_ == 0 || revealBlocks_ == 0 || maxPerRound_ == 0) revert BadValue();
        governance = governance_;
        start = start_;
        commitBlocks = commitBlocks_;
        revealBlocks = revealBlocks_;
        maxPerRound = maxPerRound_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert BadValue();
        governance = next;
        emit GovernanceChanged(next);
    }

    function setPaused(bool p) external onlyGovernance {
        paused = p;
        emit Paused(p);
    }

    function setMaxPerRound(uint32 n) external onlyGovernance {
        if (n == 0) revert BadValue();
        maxPerRound = n;
        emit MaxPerRound(n);
    }

    /// First block of a round.
    function roundStart(uint256 round) public view returns (uint256) {
        return uint256(start) + round * (uint256(commitBlocks) + revealBlocks);
    }

    /// The round and phase (1 = commit, 2 = reveal) at a block; phase 0 before the first round.
    function phaseAt(uint256 blockNumber) public view returns (uint256 round, uint8 phase) {
        if (blockNumber < start) return (0, 0);
        uint256 period = uint256(commitBlocks) + revealBlocks;
        uint256 off = blockNumber - start;
        round = off / period;
        phase = off % period < commitBlocks ? 1 : 2;
    }

    function commitmentFor(bytes32 payloadHash, bytes32 salt, address sender) public pure returns (bytes32) {
        return keccak256(abi.encode(payloadHash, salt, sender));
    }

    function commit(uint256 round, bytes32 commitment) external {
        if (paused) revert IsPaused();
        (uint256 r, uint8 phase) = phaseAt(block.number);
        if (phase != 1 || r != round) revert WrongPhase();
        if (commitment == bytes32(0)) revert BadValue();
        if (commitmentOf[round][msg.sender] != bytes32(0)) revert AlreadyCommitted();
        if (commits[round] >= maxPerRound) revert RoundFull();
        commitmentOf[round][msg.sender] = commitment;
        commits[round] += 1;
        emit Committed(round, msg.sender, commitment);
    }

    function reveal(uint256 round, bytes32 salt, bytes calldata payload) external {
        (uint256 r, uint8 phase) = phaseAt(block.number);
        if (phase != 2 || r != round) revert WrongPhase();
        if (payload.length == 0 || payload.length > MAX_PAYLOAD) revert BadValue();
        bytes32 c = commitmentOf[round][msg.sender];
        bytes32 ph = keccak256(payload);
        if (c == bytes32(0) || revealed[round][msg.sender] || c != commitmentFor(ph, salt, msg.sender)) revert BadReveal();
        revealed[round][msg.sender] = true;
        reveals[round] += 1;
        emit Revealed(round, msg.sender, ph, payload);
    }
}

contracts/ForesightRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ForesightRegistry: Proof of Foresight (testnet)
/// @notice Forecasters and AI models commit keccak256(eventId, modelId, p, salt)
///         before an event's commit deadline and reveal p after it, so nobody can
///         copy a forecast or change it once the answer is known. When the event's
///         resolver states the outcome, every commitment is scored with the Brier
///         score (p - outcome)^2 and added to the model's public track record.
///         A commitment that is never revealed scores the worst possible loss (1.0),
///         so hiding a bad forecast never pays.
///
///         Probabilities are in basis points (0..10000 = 0..100%); a Brier score is
///         stored scaled by 1e8 (1.0 = 100_000_000). Always saying 50% scores 0.25.
///
///         Only resolvers that governance approved (contracts that resolve from
///         on-chain facts, such as RiskForecasts and RedBlueArena) may open events,
///         so nobody can make up events whose outcome they choose.
///         The track record is a weight, not money: DetectorPool pays and slashes
///         detectors with it, and Neuro may weight models by `skill`.
contract ForesightRegistry {
    uint256 public constant ONE = 10_000;
    uint256 public constant MAX_LOSS = ONE * ONE;      // 1.0
    uint256 public constant COIN_FLIP = MAX_LOSS / 4;  // 0.25: always 50%
    uint256 public constant PRIOR_N = 10;              // skill shrinks toward 0 with few forecasts

    enum Outcome { Open, No, Yes, Void }

    struct Event {
        address resolver;
        uint64 commitEnd;
        uint64 revealEnd;
        Outcome outcome;
        uint32 commits;
        bytes32 topic;       // what the event is, e.g. keccak256(abi.encode(market contract, market id))
    }

    struct Forecast {
        bytes32 commitment;
        uint16 p;            // revealed probability of Yes, basis points
        bool revealed;
        bool scored;
    }

    struct Track {
        uint32 n;            // scored forecasts
        uint32 unrevealed;   // of which never revealed (scored 1.0)
        uint64 brierSum;     // sum of Brier scores, 1e8 each at most
    }

    address public governance;
    uint256 public eventCount;
    mapping(address => bool) public resolvers;
    mapping(bytes32 => address) public modelOwner;
    mapping(uint256 => Event) public events;
    mapping(uint256 => mapping(bytes32 => Forecast)) public forecasts;
    mapping(bytes32 => Track) public tracks;

    event GovernanceSet(address governance);
    event ResolverSet(address indexed resolver, bool on);
    event ModelRegistered(bytes32 indexed modelId, address indexed owner);
    event ModelTransferred(bytes32 indexed modelId, address indexed to);
    event EventOpened(uint256 indexed id, address indexed resolver, bytes32 topic, uint64 commitEnd, uint64 revealEnd);
    event CommitsClosed(uint256 indexed id, uint64 at);
    event Committed(uint256 indexed id, bytes32 indexed modelId, bytes32 commitment);
    event Revealed(uint256 indexed id, bytes32 indexed modelId, uint16 p);
    event Resolved(uint256 indexed id, Outcome outcome);
    event Scored(uint256 indexed id, bytes32 indexed modelId, uint256 brier, bool revealed);

    error NotGovernance();
    error NotResolver();
    error NotModelOwner();
    error Taken();
    error BadTimes();
    error Closed();
    error NotYet();
    error BadReveal();
    error BadOutcome();
    error NothingToScore();

    constructor(address governance_) {
        governance = governance_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov {
        governance = g;
        emit GovernanceSet(g);
    }

    function setResolver(address r, bool on) external onlyGov {
        resolvers[r] = on;
        emit ResolverSet(r, on);
    }

    // ------------------------------------------------------------------ models

    /// A model id (e.g. keccak256("neuro-ml nml-b4c35477f7b1") or a detector's id) belongs to the first to claim it.
    function registerModel(bytes32 modelId) external {
        if (modelId == bytes32(0) || modelOwner[modelId] != address(0)) revert Taken();
        modelOwner[modelId] = msg.sender;
        emit ModelRegistered(modelId, msg.sender);
    }

    function transferModel(bytes32 modelId, address to) external {
        if (modelOwner[modelId] != msg.sender || to == address(0)) revert NotModelOwner();
        modelOwner[modelId] = to;
        emit ModelTransferred(modelId, to);
    }

    // ------------------------------------------------------------------ events

    function openEvent(bytes32 topic, uint64 commitEnd, uint64 revealEnd) external returns (uint256 id) {
        if (!resolvers[msg.sender]) revert NotResolver();
        if (commitEnd <= block.timestamp || revealEnd <= commitEnd) revert BadTimes();
        id = ++eventCount;
        events[id] = Event(msg.sender, commitEnd, revealEnd, Outcome.Open, 0, topic);
        emit EventOpened(id, msg.sender, topic, commitEnd, revealEnd);
    }

    /// The resolver closes commits early, e.g. as soon as the watched condition is seen.
    function closeCommits(uint256 id) external {
        Event storage e = events[id];
        if (msg.sender != e.resolver) revert NotResolver();
        if (block.timestamp < e.commitEnd) {
            uint64 shift = e.commitEnd - uint64(block.timestamp);
            e.commitEnd = uint64(block.timestamp);
            e.revealEnd -= shift; // the reveal period keeps its length
            emit CommitsClosed(id, uint64(block.timestamp));
        }
    }

    function resolve(uint256 id, Outcome outcome) external {
        Event storage e = events[id];
        if (msg.sender != e.resolver) revert NotResolver();
        if (outcome == Outcome.Open) revert BadOutcome();
        if (e.outcome != Outcome.Open) revert Closed();
        if (block.timestamp < e.commitEnd) {
            // resolving closes commits
            uint64 shift = e.commitEnd - uint64(block.timestamp);
            e.commitEnd = uint64(block.timestamp);
            e.revealEnd -= shift;
        }
        e.outcome = outcome;
        emit Resolved(id, outcome);
    }

    // ------------------------------------------------------------------ forecasts

    function commitmentOf(uint256 id, bytes32 modelId, uint16 p, bytes32 salt) public pure returns (bytes32) {
        return keccak256(abi.encode(id, modelId, p, salt));
    }

    /// Commits (or replaces, before the deadline) a model's hidden forecast.
    function commit(uint256 id, bytes32 modelId, bytes32 commitment) external {
        Event storage e = events[id];
        if (modelOwner[modelId] != msg.sender) revert NotModelOwner();
        if (e.resolver == address(0) || e.outcome != Outcome.Open || block.timestamp >= e.commitEnd) revert Closed();
        if (commitment == bytes32(0)) revert BadReveal();
        Forecast storage f = forecasts[id][modelId];
        if (f.commitment == bytes32(0)) e.commits++;
        f.commitment = commitment;
        emit Committed(id, modelId, commitment);
    }

    /// Anyone holding the salt may reveal, after the commit deadline and before the reveal deadline.
    function reveal(uint256 id, bytes32 modelId, uint16 p, bytes32 salt) external {
        Event storage e = events[id];
        if (block.timestamp < e.commitEnd) revert NotYet();
        if (block.timestamp >= e.revealEnd) revert Closed();
        Forecast storage f = forecasts[id][modelId];
        if (p > ONE || f.revealed || f.commitment == bytes32(0) || f.commitment != commitmentOf(id, modelId, p, salt)) revert BadReveal();
        f.p = p;
        f.revealed = true;
        emit Revealed(id, modelId, p);
    }

    /// Adds a forecast's Brier score to its model's track record (anyone may call).
    /// A revealed forecast is scored once the event is resolved; an unrevealed one after the reveal deadline (as 1.0).
    function score(uint256 id, bytes32 modelId) public returns (uint256 brier) {
        Event storage e = events[id];
        Forecast storage f = forecasts[id][modelId];
        if (f.commitment == bytes32(0) || f.scored || e.outcome == Outcome.Open || e.outcome == Outcome.Void) revert NothingToScore();
        if (!f.revealed && block.timestamp < e.revealEnd) revert NotYet();
        if (f.revealed) {
            uint256 target = e.outcome == Outcome.Yes ? ONE : 0;
            uint256 d = f.p > target ? f.p - target : target - f.p;
            brier = d * d;
        } else {
            brier = MAX_LOSS;
        }
        f.scored = true;
        Track storage t = tracks[modelId];
        t.n += 1;
        if (!f.revealed) t.unrevealed += 1;
        t.brierSum += uint64(brier);
        emit Scored(id, modelId, brier, f.revealed);
    }

    function scoreMany(uint256 id, bytes32[] calldata modelIds) external {
        for (uint256 i; i < modelIds.length; i++) {
            Forecast storage f = forecasts[id][modelIds[i]];
            if (f.commitment != bytes32(0) && !f.scored) score(id, modelIds[i]);
        }
    }

    // ------------------------------------------------------------------ track record

    /// Mean Brier score (1e8 = 1.0) over n scored forecasts; mean is 0 when n is 0.
    function brierOf(bytes32 modelId) external view returns (uint256 n, uint256 mean) {
        Track memory t = tracks[modelId];
        n = t.n;
        mean = n == 0 ? 0 : t.brierSum / n;
    }

    /// Skill in basis points: how much better than always saying 50% (0 = no better, 10000 = perfect),
    /// shrunk by n / (n + PRIOR_N) so a short lucky record weighs little.
    function skill(bytes32 modelId) external view returns (uint256) {
        Track memory t = tracks[modelId];
        if (t.n == 0) return 0;
        uint256 mean = t.brierSum / t.n;
        if (mean >= COIN_FLIP) return 0;
        uint256 s = ((COIN_FLIP - mean) * ONE) / COIN_FLIP;
        return (s * t.n) / (t.n + PRIOR_N);
    }
}

contracts/HackInsurance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// Parametric hack insurance, TESTNET ONLY (docs/future/crosschain-assist.md, item 32). Testnet ZETAPHY has no
// value; nothing here is an insurance product and no real money may ever be put in it.
//
//   pool:    anyone deposits testnet ZETAPHY for shares; a withdrawal is requested and paid after
//            `withdrawDelay` (longer than a claim's whole life, so a known incident cannot be fled), at the
//            share price of that time (requested shares still carry losses until then).
//   targets: governance lists the covered contracts (a target key, as ThreatRegistry.addressKey(chainid, a))
//            with a cap per claim.
//   covers:  anyone buys cover on a listed target: amount, duration; premium = amount x premiumBps x
//            duration / year, paid into the pool. Total active cover is limited to maxCoverBps of the pool.
//   claims:  the holder files the incident as deterministic replay evidence: the exploit's transaction hashes
//            and the block range (all inside the cover's blocks), the hash of Neuro's forensic report of that
//            replay and the loss it computed, with a bond. evidenceHash = keccak256(abi.encode(chain id, target,
//            txHashes, fromBlock, toBlock)) is what every runner replays.
//   vote:    the committee is NeuroJobs' runners (active, with a track record, like ThreatRegistry). A runner
//            approves by restating the SAME report hash and loss its own replay produced; anything else counts
//            as a rejection. `quorum` approvals approve, `quorum` rejections reject (the bond goes to the pool),
//            neither within `voteWindow`: expired (bond refunded).
//   dispute: during `disputeWindow` after approval anyone may dispute with a bond; governance (the chain's
//            gov module or the timelock) then upholds or overturns. Undisputed, anyone triggers the payout.
//   payout:  min(loss, the cover's amount, the target's cap, maxClaimBps of the pool, what is left of the
//            daily cap), never more than the pool holds; one payout per cover.
// What this does not do (the doc says it plainly): prove the loss on chain (the runners' replays are the
// evidence), cover chains other than this one, price risk, or protect LPs from a governance mistake.

interface IHIRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

contract HackInsurance {
    enum ClaimState { None, Voting, Approved, Rejected, Expired, Disputed, Paid, Overturned }

    struct Target { bool listed; uint128 capPerClaim; }
    struct Cover { address holder; bytes32 target; uint128 amount; uint64 startBlock; uint64 endBlock; uint64 end; bool claimed; }
    struct Claim {
        uint256 coverId;
        address claimant;
        ClaimState state;
        uint8 approvals;
        uint8 rejections;
        uint64 filedAt;
        uint64 decidedAt;     // approval time (start of the dispute window)
        uint128 loss;         // what the forensic report computed (wei)
        uint128 bond;
        bytes32 evidenceHash;
        bytes32 reportHash;
        address disputer;
        uint128 disputeBond;
    }

    uint256 public constant MAX_TXS = 16;
    uint256 public constant YEAR = 365 days;

    IHIRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed;
    address public governance;

    // parameters (governance)
    uint16 public premiumBps = 200;          // per year of cover
    uint16 public maxCoverBps = 30000;       // active cover at most 3x the pool
    uint16 public maxClaimBps = 2000;        // one claim pays at most 20% of the pool
    uint128 public dailyCap = 1000 ether;    // all payouts per UTC day
    uint128 public claimBond = 1 ether;
    uint128 public disputeBond = 5 ether;
    uint64 public voteWindow = 3 days;
    uint64 public disputeWindow = 2 days;
    uint64 public withdrawDelay = 7 days;

    // pool
    uint256 public totalShares;
    mapping(address => uint256) public shares;
    mapping(address => uint256) public pendingShares;
    mapping(address => uint64) public withdrawReadyAt;
    uint256 public bondsHeld;                // claim + dispute bonds (not pool money)
    uint256 public activeCover;
    uint64 public payDay;
    uint128 public paidToday;

    mapping(bytes32 => Target) public targets;
    Cover[] public covers;
    Claim[] public claims;
    mapping(uint256 => mapping(address => bool)) public voted;
    mapping(uint256 => uint256) public claimOfCover;   // cover id -> claim id + 1 of its open/approved claim

    event Deposited(address indexed lp, uint256 amount, uint256 shares);
    event WithdrawRequested(address indexed lp, uint256 shares, uint64 readyAt);
    event Withdrawn(address indexed lp, uint256 shares, uint256 amount);
    event TargetSet(bytes32 indexed target, bool listed, uint128 capPerClaim);
    event CoverBought(uint256 indexed id, address indexed holder, bytes32 indexed target, uint128 amount, uint64 end, uint256 premium);
    event ClaimFiled(uint256 indexed id, uint256 indexed coverId, bytes32 evidenceHash, bytes32 reportHash, uint128 loss);
    event ClaimEvidence(uint256 indexed id, bytes32[] txHashes, uint64 fromBlock, uint64 toBlock, string uri);
    event ClaimVoted(uint256 indexed id, address indexed runner, bool approve, bytes32 reportHash, uint128 loss);
    event ClaimStateChanged(uint256 indexed id, ClaimState state);
    event Disputed(uint256 indexed id, address indexed by, string why);
    event PaidOut(uint256 indexed id, address indexed to, uint256 amount);
    event ParamsSet();
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotRunner();
    error NotListed();
    error OverCapacity(uint256 room);
    error Premium(uint256 needed);
    error Bond(uint256 needed);
    error NotHolder();
    error CoverEnded();
    error Claimed();
    error BadEvidence();
    error WrongState(ClaimState state);
    error AlreadyVoted();
    error TooLate();
    error NotYet(uint64 at);
    error NoShares();
    error PayFailed();
    error BadParams();

    constructor(IHIRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_) {
        require(quorum_ >= 2 && governance_ != address(0), "params");
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov { require(g != address(0), "zero"); governance = g; emit GovernanceSet(g); }

    function setParams(uint16 premiumBps_, uint16 maxCoverBps_, uint16 maxClaimBps_, uint128 dailyCap_, uint128 claimBond_, uint128 disputeBond_,
        uint64 voteWindow_, uint64 disputeWindow_, uint64 withdrawDelay_) external onlyGov
    {
        if (maxClaimBps_ > 10000 || maxClaimBps_ == 0 || premiumBps_ > 10000 || voteWindow_ < 1 hours || disputeWindow_ < 1 hours
            || withdrawDelay_ < voteWindow_ + disputeWindow_) revert BadParams();
        (premiumBps, maxCoverBps, maxClaimBps, dailyCap, claimBond, disputeBond) = (premiumBps_, maxCoverBps_, maxClaimBps_, dailyCap_, claimBond_, disputeBond_);
        (voteWindow, disputeWindow, withdrawDelay) = (voteWindow_, disputeWindow_, withdrawDelay_);
        emit ParamsSet();
    }

    function setTarget(bytes32 target, bool listed, uint128 capPerClaim) external onlyGov {
        targets[target] = Target(listed, capPerClaim);
        emit TargetSet(target, listed, capPerClaim);
    }

    /// keccak256(abi.encode("zetaphy.threat.address", chainId, a)): the same key as ThreatRegistry.addressKey.
    function targetKey(uint256 chainId, address a) public pure returns (bytes32) { return keccak256(abi.encode("zetaphy.threat.address", chainId, a)); }

    // ---------------------------------------------------------------- pool

    /// Pool money: everything held minus the bonds.
    function assets() public view returns (uint256) { return address(this).balance - bondsHeld; }

    function deposit() external payable {
        uint256 before = assets() - msg.value;
        uint256 s = totalShares == 0 || before == 0 ? msg.value : (msg.value * totalShares) / before;
        if (s == 0) revert NoShares();
        shares[msg.sender] += s;
        totalShares += s;
        emit Deposited(msg.sender, msg.value, s);
    }

    function requestWithdraw(uint256 s) external {
        if (s == 0 || s > shares[msg.sender]) revert NoShares();
        pendingShares[msg.sender] = s;
        withdrawReadyAt[msg.sender] = uint64(block.timestamp) + withdrawDelay;
        emit WithdrawRequested(msg.sender, s, withdrawReadyAt[msg.sender]);
    }

    function withdraw() external {
        uint256 s = pendingShares[msg.sender];
        if (s == 0) revert NoShares();
        if (block.timestamp < withdrawReadyAt[msg.sender]) revert NotYet(withdrawReadyAt[msg.sender]);
        if (s > shares[msg.sender]) s = shares[msg.sender];
        uint256 amount = (s * assets()) / totalShares;
        pendingShares[msg.sender] = 0;
        shares[msg.sender] -= s;
        totalShares -= s;
        emit Withdrawn(msg.sender, s, amount);
        _send(msg.sender, amount);
    }

    // ---------------------------------------------------------------- covers

    function premiumOf(uint128 amount, uint64 duration) public view returns (uint256) {
        return (uint256(amount) * premiumBps * duration) / (10000 * YEAR);
    }

    function buyCover(bytes32 target, uint128 amount, uint64 duration) external payable returns (uint256 id) {
        if (!targets[target].listed) revert NotListed();
        if (amount == 0 || duration < 1 days || duration > YEAR) revert BadParams();
        uint256 premium = premiumOf(amount, duration);
        if (msg.value < premium) revert Premium(premium);
        uint256 room = ((assets() - msg.value + premium) * maxCoverBps) / 10000;
        if (activeCover + amount > room) revert OverCapacity(room > activeCover ? room - activeCover : 0);
        activeCover += amount;
        covers.push(Cover(msg.sender, target, amount, uint64(block.number), type(uint64).max, uint64(block.timestamp) + duration, false));
        id = covers.length - 1;
        emit CoverBought(id, msg.sender, target, amount, uint64(block.timestamp) + duration, premium);
        if (msg.value > premium) _send(msg.sender, msg.value - premium);
    }

    /// Ends an expired cover's capacity use (anyone).
    function expireCover(uint256 coverId) external {
        Cover storage c = covers[coverId];
        if (block.timestamp < c.end || c.endBlock != type(uint64).max || claimOfCover[coverId] != 0) revert NotYet(c.end);
        c.endBlock = uint64(block.number);
        activeCover -= c.amount;
    }

    // ---------------------------------------------------------------- claims

    /// What every runner replays: this chain, the target, the exploit's transactions and the block range.
    function evidenceHash(bytes32 target, bytes32[] calldata txHashes, uint64 fromBlock, uint64 toBlock) public view returns (bytes32) {
        return keccak256(abi.encode(block.chainid, target, txHashes, fromBlock, toBlock));
    }

    function fileClaim(uint256 coverId, bytes32[] calldata txHashes, uint64 fromBlock, uint64 toBlock, bytes32 reportHash, uint128 loss, string calldata uri)
        external payable returns (uint256 id)
    {
        Cover storage c = covers[coverId];
        _checkFiling(c, coverId, txHashes.length, fromBlock, toBlock, reportHash, loss, bytes(uri).length);
        bondsHeld += msg.value;
        bytes32 ev = evidenceHash(c.target, txHashes, fromBlock, toBlock);
        claims.push(Claim(coverId, msg.sender, ClaimState.Voting, 0, 0, uint64(block.timestamp), 0, loss, uint128(msg.value), ev, reportHash, address(0), 0));
        id = claims.length - 1;
        claimOfCover[coverId] = id + 1;
        emit ClaimFiled(id, coverId, ev, reportHash, loss);
        emit ClaimEvidence(id, txHashes, fromBlock, toBlock, uri);
    }

    function _checkFiling(Cover storage c, uint256 coverId, uint256 txs, uint64 fromBlock, uint64 toBlock, bytes32 reportHash, uint128 loss, uint256 uriLen) private view {
        if (msg.sender != c.holder) revert NotHolder();
        if (c.claimed || claimOfCover[coverId] != 0) revert Claimed();
        if (block.timestamp > c.end + voteWindow) revert CoverEnded();
        if (msg.value != claimBond) revert Bond(claimBond);
        if (txs == 0 || txs > MAX_TXS || reportHash == bytes32(0) || loss == 0 || uriLen > 200
            || fromBlock > toBlock || fromBlock < c.startBlock || toBlock >= block.number) revert BadEvidence();
    }

    function _checkRunner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    /// A runner's vote: approve only by restating the same forensic report hash and loss its replay produced.
    function vote(uint256 id, bool approve, bytes32 reportHash, uint128 loss) external {
        _checkRunner();
        Claim storage k = claims[id];
        if (k.state != ClaimState.Voting) revert WrongState(k.state);
        if (block.timestamp > k.filedAt + voteWindow) revert TooLate();
        if (msg.sender == k.claimant) revert NotRunner();
        if (voted[id][msg.sender]) revert AlreadyVoted();
        voted[id][msg.sender] = true;
        bool yes = approve && reportHash == k.reportHash && loss == k.loss;
        if (yes) k.approvals += 1; else k.rejections += 1;
        emit ClaimVoted(id, msg.sender, yes, reportHash, loss);
        if (k.approvals >= quorum) {
            k.state = ClaimState.Approved;
            k.decidedAt = uint64(block.timestamp);
            emit ClaimStateChanged(id, ClaimState.Approved);
        } else if (k.rejections >= quorum) {
            _close(id, ClaimState.Rejected, false);
        }
    }

    /// Neither quorum within the vote window: the bond comes back.
    function expire(uint256 id) external {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Voting) revert WrongState(k.state);
        if (block.timestamp <= k.filedAt + voteWindow) revert NotYet(k.filedAt + voteWindow);
        _close(id, ClaimState.Expired, true);
    }

    function dispute(uint256 id, string calldata why) external payable {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Approved) revert WrongState(k.state);
        if (block.timestamp >= k.decidedAt + disputeWindow) revert TooLate();
        if (msg.value != disputeBond) revert Bond(disputeBond);
        bondsHeld += msg.value;
        k.state = ClaimState.Disputed;
        k.disputer = msg.sender;
        k.disputeBond = uint128(msg.value);
        emit Disputed(id, msg.sender, why);
        emit ClaimStateChanged(id, ClaimState.Disputed);
    }

    /// Governance decides a dispute: upheld = the claim stands (the disputer's bond goes to the pool, then
    /// the payout follows); overturned = the claim fails (the claimant's bond goes to the disputer, whose own comes back).
    function resolveDispute(uint256 id, bool claimStands) external onlyGov {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Disputed) revert WrongState(k.state);
        uint256 db = k.disputeBond;
        bondsHeld -= db;
        k.disputeBond = 0;
        if (claimStands) {
            k.state = ClaimState.Approved;
            k.decidedAt = uint64(block.timestamp) - disputeWindow; // payable now
            emit ClaimStateChanged(id, ClaimState.Approved);
        } else {
            uint256 cb = k.bond;
            bondsHeld -= cb;
            k.bond = 0;
            k.state = ClaimState.Overturned;
            claimOfCover[k.coverId] = 0;
            emit ClaimStateChanged(id, ClaimState.Overturned);
            _send(k.disputer, db + cb);
        }
    }

    /// What payout(id) would pay now.
    function payoutOf(uint256 id) public view returns (uint256 amount) {
        Claim storage k = claims[id];
        Cover storage c = covers[k.coverId];
        amount = k.loss;
        if (c.amount < amount) amount = c.amount;
        uint128 cap = targets[c.target].capPerClaim;
        if (cap < amount) amount = cap;
        uint256 pool = assets();
        uint256 byPool = (pool * maxClaimBps) / 10000;
        if (byPool < amount) amount = byPool;
        uint128 today = uint64(block.timestamp / 1 days) == payDay ? paidToday : 0;
        uint256 dayLeft = dailyCap > today ? dailyCap - today : 0;
        if (dayLeft < amount) amount = dayLeft;
    }

    /// Anyone, after the dispute window of an approved claim: pays the holder and returns the bond.
    function payout(uint256 id) external {
        Claim storage k = claims[id];
        if (k.state != ClaimState.Approved) revert WrongState(k.state);
        if (block.timestamp < k.decidedAt + disputeWindow) revert NotYet(k.decidedAt + disputeWindow);
        uint256 amount = payoutOf(id);
        Cover storage c = covers[k.coverId];
        uint64 today = uint64(block.timestamp / 1 days);
        if (payDay != today) { payDay = today; paidToday = 0; }
        paidToday += uint128(amount);
        c.claimed = true;
        if (c.endBlock == type(uint64).max) { c.endBlock = uint64(block.number); activeCover -= c.amount; }
        k.state = ClaimState.Paid;
        uint256 bond = k.bond;
        bondsHeld -= bond;
        k.bond = 0;
        emit PaidOut(id, k.claimant, amount);
        emit ClaimStateChanged(id, ClaimState.Paid);
        _send(k.claimant, amount + bond);
    }

    function _close(uint256 id, ClaimState s, bool refund) private {
        Claim storage k = claims[id];
        k.state = s;
        claimOfCover[k.coverId] = 0;
        uint256 b = k.bond;
        bondsHeld -= b;     // refunded, or (rejected) left in the contract as pool money
        k.bond = 0;
        emit ClaimStateChanged(id, s);
        if (refund) _send(k.claimant, b);
    }

    function _send(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
    }

    function coverCount() external view returns (uint256) { return covers.length; }
    function claimCount() external view returns (uint256) { return claims.length; }
}

contracts/HumanAgentLabels.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ILabelWebAuthn {
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool);
}

interface ILabelAgents {
    function activeAgentOf(address account) external view returns (uint256);
}

/// The read interface for hooks (faucets, DEX gates, ...).
interface ILabels {
    /// 0 = no label, 1 = human (passkey-verified), 2 = registered AI agent
    function labelOf(address account) external view returns (uint8);
}

/// @title LabelRegistry: "human" or "agent" labels for accounts (testnet)
/// @notice
///   AGENT: an account an active agent of AgentRegistry transacts from
///          (bonded, not unbonding). Read live from the registry, so it
///          follows registration, unbonding and slashing.
///   HUMAN: an account whose owner showed a passkey (WebAuthn) with user
///          verification (fingerprint, face or device PIN), in one of two ways:
///          - on chain: proveHumanP256 checks the assertion through
///            WebAuthnVerifier (the P-256 precompile 0x…0100); the passkey's
///            challenge commits to this account and its nonce;
///          - off chain: an attester governance approved (a volunteer runner)
///            verified the assertion and signs an EIP-712 HumanAttestation
///            that anyone submits with attestHuman.
///          One passkey (its public key hash) labels one account at a time;
///          moving it to another account drops the old one's label.
///   An agent account is labelled AGENT even if it once proved a passkey.
///
///   What a HUMAN label does NOT prove: that the person is unique. Anyone can
///   make many passkeys. It proves a person was present at a device when the
///   label was made (expires after humanTtl). Hooks must treat it as a
///   speed bump against simple bots, not as proof of personhood.
contract LabelRegistry is ILabels {
    uint8 public constant NONE = 0;
    uint8 public constant HUMAN = 1;
    uint8 public constant AGENT = 2;
    uint8 public constant BY_PASSKEY = 1;
    uint8 public constant BY_ATTESTER = 2;

    bytes32 public constant ATTESTATION_TYPEHASH = keccak256(
        "HumanAttestation(address account,bytes32 credentialHash,uint64 validUntil,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");

    struct Human {
        uint64 validUntil;
        uint8 method;
        bytes32 credentialHash;
        address attester; // 0 for an on-chain passkey proof
    }

    address public governance;
    ILabelAgents public agents;
    ILabelWebAuthn public webauthn;
    bytes32 public rpIdHash;  // sha256 of the hub's host name (0 = any site)
    uint64 public humanTtl;

    mapping(address => bool) public isAttester;
    mapping(address => Human) public humans;
    mapping(bytes32 => address) public credentialAccount;
    mapping(address => uint256) public nonces;

    event HumanLabelled(address indexed account, bytes32 indexed credentialHash, uint8 method, address attester, uint64 validUntil);
    event HumanRevoked(address indexed account, address by);
    event AttesterSet(address indexed attester, bool allowed);
    event ConfigSet(address agents, address webauthn, bytes32 rpIdHash, uint64 humanTtl);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotAttester();
    error BadPasskey();
    error BadSignature();
    error Expired();
    error BadTtl();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_, address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) {
        governance = governance_;
        _config(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    // ------------------------------------------------------------- reading

    function labelOf(address account) public view returns (uint8) {
        if (address(agents) != address(0) && agents.activeAgentOf(account) != 0) return AGENT;
        Human storage h = humans[account];
        if (h.validUntil >= block.timestamp && credentialAccount[h.credentialHash] == account) return HUMAN;
        return NONE;
    }

    function isHuman(address account) external view returns (bool) {
        return labelOf(account) == HUMAN;
    }

    function isAgent(address account) external view returns (bool) {
        return labelOf(account) == AGENT;
    }

    /// The 32-byte challenge the passkey must sign to label `account` now.
    function humanChallenge(address account) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY human label", block.chainid, address(this), account, nonces[account]));
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY Labels"), keccak256("1"), block.chainid, address(this)));
    }

    function attestationDigest(address account, bytes32 credentialHash, uint64 validUntil, uint256 nonce, uint256 deadline)
        public view returns (bytes32)
    {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(),
            keccak256(abi.encode(ATTESTATION_TYPEHASH, account, credentialHash, validUntil, nonce, deadline))));
    }

    // ------------------------------------------------------------- labelling

    /// On-chain path: msg.sender labels itself with a passkey assertion over humanChallenge(msg.sender).
    function proveHumanP256(uint256 x, uint256 y, ILabelWebAuthn.Assertion calldata assertion) external {
        if (!webauthn.verify(humanChallenge(msg.sender), assertion, x, y, rpIdHash, true)) revert BadPasskey();
        _label(msg.sender, keccak256(abi.encode(x, y)), BY_PASSKEY, address(0), uint64(block.timestamp) + humanTtl);
    }

    /// Off-chain path: an attester's EIP-712 HumanAttestation, submitted by anyone.
    function attestHuman(address account, bytes32 credentialHash, uint64 validUntil, uint256 deadline, bytes calldata sig) external {
        if (block.timestamp > deadline) revert Expired();
        if (validUntil > block.timestamp + humanTtl) revert BadTtl();
        address attester = _recover(attestationDigest(account, credentialHash, validUntil, nonces[account], deadline), sig);
        if (!isAttester[attester]) revert NotAttester();
        _label(account, credentialHash, BY_ATTESTER, attester, validUntil);
    }

    /// The account itself, governance or any attester can remove a human label.
    function revokeHuman(address account) external {
        if (msg.sender != account && msg.sender != governance && !isAttester[msg.sender]) revert NotAttester();
        Human storage h = humans[account];
        if (credentialAccount[h.credentialHash] == account) delete credentialAccount[h.credentialHash];
        delete humans[account];
        nonces[account]++;
        emit HumanRevoked(account, msg.sender);
    }

    // ------------------------------------------------------------- governance

    function setAttester(address a, bool allowed) external onlyGovernance {
        isAttester[a] = allowed;
        emit AttesterSet(a, allowed);
    }

    function setConfig(address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) external onlyGovernance {
        _config(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _config(address agents_, address webauthn_, bytes32 rpIdHash_, uint64 humanTtl_) private {
        if (humanTtl_ == 0 || humanTtl_ > 400 days) revert BadTtl();
        agents = ILabelAgents(agents_);
        webauthn = ILabelWebAuthn(webauthn_);
        rpIdHash = rpIdHash_;
        humanTtl = humanTtl_;
        emit ConfigSet(agents_, webauthn_, rpIdHash_, humanTtl_);
    }

    function _label(address account, bytes32 cred, uint8 method, address attester, uint64 until) private {
        if (cred == bytes32(0)) revert BadPasskey();
        address prev = credentialAccount[cred];
        if (prev != address(0) && prev != account) delete humans[prev]; // one passkey, one account
        Human storage old = humans[account];
        if (old.credentialHash != bytes32(0) && old.credentialHash != cred && credentialAccount[old.credentialHash] == account) {
            delete credentialAccount[old.credentialHash];
        }
        credentialAccount[cred] = account;
        humans[account] = Human({validUntil: until, method: method, credentialHash: cred, attester: attester});
        nonces[account]++;
        emit HumanLabelled(account, cred, method, attester, until);
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (v < 27) v += 27;
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(d, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }
}

/// @title VouchRegistry: an optional "vouched unique human" level on top of LabelRegistry (testnet)
/// @notice Levels (levelOf):
///           0 NONE           no HUMAN label (no label, or an AI agent);
///           1 PASSKEY_HUMAN  LabelRegistry's HUMAN: a person used a passkey. Says nothing about
///                            uniqueness: one person can make many passkeys;
///           2 VOUCHED_UNIQUE a passkey human that at least `vouchesNeeded` vouched-unique humans
///                            vouched for, each saying "I know this is one real person with one
///                            account here", and not suspended or banned.
///         A web of trust, free and without a server: no stake, no fee, no oracle. What
///         makes it Sybil-RESISTANT (not Sybil-proof):
///           - every vouch is rate-limited (one per `vouchCooldown` per voucher, at most
///             `maxActiveVouches` open at once) and only from accounts that have been unique
///             for `voucherMinAge`: a ring of k colluding real people can add at most
///             k·maxActiveVouches / vouchesNeeded fake identities, and those can vouch only
///             after voucherMinAge, so growth is slow and visible on chain;
///           - a vouch binds the vouchee's passkey (credential hash): moving the label to
///             another passkey voids it;
///           - accountability: `flagsToSuspend` distinct unique humans flagging an account
///             suspend it (level 1) until they withdraw or governance clears the flags;
///             governance bans an account it finds to be a duplicate (evidence hash on chain)
///             and every voucher of it gets a strike; `strikesToBan` strikes ban the voucher;
///           - the count is live: a vouch from an account that is banned, suspended, lost its
///             HUMAN label or its own unique status no longer counts.
///         Limits (docs/future/agents.md §25): a vouched account's own vouchers are read from
///         their stored status (one level deep; anyone can refresh() a stale one); the
///         bootstrap set is chosen by governance; collusion and bought vouches are not
///         prevented, only bounded and traceable. Full Sybil resistance is not solved here.
contract VouchRegistry {
    uint8 public constant NONE = 0;
    uint8 public constant PASSKEY_HUMAN = 1;
    uint8 public constant VOUCHED_UNIQUE = 2;
    uint256 public constant MAX_VOUCHERS = 32; // open vouches one account can hold (bounds the live count)

    LabelRegistry public immutable labels;
    address public governance;

    uint8 public vouchesNeeded;
    uint8 public maxActiveVouches;
    uint8 public flagsToSuspend;
    uint8 public strikesToBan;
    uint32 public vouchCooldown;
    uint32 public voucherMinAge;

    struct Person {
        bool genesis;       // the bootstrap set (governance)
        bool banned;
        uint8 activeGiven;  // open vouches this account gave
        uint8 strikes;      // vouched for accounts later banned
        uint64 uniqueSince; // 0 = not counted unique (refresh() sets and clears it)
        uint64 lastVouchAt;
        uint32 flagEpoch;   // clearFlags() starts a new epoch
        uint16 flags;       // distinct flaggers in this epoch
    }

    mapping(address => Person) public people;
    mapping(address => address[]) private vouchersOf_;                // vouchee -> its open vouchers
    mapping(address => mapping(address => bytes32)) public vouchCredential; // voucher => vouchee => passkey hash (0 = no vouch)
    mapping(address => mapping(uint256 => mapping(address => bool))) public flaggedBy; // account => epoch => flagger

    event Vouched(address indexed voucher, address indexed vouchee, bytes32 credentialHash);
    event Unvouched(address indexed voucher, address indexed vouchee);
    event Refreshed(address indexed account, uint8 level, uint256 vouches);
    event Flagged(address indexed account, address indexed by, uint256 flags);
    event Unflagged(address indexed account, address indexed by, uint256 flags);
    event FlagsCleared(address indexed account);
    event Banned(address indexed account, bytes32 evidenceHash);
    event Unbanned(address indexed account);
    event Struck(address indexed voucher, address indexed banned, uint256 strikes);
    event GenesisSet(address indexed account, bool on);
    event ParamsSet(uint8 vouchesNeeded, uint8 maxActiveVouches, uint32 vouchCooldown, uint32 voucherMinAge, uint8 flagsToSuspend, uint8 strikesToBan);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotUnique();
    error NotPasskeyHuman(address who);
    error TooSoon(uint256 next);
    error TooManyVouches();
    error AlreadyVouched();
    error NoVouch();
    error AlreadyFlagged();
    error NotFlagged();
    error Self();
    error IsBanned(address who);
    error BadParams();

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(LabelRegistry labels_, address governance_) {
        labels = labels_;
        governance = governance_;
        _params(3, 5, 7 days, 30 days, 5, 2);
    }

    // ------------------------------------------------------------- reading

    /// 0 none (or an agent), 1 passkey human (not proven unique), 2 vouched unique human.
    function levelOf(address a) public view returns (uint8) {
        if (labels.labelOf(a) != 1) return NONE;
        Person storage p = people[a];
        if (p.banned || p.flags >= flagsToSuspend) return PASSKEY_HUMAN;
        if (p.genesis) return VOUCHED_UNIQUE;
        if (p.uniqueSince != 0 && validVouches(a) >= vouchesNeeded) return VOUCHED_UNIQUE;
        return PASSKEY_HUMAN;
    }

    /// Open vouches for `a` that count now: the voucher is not banned or suspended, still a passkey
    /// human, counted unique (stored status), and `a` still has the passkey it was vouched with.
    function validVouches(address a) public view returns (uint256 n) {
        (, , bytes32 cred,) = labels.humans(a);
        address[] storage vs = vouchersOf_[a];
        for (uint256 i = 0; i < vs.length; i++) {
            address v = vs[i];
            if (vouchCredential[v][a] != cred || !_countsAsVoucher(v)) continue;
            n++;
        }
    }

    function vouchersOf(address a) external view returns (address[] memory) {
        return vouchersOf_[a];
    }

    /// Everything the hub shows: level, valid vouches, vouches needed, unique since, flags, flags to
    /// suspend, banned, genesis, open vouches given, when this account may vouch next (0 = cannot).
    function status(address a) external view returns (uint256[10] memory s) {
        Person storage p = people[a];
        s[0] = levelOf(a);
        s[1] = validVouches(a);
        s[2] = vouchesNeeded;
        s[3] = p.uniqueSince;
        s[4] = p.flags;
        s[5] = flagsToSuspend;
        s[6] = p.banned ? 1 : 0;
        s[7] = p.genesis ? 1 : 0;
        s[8] = p.activeGiven;
        if (s[0] == VOUCHED_UNIQUE && p.activeGiven < maxActiveVouches) {
            uint256 next = _nextVouchAt(p);
            uint256 aged = p.genesis ? 0 : uint256(p.uniqueSince) + voucherMinAge;
            s[9] = next > aged ? next : aged;
        }
    }

    // ------------------------------------------------------------- vouching

    /// msg.sender, a vouched-unique human, vouches that `who` (a passkey human) is one real person
    /// with one account. Rate-limited; withdrawable with unvouch().
    function vouch(address who) external {
        if (who == msg.sender) revert Self();
        if (levelOf(msg.sender) != VOUCHED_UNIQUE) revert NotUnique();
        Person storage me = people[msg.sender];
        if (!me.genesis && block.timestamp < uint256(me.uniqueSince) + voucherMinAge) revert TooSoon(uint256(me.uniqueSince) + voucherMinAge);
        uint256 next = _nextVouchAt(me);
        if (block.timestamp < next) revert TooSoon(next);
        if (me.activeGiven >= maxActiveVouches) revert TooManyVouches();
        if (labels.labelOf(who) != 1) revert NotPasskeyHuman(who);
        if (people[who].banned) revert IsBanned(who);
        if (vouchCredential[msg.sender][who] != bytes32(0)) revert AlreadyVouched();
        if (vouchersOf_[who].length >= MAX_VOUCHERS) revert TooManyVouches();
        (, , bytes32 cred,) = labels.humans(who);
        vouchCredential[msg.sender][who] = cred;
        vouchersOf_[who].push(msg.sender);
        me.activeGiven++;
        me.lastVouchAt = uint64(block.timestamp);
        emit Vouched(msg.sender, who, cred);
    }

    function unvouch(address who) external {
        if (vouchCredential[msg.sender][who] == bytes32(0)) revert NoVouch();
        _dropVouch(msg.sender, who);
    }

    /// Recomputes `a`'s stored unique status from its live vouches (anyone may call; the vouchee calls
    /// it once it has enough vouches). Returns the level.
    function refresh(address a) public returns (uint8 level) {
        Person storage p = people[a];
        uint256 n = validVouches(a);
        bool unique = labels.labelOf(a) == 1 && !p.banned && (p.genesis || n >= vouchesNeeded);
        if (unique && p.uniqueSince == 0) p.uniqueSince = uint64(block.timestamp);
        if (!unique && !p.genesis) p.uniqueSince = 0;
        level = levelOf(a);
        emit Refreshed(a, level, n);
    }

    // ------------------------------------------------------------- accountability

    /// A vouched-unique human says `a` is not one real person with one account (a duplicate, a bot).
    function flag(address a) external {
        if (a == msg.sender) revert Self();
        if (levelOf(msg.sender) != VOUCHED_UNIQUE) revert NotUnique();
        Person storage p = people[a];
        if (flaggedBy[a][p.flagEpoch][msg.sender]) revert AlreadyFlagged();
        flaggedBy[a][p.flagEpoch][msg.sender] = true;
        p.flags++;
        emit Flagged(a, msg.sender, p.flags);
    }

    function unflag(address a) external {
        Person storage p = people[a];
        if (!flaggedBy[a][p.flagEpoch][msg.sender]) revert NotFlagged();
        flaggedBy[a][p.flagEpoch][msg.sender] = false;
        p.flags--;
        emit Unflagged(a, msg.sender, p.flags);
    }

    // ------------------------------------------------------------- governance

    /// The bootstrap set: accounts governance knows to be distinct people (a ceremony, a meetup).
    function setGenesis(address[] calldata accounts, bool on) external onlyGovernance {
        for (uint256 i = 0; i < accounts.length; i++) {
            Person storage p = people[accounts[i]];
            p.genesis = on;
            p.uniqueSince = on ? uint64(block.timestamp) : 0;
            emit GenesisSet(accounts[i], on);
        }
    }

    /// `a` was shown to be a duplicate or a bot (evidence published, its hash here): banned, and each
    /// of its open vouchers gets a strike (banned at strikesToBan).
    function ban(address a, bytes32 evidenceHash) external onlyGovernance {
        Person storage p = people[a];
        p.banned = true;
        p.uniqueSince = 0;
        address[] storage vs = vouchersOf_[a];
        for (uint256 i = 0; i < vs.length; i++) {
            Person storage v = people[vs[i]];
            if (v.strikes < type(uint8).max) v.strikes++;
            emit Struck(vs[i], a, v.strikes);
            if (v.strikes >= strikesToBan && !v.banned) {
                v.banned = true;
                v.uniqueSince = 0;
                emit Banned(vs[i], evidenceHash);
            }
        }
        emit Banned(a, evidenceHash);
    }

    function unban(address a) external onlyGovernance {
        people[a].banned = false;
        people[a].strikes = 0;
        emit Unbanned(a);
    }

    /// Ends a flagging campaign that governance found unfounded (a new epoch: old flags no longer count).
    function clearFlags(address a) external onlyGovernance {
        Person storage p = people[a];
        p.flagEpoch++;
        p.flags = 0;
        emit FlagsCleared(a);
    }

    function setParams(uint8 needed, uint8 maxActive, uint32 cooldown, uint32 minAge, uint8 suspendAt, uint8 banAt) external onlyGovernance {
        _params(needed, maxActive, cooldown, minAge, suspendAt, banAt);
    }

    function setGovernance(address g) external onlyGovernance {
        governance = g;
        emit GovernanceChanged(g);
    }

    // ------------------------------------------------------------- internals

    function _params(uint8 needed, uint8 maxActive, uint32 cooldown, uint32 minAge, uint8 suspendAt, uint8 banAt) private {
        if (needed < 2 || needed > 16 || maxActive == 0 || maxActive > 16 || suspendAt < 2 || banAt == 0 || minAge > 365 days || cooldown > 90 days) revert BadParams();
        vouchesNeeded = needed;
        maxActiveVouches = maxActive;
        vouchCooldown = cooldown;
        voucherMinAge = minAge;
        flagsToSuspend = suspendAt;
        strikesToBan = banAt;
        emit ParamsSet(needed, maxActive, cooldown, minAge, suspendAt, banAt);
    }

    function _countsAsVoucher(address v) private view returns (bool) {
        Person storage p = people[v];
        if (p.banned || p.flags >= flagsToSuspend || labels.labelOf(v) != 1) return false;
        return p.genesis || p.uniqueSince != 0;
    }

    function _nextVouchAt(Person storage p) private view returns (uint256) {
        return p.lastVouchAt == 0 ? block.timestamp : uint256(p.lastVouchAt) + vouchCooldown;
    }

    function _dropVouch(address voucher, address who) private {
        delete vouchCredential[voucher][who];
        address[] storage vs = vouchersOf_[who];
        for (uint256 i = 0; i < vs.length; i++) {
            if (vs[i] == voucher) {
                vs[i] = vs[vs.length - 1];
                vs.pop();
                break;
            }
        }
        if (people[voucher].activeGiven > 0) people[voucher].activeGiven--;
        emit Unvouched(voucher, who);
    }
}

/// @title LabelFaucet: a testnet faucet hook that reads labels
/// @notice Pays each label its own amount (e.g. humans 10, agents 1,
///         unlabelled 0) at most once per cooldown per account, and, for
///         humans, once per cooldown per passkey too, so moving one passkey
///         across accounts does not multiply the drip. Funded by anyone.
contract LabelFaucet {
    LabelRegistry public immutable labels;
    address public governance;
    uint256 public cooldown;
    uint256[3] public amountFor; // by label: NONE, HUMAN, AGENT
    mapping(address => uint256) public lastDrip;
    mapping(bytes32 => uint256) public lastDripCredential;

    event Dripped(address indexed to, uint8 label, uint256 amount);
    event ConfigSet(uint256 cooldown, uint256[3] amountFor);

    error NotGovernance();
    error NothingForLabel(uint8 label);
    error TooSoon();
    error TransferFailed();

    constructor(LabelRegistry labels_, address governance_, uint256 cooldown_, uint256[3] memory amountFor_) {
        labels = labels_;
        governance = governance_;
        cooldown = cooldown_;
        amountFor = amountFor_;
        emit ConfigSet(cooldown_, amountFor_);
    }

    receive() external payable {}

    function setConfig(uint256 cooldown_, uint256[3] calldata amountFor_) external {
        if (msg.sender != governance) revert NotGovernance();
        cooldown = cooldown_;
        amountFor = amountFor_;
        emit ConfigSet(cooldown_, amountFor_);
    }

    function drip() external returns (uint256 amount) {
        uint8 label = labels.labelOf(msg.sender);
        amount = amountFor[label];
        if (amount == 0) revert NothingForLabel(label);
        if (lastDrip[msg.sender] != 0 && block.timestamp < lastDrip[msg.sender] + cooldown) revert TooSoon();
        lastDrip[msg.sender] = block.timestamp;
        if (label == 1) {
            (,, bytes32 cred,) = labels.humans(msg.sender);
            if (lastDripCredential[cred] != 0 && block.timestamp < lastDripCredential[cred] + cooldown) revert TooSoon();
            lastDripCredential[cred] = block.timestamp;
        }
        if (amount > address(this).balance) amount = address(this).balance;
        emit Dripped(msg.sender, label, amount);
        (bool ok,) = msg.sender.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}

/// @title LabelSwapGate: a DEX-side hook that reads labels
/// @notice A router or pool calls check(trader, amountIn) before a swap.
///         Each label has its own cap per hour on the input amount (0 = no
///         swaps for that label, type(uint256).max = no cap). The default
///         testnet setting: humans uncapped, registered agents capped (they
///         can be held to account), unlabelled accounts capped lower.
contract LabelSwapGate {
    ILabels public immutable labels;
    address public governance;
    uint256[3] public hourlyCap;
    mapping(address => uint256) public windowStart;
    mapping(address => uint256) public usedInWindow;
    mapping(address => bool) public isCaller; // routers / pools allowed to count volume

    event CapsSet(uint256[3] hourlyCap);
    event CallerSet(address caller, bool allowed);

    error NotGovernance();
    error NotCaller();
    error OverCap(uint8 label, uint256 cap);

    constructor(ILabels labels_, address governance_, uint256[3] memory hourlyCap_) {
        labels = labels_;
        governance = governance_;
        hourlyCap = hourlyCap_;
        emit CapsSet(hourlyCap_);
    }

    function setCaps(uint256[3] calldata caps) external {
        if (msg.sender != governance) revert NotGovernance();
        hourlyCap = caps;
        emit CapsSet(caps);
    }

    function setCaller(address c, bool allowed) external {
        if (msg.sender != governance) revert NotGovernance();
        isCaller[c] = allowed;
        emit CallerSet(c, allowed);
    }

    /// Counts amountIn against the trader's hourly cap for its label; reverts when over.
    function check(address trader, uint256 amountIn) external returns (uint8 label) {
        if (!isCaller[msg.sender]) revert NotCaller();
        label = labels.labelOf(trader);
        uint256 cap = hourlyCap[label];
        if (cap == type(uint256).max) return label;
        if (block.timestamp >= windowStart[trader] + 1 hours) {
            windowStart[trader] = block.timestamp;
            usedInWindow[trader] = 0;
        }
        uint256 used = usedInWindow[trader] + amountIn;
        if (used > cap) revert OverCap(label, cap);
        usedInWindow[trader] = used;
    }
}

