contracts/NeuroValidation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IValidationRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IIdentityRegistry {
    function ownerOf(uint256 tokenId) external view returns (address);
    function getApproved(uint256 tokenId) external view returns (address);
    function isApprovedForAll(address owner, address operator) external view returns (bool);
    function webEndpoint(uint256 agentId) external view returns (string memory);
}

/// @title NeuroValidation: ERC-8004 Validation Registry answered by Neuro runners
/// @notice The ERC-8004 Validation Registry interface. Validators here are the
///         bonded NeuroJobs runners with a track record (active, at least
///         `minAgreed` accepted verdicts, no more rejected than accepted):
///         stake-secured re-execution, which ERC-8004 calls "crypto-economic"
///         trust. A runner posts Neuro's verdict on an agent (a contract's
///         identity) as a validation response: the verdict hash and a 0-100
///         score.
///
///         - `validationRequest` / `validationResponse` follow the spec: the
///           agent's owner or operator asks a named validator, and only that
///           validator answers (and it must be a runner when it answers).
///         - `postVerdict` lets a runner publish a verdict on any agent without
///           a request, because an unclaimed contract identity has no owner to
///           ask, and an owner must not be able to keep Neuro's verdicts off
///           its identity. It emits the same two spec events.
///         - Each runner has ONE verdict slot per agent, at
///           `verdictRequestHash(agentId, runner)`. A newer verdict replaces the
///           older one. Verdict slots live in their own namespace: their hash
///           starts with VERDICT_TAG, and `validationRequest` refuses any hash
///           that does, so nobody can pre-create a runner's slot under another
///           agent and steal its verdicts.
///         - `getSummary` counts each validator once per agent: its latest
///           answer there (a verdict or a spec response). One runner cannot
///           outweigh the others by answering many times.
///         - A spec `requestHash` is first come, first served (the spec reads
///           by the bare hash, so it cannot be bound to the requester). Make it
///           commit to the request (e.g. keccak of agentId, validator and the
///           request file); if someone takes it first, `validationRequest`
///           reverts `Exists` and nothing of yours is written, so pick a new
///           hash. Validators should check `getValidationStatus(h).agentId`
///           before answering.
contract NeuroValidation {
    struct ValidationStatus {
        address validatorAddress;
        uint256 agentId;
        uint8 response;      // 0..100
        bytes32 responseHash;
        string tag;
        uint256 lastUpdate;
        bool hasResponse;
    }

    address public immutable identityRegistry;
    IValidationRunners public immutable runners;
    uint32 public immutable minAgreed;
    uint256 public constant MAX_TAG = 64;
    /// First 4 bytes of every postVerdict slot hash ("NVD1"); spec requests may not use them.
    bytes4 public constant VERDICT_TAG = 0x4e564431;
    bytes32 private constant TAG_MASK = 0xffffffff00000000000000000000000000000000000000000000000000000000;

    mapping(bytes32 => ValidationStatus) private _validations;
    mapping(uint256 => bytes32[]) private _agentValidations;
    mapping(address => bytes32[]) private _validatorRequests;
    /// agentId => validator => requestHash of its latest answer on that agent
    mapping(uint256 => mapping(address => bytes32)) private _latest;

    event ValidationRequest(address indexed validatorAddress, uint256 indexed agentId, string requestURI, bytes32 indexed requestHash);
    event ValidationResponse(address indexed validatorAddress, uint256 indexed agentId, bytes32 indexed requestHash,
        uint8 response, string responseURI, bytes32 responseHash, string tag);

    error BadValue();
    error NotAuthorized();
    error Exists();
    error Unknown();
    error NotValidator();
    error NotRunner();
    error ReservedHash();

    constructor(address identityRegistry_, IValidationRunners runners_, uint32 minAgreed_) {
        if (identityRegistry_ == address(0) || address(runners_) == address(0) || minAgreed_ == 0) revert BadValue();
        identityRegistry = identityRegistry_;
        runners = runners_;
        minAgreed = minAgreed_;
    }

    function getIdentityRegistry() external view returns (address) {
        return identityRegistry;
    }

    /// Is `who` a bonded runner with a track record right now?
    function isRunner(address who) public view returns (bool) {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(who);
        return active && agreed >= minAgreed && rejected <= agreed;
    }

    // ---------------------------------------------------------- ERC-8004

    function validationRequest(address validatorAddress, uint256 agentId, string calldata requestURI, bytes32 requestHash) external {
        if (validatorAddress == address(0) || requestHash == bytes32(0)) revert BadValue();
        if (isVerdictHash(requestHash)) revert ReservedHash();
        if (_validations[requestHash].validatorAddress != address(0)) revert Exists();
        IIdentityRegistry reg = IIdentityRegistry(identityRegistry);
        address owner = reg.ownerOf(agentId);
        if (msg.sender != owner && !reg.isApprovedForAll(owner, msg.sender) && reg.getApproved(agentId) != msg.sender) revert NotAuthorized();
        _open(validatorAddress, agentId, requestURI, requestHash);
    }

    function validationResponse(bytes32 requestHash, uint8 response, string calldata responseURI, bytes32 responseHash, string calldata tag) external {
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) revert Unknown();
        if (msg.sender != s.validatorAddress) revert NotValidator();
        if (!isRunner(msg.sender)) revert NotRunner();
        _answer(s, requestHash, response, responseURI, responseHash, tag);
    }

    // ------------------------------------------------------------- Neuro

    /// A runner publishes Neuro's verdict on `agentId`: `verdictHash` is the
    /// verdict (as in NeuroJobs, stored as the responseHash), `score` 0-100
    /// (100 = no problems found). A runner has one verdict slot per agent: a
    /// new post replaces its previous verdict there.
    function postVerdict(uint256 agentId, bytes32 verdictHash, uint8 score, string calldata responseURI, string calldata tag)
        external returns (bytes32 requestHash)
    {
        if (!isRunner(msg.sender)) revert NotRunner();
        if (verdictHash == bytes32(0)) revert BadValue();
        IIdentityRegistry(identityRegistry).ownerOf(agentId); // reverts for an unknown agent
        requestHash = verdictRequestHash(agentId, msg.sender);
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) {
            string memory uri;
            try IIdentityRegistry(identityRegistry).webEndpoint(agentId) returns (string memory u) { uri = u; } catch {}
            _open(msg.sender, agentId, uri, requestHash);
        } else if (s.agentId != agentId || s.validatorAddress != msg.sender) {
            revert NotAuthorized(); // unreachable while only postVerdict writes tagged slots; kept as a guard
        }
        _answer(s, requestHash, score, responseURI, verdictHash, tag);
    }

    /// The one verdict slot of `runner` on `agentId`. Its first 4 bytes are VERDICT_TAG.
    function verdictRequestHash(uint256 agentId, address runner) public view returns (bytes32) {
        bytes32 h = keccak256(abi.encode("neuro.verdict.v1", address(this), agentId, runner));
        return (h & ~TAG_MASK) | bytes32(VERDICT_TAG);
    }

    /// Is `requestHash` in the postVerdict namespace (closed to validationRequest)?
    function isVerdictHash(bytes32 requestHash) public pure returns (bool) {
        return bytes4(requestHash) == VERDICT_TAG;
    }

    // ------------------------------------------------------------- reads

    function getValidationStatus(bytes32 requestHash) external view returns (
        address validatorAddress, uint256 agentId, uint8 response, bytes32 responseHash, string memory tag, uint256 lastUpdate
    ) {
        ValidationStatus storage s = _validations[requestHash];
        if (s.validatorAddress == address(0)) revert Unknown();
        return (s.validatorAddress, s.agentId, s.response, s.responseHash, s.tag, s.lastUpdate);
    }

    /// Average response of answered validations, optionally only from
    /// `validatorAddresses` and with `tag`. Each validator counts once per
    /// agent: only its latest answer on that agent is read.
    function getSummary(uint256 agentId, address[] calldata validatorAddresses, string calldata tag)
        external view returns (uint64 count, uint8 averageResponse)
    {
        bytes32[] storage list = _agentValidations[agentId];
        bytes32 tagHash = keccak256(bytes(tag));
        uint256 total;
        for (uint256 i; i < list.length; i++) {
            ValidationStatus storage s = _validations[list[i]];
            if (!s.hasResponse) continue;
            if (_latest[agentId][s.validatorAddress] != list[i]) continue; // superseded by a newer answer
            if (bytes(tag).length > 0 && keccak256(bytes(s.tag)) != tagHash) continue;
            if (validatorAddresses.length > 0) {
                bool found;
                for (uint256 j; j < validatorAddresses.length; j++) if (validatorAddresses[j] == s.validatorAddress) { found = true; break; }
                if (!found) continue;
            }
            total += s.response;
            count++;
        }
        averageResponse = count > 0 ? uint8(total / count) : 0;
    }

    function getAgentValidations(uint256 agentId) external view returns (bytes32[] memory) {
        return _agentValidations[agentId];
    }

    function getValidatorRequests(address validatorAddress) external view returns (bytes32[] memory) {
        return _validatorRequests[validatorAddress];
    }

    // ------------------------------------------------------------ internal

    function _open(address validatorAddress, uint256 agentId, string memory requestURI, bytes32 requestHash) internal {
        ValidationStatus storage s = _validations[requestHash];
        s.validatorAddress = validatorAddress;
        s.agentId = agentId;
        s.lastUpdate = block.timestamp;
        _agentValidations[agentId].push(requestHash);
        _validatorRequests[validatorAddress].push(requestHash);
        emit ValidationRequest(validatorAddress, agentId, requestURI, requestHash);
    }

    function _answer(ValidationStatus storage s, bytes32 requestHash, uint8 response, string calldata responseURI, bytes32 responseHash, string calldata tag) internal {
        if (response > 100 || bytes(tag).length > MAX_TAG) revert BadValue();
        s.response = response;
        s.responseHash = responseHash;
        s.tag = tag;
        s.lastUpdate = block.timestamp;
        s.hasResponse = true;
        _latest[s.agentId][s.validatorAddress] = requestHash;
        emit ValidationResponse(s.validatorAddress, s.agentId, requestHash, response, responseURI, responseHash, tag);
    }
}

contracts/QuantumWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title QuantumWallet: a smart wallet a quantum computer cannot drain (stage 5)
/// @notice Every action needs an ML-DSA signature (FIPS 204, post-quantum),
///         checked by ZETAPHY's precompile at 0x…0900. Two modes:
///           - hybrid: ECDSA AND ML-DSA must both sign (today's security, plus
///             protection if ECDSA is ever broken)
///           - post-quantum only: no ECDSA key at all (ecdsaOwner = 0)
///         Anyone may submit a signed action and pay its gas (a relay), so the
///         owner needs no other account. Keys rotate only through the wallet
///         itself, i.e. with the current keys' signatures.
contract QuantumWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    address public ecdsaOwner;   // 0 = post-quantum only
    uint8 public variant;        // 44 or 65 (ML-DSA parameter set)
    bytes32 public pqKeyHash;    // keccak256 of the ML-DSA public key (the key itself rides in calldata)
    uint256 public nonce;

    /// The signatures for one action. pqPublicKey must hash to pqKeyHash;
    /// ecdsaSig is ignored in post-quantum-only mode.
    struct Auth {
        bytes pqPublicKey;
        bytes pqSig;
        bytes ecdsaSig;
    }

    event Executed(uint256 indexed nonce, address indexed to, uint256 value);
    event KeysChanged(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    error Expired();
    error BadEcdsa();
    error BadPq();
    error WrongKey();
    error BadVariant();
    error OnlySelf();
    error CallFailed(bytes reason);

    constructor(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) payable {
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    receive() external payable {}

    /// The 32 bytes both keys sign for one action.
    function digest(address to, uint256 value, bytes calldata data, uint256 deadline) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumWallet", block.chainid, address(this), nonce, to, value, keccak256(data), deadline));
    }

    function execute(address to, uint256 value, bytes calldata data, uint256 deadline, Auth calldata auth)
        external returns (bytes memory)
    {
        if (block.timestamp > deadline) revert Expired();
        _authorize(digest(to, value, data, deadline), auth);
        uint256 n = nonce++;
        (bool ok, bytes memory ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit Executed(n, to, value);
        return ret;
    }

    function _authorize(bytes32 d, Auth calldata auth) private view {
        if (ecdsaOwner != address(0) && _recover(d, auth.ecdsaSig) != ecdsaOwner) revert BadEcdsa();
        if (keccak256(auth.pqPublicKey) != pqKeyHash) revert WrongKey();
        if (!_pqValid(d, auth.pqPublicKey, auth.pqSig)) revert BadPq();
    }

    /// Rotate keys or switch mode; callable only by execute() on this wallet.
    function setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) private {
        if ((variant_ != 44 && variant_ != 65) || pqKeyHash_ == bytes32(0)) revert BadVariant();
        ecdsaOwner = ecdsaOwner_;
        variant = variant_;
        pqKeyHash = pqKeyHash_;
        emit KeysChanged(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(variant, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

/// @title QuantumWalletFactory: wallets at an address known before they exist
/// @notice The address depends only on the keys, so funds can be sent to a
///         wallet before it is deployed, and anyone can deploy it later.
contract QuantumWalletFactory {
    event Created(address indexed wallet, address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    function create(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external returns (address w) {
        w = address(new QuantumWallet{salt: _salt(ecdsaOwner, variant, pqKeyHash)}(ecdsaOwner, variant, pqKeyHash));
        emit Created(w, ecdsaOwner, variant, pqKeyHash);
    }

    function predict(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external view returns (address) {
        bytes32 h = keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt(ecdsaOwner, variant, pqKeyHash),
            keccak256(abi.encodePacked(type(QuantumWallet).creationCode, abi.encode(ecdsaOwner, variant, pqKeyHash)))));
        return address(uint160(uint256(h)));
    }

    function _salt(address e, uint8 v, bytes32 k) private pure returns (bytes32) {
        return keccak256(abi.encode(e, v, k));
    }
}

contracts/RedBlueArena.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title RedBlueArena: an open red-vs-blue round for Neuro (testnet sandbox)
/// @notice TESTNET ONLY, and the "scams" never leave a sandbox: red entries are deployed
///         only on the runners' throwaway in-memory devnet, never on a public chain.
///
///         Red submits a scam token (a manifest: Solidity source + the owner's trap steps)
///         that should get past Neuro; blue submits a detector (a rule spec). Both commit
///         keccak256(arena, round, side, author, contentHash, salt) before `commitEnd`, so
///         neither side can tailor its entry to the other's, and reveal the content hash,
///         salt and a URI after it. Runners (governance-approved; e.g. NeuroJobs runners)
///         fetch every revealed entry, check its hash, and run zetaphy-neuro/ml/redteam/arena.js:
///         each red token is deployed and listed on an in-memory devnet, a victim buys,
///         the owner's trap steps run, the victim sells; the red entry is valid when the
///         victim gets back less than half of what the pool quoted, and it evades when Neuro
///         (rules + model) still shows it below "medium". Each blue detector scores
///         (valid reds it catches) - 2 x (benign reference tokens it flags).
///         `quorum` runners must post the same result; then, after `judgeEnd`, `settle` pays:
///           - red: every valid evading entry gets an equal share of the red pool; valid
///             entries get their bond back; invalid or unrevealed entries lose it;
///           - blue: entries with a positive score share the blue pool by score; revealed
///             entries get their bond back; unrevealed ones lose it.
///         Lost bonds and unpaid pools carry over to the next round. If no result reached
///         quorum by `judgeEnd`, the round is void: revealed entries get their bonds back.
contract RedBlueArena {
    uint256 public constant MAX_RED = 128;
    uint256 public constant MAX_BLUE = 32;
    uint256 public constant MAX_URI = 200;

    struct Round {
        uint64 commitEnd;
        uint64 revealEnd;
        uint64 judgeEnd;
        bool judged;
        bool settled;
        uint128 redPool;
        uint128 bluePool;
        uint256 redValid;    // bit i: red entry i is a working scam
        uint256 redEvaded;   // bit i: ...and Neuro missed it
    }

    struct Entry {
        address author;
        bool revealed;
        bytes32 commitment;
        bytes32 contentHash;
        string uri;
    }

    address public governance;
    uint128 public redBond = 1 ether;
    uint128 public blueBond = 1 ether;
    uint8 public quorum = 1;
    uint256 public carry;          // lost bonds and unpaid pools, for the next round
    uint256 public roundCount;

    mapping(address => bool) public runners;
    mapping(uint256 => Round) public rounds;
    mapping(uint256 => Entry[]) private _red;
    mapping(uint256 => Entry[]) private _blue;
    mapping(uint256 => int32[]) private _blueScore;
    mapping(uint256 => mapping(address => bool)) public posted;
    mapping(uint256 => mapping(bytes32 => uint8)) public votes;
    mapping(address => uint256) public owed;

    event RoundOpened(uint256 indexed round, uint64 commitEnd, uint64 revealEnd, uint64 judgeEnd, uint256 redPool, uint256 bluePool);
    event Committed(uint256 indexed round, uint8 side, uint256 index, address indexed author);
    event Revealed(uint256 indexed round, uint8 side, uint256 index, bytes32 contentHash, string uri);
    event ResultPosted(uint256 indexed round, address indexed runner, bytes32 key, uint8 votes);
    event Judged(uint256 indexed round, uint256 redValid, uint256 redEvaded, int32[] blueScore);
    event Settled(uint256 indexed round, bool void, uint256 redPaid, uint256 bluePaid, uint256 carried);
    event RunnerSet(address indexed runner, bool on);
    event ParamsSet(uint128 redBond, uint128 blueBond, uint8 quorum);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotRunner();
    error BadInput();
    error WrongPhase();
    error Full();
    error BadReveal();
    error AlreadyPosted();
    error NothingOwed();
    error SendFailed();

    constructor(address governance_) {
        governance = governance_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setRunner(address r, bool on) external onlyGov { runners[r] = on; emit RunnerSet(r, on); }
    function setParams(uint128 rb, uint128 bb, uint8 q) external onlyGov {
        if (q == 0) revert BadInput();
        (redBond, blueBond, quorum) = (rb, bb, q);
        emit ParamsSet(rb, bb, q);
    }

    /// Opens a round with msg.value (+ the carry) as bounties; redShareBps of it for red.
    function openRound(uint64 commitEnd, uint64 revealEnd, uint64 judgeEnd, uint16 redShareBps) external payable onlyGov returns (uint256 id) {
        if (commitEnd <= block.timestamp || revealEnd <= commitEnd || judgeEnd <= revealEnd || redShareBps > 10_000) revert BadInput();
        uint256 total = msg.value + carry;
        carry = 0;
        uint128 red = uint128((total * redShareBps) / 10_000);
        id = ++roundCount;
        rounds[id] = Round(commitEnd, revealEnd, judgeEnd, false, false, red, uint128(total - red), 0, 0);
        emit RoundOpened(id, commitEnd, revealEnd, judgeEnd, red, total - red);
    }

    // ------------------------------------------------------------------ entries

    function commitmentOf(uint256 round, uint8 side, address author, bytes32 contentHash, bytes32 salt) public view returns (bytes32) {
        return keccak256(abi.encode(address(this), round, side, author, contentHash, salt));
    }

    /// side 0 = red (a scam token), 1 = blue (a detector). The bond is the side's bond.
    function commit(uint256 round, uint8 side, bytes32 commitment) external payable returns (uint256 index) {
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || block.timestamp >= r.commitEnd) revert WrongPhase();
        if (side > 1 || commitment == bytes32(0) || msg.value != (side == 0 ? redBond : blueBond)) revert BadInput();
        Entry[] storage list = side == 0 ? _red[round] : _blue[round];
        if (list.length >= (side == 0 ? MAX_RED : MAX_BLUE)) revert Full();
        list.push(Entry(msg.sender, false, commitment, bytes32(0), ""));
        index = list.length - 1;
        emit Committed(round, side, index, msg.sender);
    }

    function reveal(uint256 round, uint8 side, uint256 index, bytes32 contentHash, bytes32 salt, string calldata uri) external {
        Round storage r = rounds[round];
        if (block.timestamp < r.commitEnd || block.timestamp >= r.revealEnd) revert WrongPhase();
        if (side > 1 || bytes(uri).length == 0 || bytes(uri).length > MAX_URI) revert BadInput();
        Entry storage e = (side == 0 ? _red[round] : _blue[round])[index];
        if (e.revealed || e.author != msg.sender || e.commitment != commitmentOf(round, side, msg.sender, contentHash, salt)) revert BadReveal();
        e.revealed = true;
        e.contentHash = contentHash;
        e.uri = uri;
        emit Revealed(round, side, index, contentHash, uri);
    }

    function counts(uint256 round) external view returns (uint256 red, uint256 blue) {
        return (_red[round].length, _blue[round].length);
    }

    function entry(uint256 round, uint8 side, uint256 index) external view returns (address author, bool revealed, bytes32 contentHash, string memory uri) {
        Entry storage e = (side == 0 ? _red[round] : _blue[round])[index];
        return (e.author, e.revealed, e.contentHash, e.uri);
    }

    function blueScores(uint256 round) external view returns (int32[] memory) {
        return _blueScore[round];
    }

    // ------------------------------------------------------------------ judging

    function resultKey(uint256 redValid, uint256 redEvaded, int32[] calldata blueScore) public pure returns (bytes32) {
        return keccak256(abi.encode(redValid, redEvaded, blueScore));
    }

    function postResult(uint256 round, uint256 redValid, uint256 redEvaded, int32[] calldata blueScore) external {
        if (!runners[msg.sender]) revert NotRunner();
        Round storage r = rounds[round];
        if (block.timestamp < r.revealEnd || block.timestamp >= r.judgeEnd || r.judged) revert WrongPhase();
        if (posted[round][msg.sender]) revert AlreadyPosted();
        Entry[] storage reds = _red[round];
        Entry[] storage blues = _blue[round];
        if (blueScore.length != blues.length || (redEvaded & ~redValid) != 0) revert BadInput();
        uint256 revealedMask;
        for (uint256 i; i < reds.length; i++) if (reds[i].revealed) revealedMask |= (uint256(1) << i);
        if ((redValid & ~revealedMask) != 0) revert BadInput();
        for (uint256 i; i < blues.length; i++) if (!blues[i].revealed && blueScore[i] > 0) revert BadInput();
        posted[round][msg.sender] = true;
        bytes32 key = resultKey(redValid, redEvaded, blueScore);
        uint8 v = ++votes[round][key];
        emit ResultPosted(round, msg.sender, key, v);
        if (v >= quorum) {
            r.judged = true;
            r.redValid = redValid;
            r.redEvaded = redEvaded;
            _blueScore[round] = blueScore;
            emit Judged(round, redValid, redEvaded, blueScore);
        }
    }

    function settle(uint256 round) external {
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || r.settled || block.timestamp < r.judgeEnd) revert WrongPhase();
        r.settled = true;
        Entry[] storage reds = _red[round];
        Entry[] storage blues = _blue[round];
        uint256 left = uint256(r.redPool) + r.bluePool;
        uint256 redPaid;
        uint256 bluePaid;
        if (!r.judged) {
            for (uint256 i; i < reds.length; i++) _back(reds[i], redBond, reds[i].revealed);
            for (uint256 i; i < blues.length; i++) _back(blues[i], blueBond, blues[i].revealed);
        } else {
            uint256 evaders = _popcount(r.redEvaded);
            for (uint256 i; i < reds.length; i++) {
                bool valid = (r.redValid >> i) & 1 == 1;
                _back(reds[i], redBond, valid);
                if ((r.redEvaded >> i) & 1 == 1) {
                    uint256 share = r.redPool / evaders;
                    owed[reds[i].author] += share;
                    redPaid += share;
                }
            }
            int32[] storage sc = _blueScore[round];
            uint256 total;
            for (uint256 i; i < sc.length; i++) if (sc[i] > 0) total += uint256(int256(sc[i]));
            for (uint256 i; i < blues.length; i++) {
                _back(blues[i], blueBond, blues[i].revealed);
                if (total > 0 && sc[i] > 0) {
                    uint256 share = (uint256(r.bluePool) * uint256(int256(sc[i]))) / total;
                    owed[blues[i].author] += share;
                    bluePaid += share;
                }
            }
        }
        left -= redPaid + bluePaid;
        carry += left;
        emit Settled(round, !r.judged, redPaid, bluePaid, left);
    }

    function _back(Entry storage e, uint256 bond, bool ok) private {
        if (ok) owed[e.author] += bond;
        else carry += bond;
    }

    function _popcount(uint256 x) private pure returns (uint256 c) {
        for (; x != 0; x &= x - 1) c++;
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingOwed();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }
}

contracts/RewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IFundable {
    function fund() external payable;
}

/// @title RewardVault: releases the ZETAPHY reward pool at 10% a year
/// @notice The 500,000,000 ZETAPHY set aside for runners and validators sit
///         here instead of in a key-holder's account. Every day, anyone can
///         call `release()`, which pays out the share of the remaining pool
///         that has vested: 10% of what is left per year, in daily steps
///         (0.9^(1/365) is kept each day), so the pool lasts for decades.
///
///         There is NO withdraw function. Governance can only choose who
///         receives the releases (e.g. NeuroJobs' reward pool, a validator
///         rewards contract), and a change only takes effect DELAY after it
///         is announced, so everyone can see it coming. Nobody can make the
///         vault pay faster than the schedule.
contract RewardVault {
    uint256 private constant RAY = 1e27;
    /// 0.9^(1/365) in RAY: keep^365 = 0.9 (to 1e-25)
    uint256 public constant DAILY_KEEP = 999711382710977687364396358;
    uint256 public constant DELAY = 7 days;
    uint256 public constant MAX_SHARES = 8;

    struct Share {
        address to;
        uint16 bps;      // out of 10,000
        bool callFund;   // pay through `fund()` (NeuroJobs, ComputeMarket) instead of a plain transfer
    }

    uint64 public immutable start;
    uint64 public releasedDays;
    address public governance;
    Share[] private _shares;
    Share[] private _pending;
    uint64 public pendingAt; // 0 = nothing pending

    event Released(uint256 day, uint256 amount);
    event Paid(address indexed to, uint256 amount, bool ok);
    event SharesProposed(uint64 effectiveAt);
    event SharesApplied();
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadShares();
    error TooEarly();

    constructor(address governance_, Share[] memory shares_) {
        governance = governance_;
        start = uint64(block.timestamp);
        _check(shares_);
        for (uint256 i = 0; i < shares_.length; i++) _shares.push(shares_[i]);
    }

    receive() external payable {}

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- schedule ----

    function daysElapsed() public view returns (uint256) {
        return (block.timestamp - start) / 1 days;
    }

    /// What `release()` would pay right now.
    function releasable() public view returns (uint256) {
        uint256 n = daysElapsed() - releasedDays;
        if (n == 0) return 0;
        uint256 bal = address(this).balance;
        return bal - (bal * _rpow(DAILY_KEEP, n)) / RAY;
    }

    /// Pays out everything vested since the last release. Anyone may call it.
    function release() public returns (uint256 amount) {
        amount = releasable();
        releasedDays = uint64(daysElapsed()); // before any external call
        if (amount == 0) return 0;
        emit Released(releasedDays, amount);
        uint256 left = amount;
        for (uint256 i = 0; i < _shares.length; i++) {
            Share memory s = _shares[i];
            uint256 part = i + 1 == _shares.length ? left : (amount * s.bps) / 10_000;
            left -= part;
            bool ok;
            if (s.callFund) {
                (ok, ) = s.to.call{value: part}(abi.encodeCall(IFundable.fund, ()));
            } else {
                (ok, ) = s.to.call{value: part}("");
            }
            // A recipient that refuses keeps nothing: the amount stays in the
            // vault (and keeps vesting); a broken recipient cannot block others.
            emit Paid(s.to, ok ? part : 0, ok);
        }
    }

    // ---- recipients ----

    function shares() external view returns (Share[] memory) {
        return _shares;
    }

    function pendingShares() external view returns (Share[] memory) {
        return _pending;
    }

    /// Announces new recipients; they apply DELAY later.
    function proposeShares(Share[] calldata next) external onlyGovernance {
        _check(next);
        delete _pending;
        for (uint256 i = 0; i < next.length; i++) _pending.push(next[i]);
        pendingAt = uint64(block.timestamp + DELAY);
        emit SharesProposed(pendingAt);
    }

    function cancelShares() external onlyGovernance {
        delete _pending;
        pendingAt = 0;
    }

    /// After the delay, anyone may switch to the announced recipients.
    /// What vested before the switch is paid to the old ones first.
    function applyShares() external {
        if (pendingAt == 0 || block.timestamp < pendingAt) revert TooEarly();
        // Take the pending list first: a recipient called during release()
        // must not be able to apply it a second time.
        Share[] memory next = _pending;
        delete _pending;
        pendingAt = 0;
        release();
        delete _shares;
        for (uint256 i = 0; i < next.length; i++) _shares.push(next[i]);
        emit SharesApplied();
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- internals ----

    function _check(Share[] memory s) private pure {
        if (s.length == 0 || s.length > MAX_SHARES) revert BadShares();
        uint256 total;
        for (uint256 i = 0; i < s.length; i++) {
            if (s[i].to == address(0) || s[i].bps == 0) revert BadShares();
            total += s[i].bps;
        }
        if (total != 10_000) revert BadShares();
    }

    /// x^n in RAY fixed point (exponentiation by squaring, rounding half up).
    function _rpow(uint256 x, uint256 n) private pure returns (uint256 z) {
        z = n % 2 != 0 ? x : RAY;
        for (n /= 2; n != 0; n /= 2) {
            x = (x * x + RAY / 2) / RAY;
            if (n % 2 != 0) z = (z * x + RAY / 2) / RAY;
        }
    }
}

contracts/RiskForecasts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRiskPair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112, uint112, uint32);
}

interface IRiskFlags {
    function isAddressFlagged(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractFlagged(address who) external view returns (bool, uint8);
}

interface IForesightResolver {
    function openEvent(bytes32 topic, uint64 commitEnd, uint64 revealEnd) external returns (uint256);
    function closeCommits(uint256 id) external;
    function resolve(uint256 id, uint8 outcome) external;
}

/// @title RiskForecasts: testnet risk forecasts on tokens, resolved from on-chain facts
/// @notice TESTNET ONLY. Stakes are testnet ZETAPHY, which has no value; this is a
///         forecasting tool that turns people's and models' judgement into labelled
///         data for Neuro, not a product to make money with.
///
///         A forecast question is one of:
///           - LiquidityDrop: "the other side of token X's pool loses at least N% of
///             what it held when the question was opened, before the deadline"
///           - Flagged: "token X is flagged in the ThreatRegistry before the deadline"
///         Forecasters back Yes or No with a testnet stake until the question closes
///         (and never while the condition already holds). The answer comes only from
///         chain state: anyone may `poke` a question, which reads the pair's reserves or
///         the ThreatRegistry; a drop counts once it has held for `confirmDelay` (so a
///         flash swap or a single-block dip is not enough). `propose` then states the
///         answer the facts give, and a dispute window lets anyone post a bond to send it
///         to governance (e.g. the pool moved for an honest migration, or the flag was a
///         mistake). Accurate forecasters share the stakes of the inaccurate side; a void
///         question refunds everyone.
///
///         When a ForesightRegistry is set, every question is also a Foresight event, so
///         models' committed probabilities are scored (Brier) against the same answer.
contract RiskForecasts {
    enum Kind { LiquidityDrop, Flagged }
    enum Status { None, Open, Proposed, Disputed, Final }
    enum Answer { None, No, Yes, Void }

    struct Question {
        address token;
        address pair;
        Kind kind;
        uint16 dropBps;       // LiquidityDrop: the drop that makes the answer Yes
        uint64 createdAt;
        uint64 closeAt;       // forecasts until
        uint64 deadline;      // the condition must be seen by then
        uint112 baseReserve;  // the pool's other side when opened
        address creator;
    }

    struct State {
        Status status;
        Answer proposed;
        Answer answer;
        uint64 seenAt;        // first poke that saw the condition (0: not holding)
        bool confirmed;       // seen again at least confirmDelay later, before the deadline (+ confirmDelay)
        uint64 proposedAt;
        address disputer;
        uint128 yes;
        uint128 no;
        uint256 foresightId;
    }

    uint256 public constant BPS = 10_000;
    uint64 public constant MIN_HORIZON = 1 hours;
    uint64 public constant MAX_HORIZON = 180 days;

    address public governance;
    IRiskFlags public threats;
    IForesightResolver public foresight;
    uint64 public confirmDelay = 1 hours;
    uint64 public disputeWindow = 1 days;
    uint64 public revealWindow = 1 days;      // Foresight reveal period after forecasts close
    uint128 public disputeBond = 10 ether;
    uint128 public minStake = 0.01 ether;
    uint112 public minReserve = 1 ether;      // smaller pools are too easy to move

    uint256 public count;
    mapping(uint256 => Question) public questions;
    mapping(uint256 => State) public states;
    mapping(uint256 => mapping(address => uint128)) public yesOf;
    mapping(uint256 => mapping(address => uint128)) public noOf;
    mapping(uint256 => mapping(address => bool)) public claimed;
    mapping(address => uint256) public owed;

    event Opened(uint256 indexed id, address indexed token, address pair, Kind kind, uint16 dropBps, uint64 closeAt, uint64 deadline, uint112 baseReserve, uint256 foresightId);
    event Forecast(uint256 indexed id, address indexed who, bool yes, uint256 amount);
    event Seen(uint256 indexed id, bool holding, bool confirmed, uint256 reserve);
    event Proposed(uint256 indexed id, Answer answer);
    event Disputed(uint256 indexed id, address indexed by, uint256 bond);
    event Finalized(uint256 indexed id, Answer answer, bool byGovernance);
    event Claimed(uint256 indexed id, address indexed who, uint256 amount);
    event ParamsSet(uint64 confirmDelay, uint64 disputeWindow, uint64 revealWindow, uint128 disputeBond, uint128 minStake, uint112 minReserve);
    event GovernanceSet(address governance);

    error NotGovernance();
    error BadParams();
    error BadPair();
    error AlreadyTrue();
    error WrongStatus();
    error ForecastsClosed();
    error StakeTooSmall();
    error NotYet();
    error TooLate();
    error BadBond();
    error NothingToClaim();
    error SendFailed();

    constructor(address governance_, IRiskFlags threats_, IForesightResolver foresight_) {
        governance = governance_;
        threats = threats_;
        foresight = foresight_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov {
        governance = g;
        emit GovernanceSet(g);
    }

    function setParams(uint64 confirm, uint64 disputeFor, uint64 reveal, uint128 bond, uint128 stake, uint112 reserve) external onlyGov {
        if (disputeFor < 1 hours || disputeFor > 30 days || confirm > 7 days || reveal < 1 hours || reveal > 30 days || stake == 0) revert BadParams();
        (confirmDelay, disputeWindow, revealWindow, disputeBond, minStake, minReserve) = (confirm, disputeFor, reveal, bond, stake, reserve);
        emit ParamsSet(confirm, disputeFor, reveal, bond, stake, reserve);
    }

    // ------------------------------------------------------------------ open

    /// @param horizon  seconds from now to the deadline
    /// @param window   seconds from now during which forecasts are taken (<= horizon)
    function open(address token, address pair, Kind kind, uint16 dropBps, uint64 horizon, uint64 window) external returns (uint256 id) {
        if (horizon < MIN_HORIZON || horizon > MAX_HORIZON || window == 0 || window > horizon || token == address(0)) revert BadParams();
        uint112 base;
        if (kind == Kind.LiquidityDrop) {
            if (dropBps < 1000 || dropBps > BPS) revert BadParams();
            base = _otherReserve(token, pair);
            if (base < minReserve) revert BadPair();
        } else {
            if (address(threats) == address(0)) revert BadParams();
            if (_flagged(token)) revert AlreadyTrue();
            dropBps = 0;
        }
        id = ++count;
        uint64 nowT = uint64(block.timestamp);
        questions[id] = Question(token, pair, kind, dropBps, nowT, nowT + window, nowT + horizon, base, msg.sender);
        State storage s = states[id];
        s.status = Status.Open;
        if (address(foresight) != address(0)) {
            s.foresightId = foresight.openEvent(keccak256(abi.encode(address(this), id)), nowT + window, nowT + window + revealWindow);
        }
        emit Opened(id, token, pair, kind, dropBps, nowT + window, nowT + horizon, base, s.foresightId);
    }

    // ------------------------------------------------------------------ forecast

    function forecast(uint256 id, bool yes) external payable {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open || block.timestamp >= q.closeAt) revert ForecastsClosed();
        if (msg.value < minStake || msg.value > type(uint128).max) revert StakeTooSmall();
        // never while the answer is already being decided
        if (s.seenAt != 0 || _holds(q)) revert AlreadyTrue();
        if (yes) { yesOf[id][msg.sender] += uint128(msg.value); s.yes += uint128(msg.value); }
        else { noOf[id][msg.sender] += uint128(msg.value); s.no += uint128(msg.value); }
        emit Forecast(id, msg.sender, yes, msg.value);
    }

    // ------------------------------------------------------------------ resolve from chain facts

    /// Reads the chain for a question (anyone; a keeper runs it on a schedule).
    function poke(uint256 id) public {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open || s.confirmed) return;
        uint64 nowT = uint64(block.timestamp);
        bool holding = _holds(q);
        uint256 reserve = q.kind == Kind.LiquidityDrop ? _otherReserve(q.token, q.pair) : 0;
        if (holding) {
            if (s.seenAt == 0) {
                if (nowT <= q.deadline) {
                    s.seenAt = nowT;
                    // forecasts and Foresight commits stop the moment it is seen
                    if (s.foresightId != 0 && nowT < q.closeAt) foresight.closeCommits(s.foresightId);
                    if (nowT < q.closeAt) q.closeAt = nowT;
                }
            }
            if (s.seenAt != 0 && nowT >= s.seenAt + _confirmFor(q)) s.confirmed = true;
        } else if (s.seenAt != 0) {
            s.seenAt = 0; // it did not hold: start again
        }
        emit Seen(id, holding, s.confirmed, reserve);
    }

    /// States the answer the facts give: Yes once confirmed, No once the deadline (+ confirm time) passed without it.
    function propose(uint256 id) external {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open) revert WrongStatus();
        poke(id);
        Answer a;
        if (s.confirmed) a = Answer.Yes;
        else if (block.timestamp > q.deadline + _confirmFor(q) && s.seenAt == 0) a = Answer.No;
        else revert NotYet(); // (past that time, the poke above either confirmed a holding condition or reset it)
        s.status = Status.Proposed;
        s.proposed = a;
        s.proposedAt = uint64(block.timestamp);
        emit Proposed(id, a);
    }

    function dispute(uint256 id) external payable {
        State storage s = states[id];
        if (s.status != Status.Proposed) revert WrongStatus();
        if (block.timestamp >= s.proposedAt + disputeWindow) revert TooLate();
        if (msg.value != disputeBond) revert BadBond();
        s.status = Status.Disputed;
        s.disputer = msg.sender;
        emit Disputed(id, msg.sender, msg.value);
    }

    /// Governance answers a disputed question. The bond goes back if the proposed answer changed, else to governance.
    function settleDispute(uint256 id, Answer a) external onlyGov {
        State storage s = states[id];
        if (s.status != Status.Disputed) revert WrongStatus();
        if (a == Answer.None) revert BadParams();
        owed[a != s.proposed ? s.disputer : governance] += disputeBond;
        _final(id, a, true);
    }

    function finalize(uint256 id) external {
        State storage s = states[id];
        if (s.status != Status.Proposed) revert WrongStatus();
        if (block.timestamp < s.proposedAt + disputeWindow) revert NotYet();
        _final(id, s.proposed, false);
    }

    function _final(uint256 id, Answer a, bool byGov) private {
        State storage s = states[id];
        s.status = Status.Final;
        s.answer = a;
        if (s.foresightId != 0) foresight.resolve(s.foresightId, uint8(a));
        emit Finalized(id, a, byGov);
    }

    // ------------------------------------------------------------------ pay out

    /// What `who` gets back from a final question.
    function payoutOf(uint256 id, address who) public view returns (uint256) {
        State storage s = states[id];
        if (s.status != Status.Final || claimed[id][who]) return 0;
        uint256 y = yesOf[id][who];
        uint256 n = noOf[id][who];
        uint256 total = uint256(s.yes) + s.no;
        if (s.answer == Answer.Void) return y + n;
        uint256 winStake = s.answer == Answer.Yes ? y : n;
        uint256 winTotal = s.answer == Answer.Yes ? s.yes : s.no;
        if (winTotal == 0) return y + n; // nobody was right: everyone gets their stake back
        return (winStake * total) / winTotal;
    }

    function claim(uint256 id, address who) external {
        uint256 amount = payoutOf(id, who);
        if (amount == 0) revert NothingToClaim();
        claimed[id][who] = true;
        owed[who] += amount;
        emit Claimed(id, who, amount);
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingToClaim();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }

    // ------------------------------------------------------------------ facts

    function _confirmFor(Question storage q) private view returns (uint64) {
        return q.kind == Kind.Flagged ? 0 : confirmDelay; // a flag already took a quorum of runners
    }

    function _holds(Question storage q) private view returns (bool) {
        if (q.kind == Kind.Flagged) return _flagged(q.token);
        uint256 r = _otherReserve(q.token, q.pair);
        return r * BPS <= uint256(q.baseReserve) * (BPS - q.dropBps);
    }

    function _flagged(address token) private view returns (bool) {
        if (address(threats) == address(0)) return false;
        (bool a,) = threats.isAddressFlagged(block.chainid, token);
        if (a) return true;
        (bool c,) = threats.isContractFlagged(token);
        return c;
    }

    /// The reserve of the pool's other token (the liquidity a holder of `token` can sell into).
    function _otherReserve(address token, address pair) private view returns (uint112) {
        if (pair.code.length == 0) revert BadPair();
        address t0 = IRiskPair(pair).token0();
        address t1 = IRiskPair(pair).token1();
        if (t0 != token && t1 != token) revert BadPair();
        (uint112 r0, uint112 r1,) = IRiskPair(pair).getReserves();
        return t0 == token ? r1 : r0;
    }

    /// The other side's reserve now (for pages and keepers).
    function reserveNow(uint256 id) external view returns (uint256) {
        Question storage q = questions[id];
        return q.kind == Kind.LiquidityDrop ? _otherReserve(q.token, q.pair) : 0;
    }

    function holdsNow(uint256 id) external view returns (bool) {
        return _holds(questions[id]);
    }
}

contracts/SaphanTokens.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY Saphan, token routes: tokens BORN on ZETAPHY go out to an EVM chain and come back
// (the reverse of the v2 ETH routes in HyperlaneLockBoxV2.sol). docs/SAPHAN-TOKENS.md.
//
//   ZETAPHY                                                     destination chain X (Sepolia, Base Sepolia, ...)
//   ZetaphyTokenVault(token, X) --lock: Hyperlane message---->  SaphanSyntheticToken(token, X) queues a mint,
//     escrows the token             (ISM on X: OUR validators   mints after the delay (veto, daily cap, supply cap, pause)
//                                    for origin ZETAPHY)
//     queues a release <-----------burn: Hyperlane message----- sendBack(): burns, dispatches
//     pays after the delay          (ISM on ZETAPHY: Hyperlane's validator(s) for origin X)
//     (veto, daily limit, pause, never more than it locked for X)
//
// One vault per (token, destination) and one synthetic per (token, destination): a hole on chain X (or in X's
// synthetic, or X's validators) can only ask vault(token, X) for a release, and that vault pays at most what was
// locked in it for X. It cannot reach another token's vault or another destination's escrow.
//
// Local copies of the Hyperlane v3 interfaces, checked against hyperlane-xyz/hyperlane-monorepo at commit
// 1aadbba0696ecf96ed4c06f78c978d08db22c0ad (as HyperlaneLockBoxV2.sol): IMailbox dispatch / quoteDispatch,
// IMessageRecipient.handle, ISpecifiesInterchainSecurityModule.interchainSecurityModule. Named apart from the
// other files' copies (the build compiles every file in one unit and names artifacts by contract).

interface ISaphanTokenMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface ISaphanTokenIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// ThreatRegistry's hold view for ZETAPHY addresses (as BridgeGuard uses it).
interface ISaphanTokenThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// @title SaphanTokenEndpoint: what both ends of a token route share
/// @notice Sending: the subclass takes the tokens (_take: the vault escrows, the synthetic burns), then this
///         dispatches a 288-byte body through the local Mailbox to the one remote contract:
///           abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to,
///                      uint256 amount, uint256 dstChainId, address dstContract, address originToken)
///         `originToken` is the token's address on ZETAPHY (the same on both ends), so a message of token A can
///         never be taken by token B's endpoint even if every other field matched.
///         Receiving: handle() takes a message only from the Mailbox (after the ISM this contract names, never the
///         Mailbox default, never zero), from the remote domain and the remote contract (sender), whose body names
///         the remote chain and contract as the source, this chain and contract as the destination, and this
///         route's origin token; each message once. It never pays at once: the payout is queued (Queued) and anyone
///         claims it after `delay`, while not vetoed, not paused and within the daily limit (over it, it waits for
///         the next UTC day); the subclass adds its own bound (_pay: the vault's backing, the synthetic's supply
///         cap). A message is never refused for a limit or a pause, so nothing depends on the relayer retrying.
///         Starts PAUSED (deployed closed): opening is governance's unpause, on both ends.
///         Roles: governance (a timelock: 48 h) unpauses, lifts vetoes, raises limits, changes the ISM; guardians
///         (a multisig) only reduce risk, at once: pause, veto, lower the daily limit, lengthen the delay.
abstract contract SaphanTokenEndpoint {
    struct Pending {
        address to;
        uint64 readyAt;      // zero: no such message
        bool done;
        bool vetoed;
        uint256 amount;
    }

    /// The message body (288 bytes, abi.encode of these fields in this order).
    struct Body {
        uint256 srcChainId;
        address srcContract;
        uint256 srcNonce;
        address sender;
        address to;
        uint256 amount;
        uint256 dstChainId;
        address dstContract;
        address originToken;
    }

    ISaphanTokenMailbox public immutable mailbox;
    uint32 public immutable remoteDomain;     // the other end's Hyperlane domain
    uint256 public immutable remoteChainId;   // the other end's EVM chain id, as it writes it into bodies
    bytes32 public immutable remote;          // the other end's contract (the only sender, the only recipient)
    address public immutable hook;            // zero = the Mailbox default hook
    address public immutable originToken;     // the token's address on ZETAPHY

    uint64 public constant MAX_DELAY = 30 days;
    uint256 public constant BODY_LENGTH = 288;

    address public governance;
    mapping(address => bool) public guardian;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule). Never zero.
    ISaphanTokenIsm public interchainSecurityModule;
    bool public paused;
    uint256 public dailyLimit;                // token units paid out (released / minted) per UTC day
    uint256 public paidToday;
    uint64 public day;
    uint64 public delay;                      // seconds between a message and its claim

    uint256 public nonce;                     // messages sent
    uint256 public received;                  // messages recorded (the relayer workflow compares it with the other end's nonce)
    mapping(bytes32 => Pending) public pending; // by keccak256(body)
    uint256 private entered = 1;

    event Sent(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount, bytes32 messageId);
    event Queued(bytes32 indexed id, uint256 indexed srcNonce, address sender, address indexed to, uint256 amount, uint64 readyAt);
    event Paid(bytes32 indexed id, address indexed to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by);
    event VetoLifted(bytes32 indexed id);
    event Paused(address indexed by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event DailyLimitSet(uint256 limit);
    event DelaySet(uint64 delay);

    error NotGovernance();
    error NotGuardian();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error WrongDestination();
    error WrongToken(address token);
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();
    error IsPaused();
    error NoMessage();
    error AlreadyDone();
    error IsVetoed();
    error NotReady(uint64 readyAt);
    error OverLimit(uint256 remaining);
    error PayFailed();
    error Fee(uint256 needed);
    error Reentered();

    /// Deploy settings shared by both ends (one tuple: fewer constructor arguments).
    struct Config {
        ISaphanTokenMailbox mailbox;
        uint32 remoteDomain;
        uint256 remoteChainId;
        bytes32 remote;
        address hook;
        address originToken;
        ISaphanTokenIsm ism;
        address governance;
        address guardian;
        uint256 dailyLimit;
        uint64 delay;
    }

    constructor(Config memory c) {
        require(address(c.mailbox) != address(0) && c.remote != bytes32(0) && c.remoteChainId != 0 && c.originToken != address(0)
            && address(c.ism) != address(0) && c.governance != address(0) && c.delay <= MAX_DELAY, "config");
        mailbox = c.mailbox;
        remoteDomain = c.remoteDomain;
        remoteChainId = c.remoteChainId;
        remote = c.remote;
        hook = c.hook;
        originToken = c.originToken;
        interchainSecurityModule = c.ism;
        governance = c.governance;
        dailyLimit = c.dailyLimit;
        delay = c.delay;
        paused = true;
        emit IsmSet(address(c.ism));
        emit GovernanceSet(c.governance);
        emit DailyLimitSet(c.dailyLimit);
        emit DelaySet(c.delay);
        emit Paused(msg.sender);
        if (c.guardian != address(0)) { guardian[c.guardian] = true; emit GuardianSet(c.guardian, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyGuardian() { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); _; }
    modifier nonReentrant() { if (entered != 1) revert Reentered(); entered = 2; _; entered = 1; }

    // ---------------------------------------------------------------- what the two ends do differently

    /// Takes `amount` from msg.sender for a send (the vault escrows it, the synthetic burns it).
    function _take(address from, uint256 amount) internal virtual;
    /// Pays a claimed message (the vault releases within its backing, the synthetic mints within its cap).
    function _pay(address to, uint256 amount) internal virtual;

    // ---------------------------------------------------------------- sending

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount, remoteChainId, address(uint160(uint256(remote))), originToken);
    }

    /// The Mailbox fee for the next send (msg.value of the send).
    function quote(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function _send(address to, uint256 amount) internal returns (bytes32 messageId) {
        if (paused) revert IsPaused();
        require(amount > 0 && to != address(0), "send");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < fee) revert Fee(fee);
        _take(msg.sender, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(remoteDomain, remote, b)
            : mailbox.dispatch{value: fee}(remoteDomain, remote, b, "", hook);
        emit Sent(n, msg.sender, to, amount, messageId);
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(remoteDomain, remote, b) : mailbox.quoteDispatch(remoteDomain, remote, b, "", hook);
    }

    // ---------------------------------------------------------------- receiving

    /// Called by the Mailbox after interchainSecurityModule verified the message.
    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != address(mailbox)) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != remoteDomain) revert WrongOrigin(origin);
        if (sender != remote) revert WrongSender(sender);
        if (b.length != BODY_LENGTH) revert BadBody();
        Body memory m = abi.decode(b, (Body));
        if (m.srcChainId != remoteChainId || bytes32(uint256(uint160(m.srcContract))) != remote) revert WrongSource();
        if (m.dstChainId != block.chainid || m.dstContract != address(this)) revert WrongDestination();
        if (m.originToken != originToken) revert WrongToken(m.originToken);
        if (m.to == address(0) || m.amount == 0) revert BadBody();
        bytes32 id = keccak256(b);
        if (pending[id].readyAt != 0) revert Replay(id);
        uint64 readyAt = uint64(block.timestamp) + delay;
        pending[id] = Pending(m.to, readyAt, false, false, m.amount);
        received += 1;
        emit Queued(id, m.srcNonce, m.sender, m.to, m.amount, readyAt);
    }

    /// Anyone: pays a queued message to its receiver once every check passes.
    function claim(bytes32 id) external nonReentrant {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        if (p.vetoed) revert IsVetoed();
        if (paused) revert IsPaused();
        if (block.timestamp < p.readyAt) revert NotReady(p.readyAt);
        uint64 today = uint64(block.timestamp / 1 days);
        if (day != today) { day = today; paidToday = 0; }
        uint256 amount = p.amount;
        if (paidToday + amount > dailyLimit) revert OverLimit(dailyLimit > paidToday ? dailyLimit - paidToday : 0);
        p.done = true;
        paidToday += amount;
        emit Paid(id, p.to, amount);
        _pay(p.to, amount);
    }

    /// What can still be paid out today.
    function remainingToday() external view returns (uint256) {
        uint256 used = day == uint64(block.timestamp / 1 days) ? paidToday : 0;
        return dailyLimit > used ? dailyLimit - used : 0;
    }

    // ---------------------------------------------------------------- guardians: only reduce risk, at once

    function pause() external onlyGuardian { paused = true; emit Paused(msg.sender); }

    /// Stops a queued payout that is not paid yet (during its delay, or while it waits for a limit).
    function veto(bytes32 id) external onlyGuardian {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        p.vetoed = true;
        emit Vetoed(id, msg.sender);
    }

    function lowerDailyLimit(uint256 v) external onlyGuardian {
        require(v < dailyLimit, "lower only");
        dailyLimit = v;
        emit DailyLimitSet(v);
    }

    function raiseDelay(uint64 d) external onlyGuardian {
        require(d > delay && d <= MAX_DELAY, "raise only");
        delay = d;
        emit DelaySet(d);
    }

    // ---------------------------------------------------------------- governance (a timelock)

    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    function liftVeto(bytes32 id) external onlyGov {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        p.vetoed = false;
        emit VetoLifted(id);
    }

    function setDailyLimit(uint256 v) external onlyGov { dailyLimit = v; emit DailyLimitSet(v); }

    function setDelay(uint64 d) external onlyGov {
        require(d <= MAX_DELAY, "delay");
        delay = d;
        emit DelaySet(d);
    }

    /// A new ISM (e.g. more validators, a higher threshold). Never zero.
    function setInterchainSecurityModule(ISaphanTokenIsm ism) external onlyGov {
        require(address(ism) != address(0), "ism");
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }
}

/// @title ZetaphyTokenVault: the ZETAPHY side of one token to one destination chain
/// @notice lock(to, amount) escrows `amount` of `originToken` (msg.value = quote(): the Mailbox fee) and sends a
///         mint to that destination's SaphanSyntheticToken. A release (a burn on the destination) is paid from this
///         vault only, after the delay, and never more than `locked` (everything locked here minus everything
///         released here): a compromise of one destination drains at most its own escrow, never another
///         destination's or another token's.
///         The token: any ERC-20 on ZETAPHY that governance adds (deploys a vault for), including the native coin
///         through its ERC-20 precompile (0xEeee…EEeE: approve, then lock). Refused: tokens that deliver less than
///         asked (fee-on-transfer: OddToken), that return false, or whose decimals() differ from the chain table's.
///         Not supported (governance must not add them): rebasing tokens, tokens with blocklists or admin
///         transfers (a vault's balance must only move through this contract). Transfers with no return value
///         (USDT style) are accepted.
///         Extra safety: `lockCap` bounds everything ever outstanding to this destination (and so the synthetic
///         supply that can exist); a ThreatRegistry (optional) holds a flagged sender (no lock) or receiver (the
///         release waits until the hold ends, as BridgeGuard's vaccine does).
contract ZetaphyTokenVault is SaphanTokenEndpoint {
    uint8 public immutable decimals;          // the token's, checked at deploy (the synthetic has the same)
    uint256 public locked;                    // backing: locked minus released
    uint256 public lockCap;                   // `locked` may never exceed this (governance raises, guardians lower)
    ISaphanTokenThreats public threats;       // zero: no hold check

    event LockCapSet(uint256 cap);
    event ThreatsSet(address registry);
    event ExcessRecovered(address indexed to, uint256 amount);

    error OddToken(uint256 received);
    error TransferFailed();
    error OverCap(uint256 cap);
    error OverBacking(uint256 locked);
    error Held(address who);

    /// `c.remote`: the destination's SaphanSyntheticToken; `c.originToken`: the token on ZETAPHY.
    constructor(Config memory c, uint8 decimals_, uint256 lockCap_, ISaphanTokenThreats threats_) SaphanTokenEndpoint(c) {
        address token_ = c.originToken;
        require(token_.code.length > 0 || token_ == 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE, "token");
        (bool ok, bytes memory ret) = token_.staticcall(abi.encodeWithSignature("decimals()"));
        require(ok && ret.length == 32 && abi.decode(ret, (uint256)) == decimals_, "decimals");
        decimals = decimals_;
        lockCap = lockCap_;
        threats = threats_;
        emit LockCapSet(lockCap_);
        emit ThreatsSet(address(threats_));
    }

    /// Escrows `amount` here and sends a mint of the same amount (same decimals) to `to` on the destination.
    function lock(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        if (_held(from)) revert Held(from);
        if (locked + amount > lockCap) revert OverCap(lockCap);
        uint256 before = _balance();
        _call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, address(this), amount));
        uint256 got = _balance() - before;
        if (got != amount) revert OddToken(got);
        locked += amount;
    }

    function _pay(address to, uint256 amount) internal override {
        if (_held(to)) revert Held(to);
        if (amount > locked) revert OverBacking(locked);
        locked -= amount;
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
    }

    function _balance() private view returns (uint256) {
        (bool ok, bytes memory ret) = originToken.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        if (!ok || ret.length < 32) revert TransferFailed();
        return abi.decode(ret, (uint256));
    }

    /// A token call that must succeed and, if it returns anything, return true.
    function _call(bytes memory data) private {
        (bool ok, bytes memory ret) = originToken.call(data);
        if (!ok || (ret.length != 0 && (ret.length < 32 || !abi.decode(ret, (bool))))) revert TransferFailed();
    }

    function _held(address who) private view returns (bool h) {
        ISaphanTokenThreats t = threats;
        if (address(t) == address(0)) return false;
        (h, ) = t.isContractHeld(who);
    }

    function lowerLockCap(uint256 v) external onlyGuardian {
        require(v < lockCap, "lower only");
        lockCap = v;
        emit LockCapSet(v);
    }

    function setLockCap(uint256 v) external onlyGov { lockCap = v; emit LockCapSet(v); }

    function setThreats(ISaphanTokenThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Tokens sent here without lock() are not backing; governance may send them on. Never touches `locked`.
    function recoverExcess(address to) external onlyGov nonReentrant {
        uint256 b = _balance();
        require(to != address(0) && b > locked, "no excess");
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, b - locked));
        if (_balance() < locked) revert OverBacking(locked);
        emit ExcessRecovered(to, b - locked);
    }
}

/// @title SaphanSyntheticToken: a ZETAPHY token on one destination chain (e.g. zZETAPHY on Base Sepolia)
/// @notice An ERC-20 that exists only through its vault on ZETAPHY: minted only for messages from ZETAPHY's
///         domain and that vault (verified by a multisig ISM of OUR validators for origin ZETAPHY), after the mint
///         delay, within the daily mint limit and the supply cap, while not vetoed or paused. sendBack(to, amount)
///         burns the caller's tokens and sends the release to the vault (msg.value = quote()).
///         Its value is exactly the vault's safety: one synthetic is a claim on one token locked in
///         ZetaphyTokenVault(token, this chain); if that vault, our validators or ZETAPHY fail, it can be worth
///         less or nothing.
contract SaphanSyntheticToken is SaphanTokenEndpoint {
    string public name;
    string public symbol;
    uint8 public immutable decimals;          // the origin token's
    uint256 public totalSupply;
    uint256 public supplyCap;                 // totalSupply may never exceed this (governance raises, guardians lower)
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event SupplyCapSet(uint256 cap);

    error OverCap(uint256 cap);

    /// `c.remote`: the ZetaphyTokenVault on ZETAPHY (domain c.remoteDomain, chain c.remoteChainId).
    constructor(string memory name_, string memory symbol_, uint8 decimals_, Config memory c, uint256 supplyCap_) SaphanTokenEndpoint(c) {
        require(bytes(name_).length > 0 && bytes(symbol_).length > 0 && decimals_ <= 36, "token");
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
        supplyCap = supplyCap_;
        emit SupplyCapSet(supplyCap_);
    }

    /// Burns `amount` of the caller's tokens and sends their release on ZETAPHY to `to`.
    function sendBack(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        require(balanceOf[from] >= amount, "balance");
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function _pay(address to, uint256 amount) internal override {
        if (totalSupply + amount > supplyCap) revert OverCap(supplyCap);
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v);
        return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v;
        balanceOf[to] += v;
        emit Transfer(f, to, v);
    }

    function lowerSupplyCap(uint256 v) external onlyGuardian {
        require(v < supplyCap, "lower only");
        supplyCap = v;
        emit SupplyCapSet(v);
    }

    function setSupplyCap(uint256 v) external onlyGov { supplyCap = v; emit SupplyCapSet(v); }
}

contracts/SimpleMultisig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SimpleMultisig: k-of-n owners for ZETAPHY admin roles (testnet)
/// @notice Holds governance of BridgeGuard / BridgeAirlock / StableGateway so
///         that no single key can change limits, prices or lanes. Any owner
///         proposes a call; it runs once `threshold` owners confirmed it.
///         Owners and the threshold change only through the multisig itself.
///         On mainnet prefer an audited Safe; this is small on purpose.
contract SimpleMultisig {
    struct Proposal {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint8 confirmations;
    }

    address[] public owners;
    mapping(address => bool) public isOwner;
    uint8 public threshold;
    Proposal[] public proposals;
    mapping(uint256 => mapping(address => bool)) public confirmed;

    event Proposed(uint256 indexed id, address indexed by, address to, uint256 value);
    event Confirmed(uint256 indexed id, address indexed by);
    event Revoked(uint256 indexed id, address indexed by);
    event Executed(uint256 indexed id);

    error NotOwner();
    error BadConfig();
    error Done();
    error Twice();
    error NotEnough();
    error CallFailed(bytes reason);

    constructor(address[] memory owners_, uint8 threshold_) {
        _setOwners(owners_, threshold_);
    }

    receive() external payable {}

    modifier onlyOwner() { if (!isOwner[msg.sender]) revert NotOwner(); _; }

    function propose(address to, uint256 value, bytes calldata data) external onlyOwner returns (uint256 id) {
        id = proposals.length;
        proposals.push(Proposal(to, value, data, false, 0));
        emit Proposed(id, msg.sender, to, value);
        _confirm(id);
    }

    function confirm(uint256 id) external onlyOwner { _confirm(id); }

    function revoke(uint256 id) external onlyOwner {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (!confirmed[id][msg.sender]) revert NotEnough();
        confirmed[id][msg.sender] = false;
        p.confirmations -= 1;
        emit Revoked(id, msg.sender);
    }

    function execute(uint256 id) external onlyOwner returns (bytes memory) {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (p.confirmations < threshold) revert NotEnough();
        p.executed = true;
        (bool ok, bytes memory ret) = p.to.call{value: p.value}(p.data);
        if (!ok) revert CallFailed(ret);
        emit Executed(id);
        return ret;
    }

    /// Change owners / threshold: only as a proposal executed by the multisig.
    function setOwners(address[] calldata owners_, uint8 threshold_) external {
        if (msg.sender != address(this)) revert NotOwner();
        for (uint256 i = 0; i < owners.length; i++) isOwner[owners[i]] = false;
        _setOwners(owners_, threshold_);
    }

    function ownerCount() external view returns (uint256) { return owners.length; }
    function proposalCount() external view returns (uint256) { return proposals.length; }

    function _confirm(uint256 id) private {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (confirmed[id][msg.sender]) revert Twice();
        confirmed[id][msg.sender] = true;
        p.confirmations += 1;
        emit Confirmed(id, msg.sender);
    }

    function _setOwners(address[] memory owners_, uint8 threshold_) private {
        if (threshold_ < 2 || threshold_ > owners_.length || owners_.length > 20) revert BadConfig();
        delete owners;
        for (uint256 i = 0; i < owners_.length; i++) {
            address o = owners_[i];
            if (o == address(0) || isOwner[o]) revert BadConfig();
            isOwner[o] = true;
            owners.push(o);
        }
        threshold = threshold_;
    }
}

contracts/StableGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20Permit {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
}

interface INeuroJobs {
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256);
}

/// ZetaphyOracle's consumer surface: a USD price (18 decimals) or a revert.
interface IPriceOracle {
    function price(address asset) external view returns (uint256 value, uint256 updatedAt);
}

/// @title StableGateway: use the Neuro network paying only in a stablecoin
/// @notice A user who holds a stablecoin but no ZETAPHY signs a job request.
///         Anyone (a "relayer") submits it and pays the gas; in the same
///         transaction the gateway takes the user's stablecoin (the cost of
///         the ZETAPHY fee, plus the relayer's tip) and pays the job fee in
///         ZETAPHY from its own reserve.
///         Price: ZetaphyOracle.price(zetaAsset) (ZETAPHY in USD, guarded: TWAP of
///         the DEX, Pyth, deviation, staleness, circuit breaker), and for each
///         accepted stablecoin either its own oracle price or a $1 peg. When the
///         oracle has no valid price the request reverts (PriceUnavailable, with
///         the oracle's reason): never a silently wrong price.
///         TESTNET FALLBACK: a fixed price per token (stablecoin units per 1
///         ZETAPHY), used ONLY while governance switched testnetFixedPrices on
///         (TestnetFixedPricesSet event; priceSource() says so). It is not a
///         market price; it exists for testnet bring-up before the oracle has a
///         TWAP window, and is off by default.
///         Roles: the owner (the ZetaphyTimelock) sets everything and moves funds;
///         guardians (named by the owner) may pause requests at once.
contract StableGateway {
    INeuroJobs public immutable jobs;
    address public owner;
    mapping(address => bool) public guardian;
    bool public paused;

    IPriceOracle public oracle;
    /// The asset id of ZETAPHY in the oracle (the DEX's wrapped ZETAPHY).
    address public zetaAsset;

    struct TokenConfig {
        bool accepted;
        bool oraclePriced;   // false: counted as $1 (a USD stablecoin)
        uint8 decimals;
    }
    mapping(address => TokenConfig) public tokens;

    /// TESTNET ONLY: stablecoin base units per 1 ZETAPHY (1e18 wei), used only while testnetFixedPrices is on.
    bool public testnetFixedPrices;
    mapping(address => uint256) public testnetFixedPrice;
    mapping(address => uint256) public nonces;

    bytes32 public constant REQUEST_TYPEHASH = keccak256(
        "JobRequest(address user,address token,bytes32 chain,string target,uint256 fee,uint256 tip,uint256 maxCost,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    struct JobRequest {
        address user;
        address token;
        bytes32 chain;
        string target;
        uint256 fee;      // ZETAPHY (wei) the job pays
        uint256 tip;      // stablecoin units to the relayer
        uint256 maxCost;  // the most stablecoin the user agrees to spend (cost + tip)
        uint256 nonce;
        uint256 deadline;
    }

    struct Permit { uint256 value; uint256 deadline; uint8 v; bytes32 r; bytes32 s; }

    event OracleSet(address oracle, address zetaAsset);
    event TokenSet(address indexed token, bool accepted, bool oraclePriced, uint8 decimals);
    event TestnetFixedPricesSet(bool on);
    event TestnetFixedPriceSet(address indexed token, uint256 pricePerZeta);
    event Paid(uint256 indexed jobId, address indexed user, address indexed token, uint256 cost, uint256 tip, address relayer);
    event OwnerChanged(address owner);
    event GuardianSet(address indexed who, bool on);
    event Paused(address indexed by);
    event Unpaused();

    error NotOwner();
    error NotGuardian();
    error GatewayPaused();
    error Expired();
    error BadNonce();
    error BadSignature();
    error NotAccepted();
    error TooExpensive();
    error ReserveLow();
    error NoPriceSource();
    error PriceUnavailable(bytes reason);

    constructor(INeuroJobs jobs_) {
        jobs = jobs_;
        owner = msg.sender;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    receive() external payable {} // ZETAPHY reserve top-up

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    function setOwner(address o) external onlyOwner {
        owner = o;
        emit OwnerChanged(o);
    }

    function setGuardian(address who, bool on) external onlyOwner {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// A guardian (or the owner) stops new requests at once; only the owner restarts them.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != owner) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused();
    }

    function setOracle(IPriceOracle o, address zetaAsset_) external onlyOwner {
        oracle = o;
        zetaAsset = zetaAsset_;
        emit OracleSet(address(o), zetaAsset_);
    }

    /// Accept (or stop accepting) a stablecoin; oraclePriced: its own oracle price, else $1.
    function setToken(address token, bool accepted, bool oraclePriced, uint8 decimals) external onlyOwner {
        require(decimals <= 30, "decimals");
        tokens[token] = TokenConfig(accepted, oraclePriced, decimals);
        emit TokenSet(token, accepted, oraclePriced, decimals);
    }

    /// TESTNET ONLY: switch the fixed prices on (they replace the oracle) or off.
    function setTestnetFixedPrices(bool on) external onlyOwner {
        testnetFixedPrices = on;
        emit TestnetFixedPricesSet(on);
    }

    /// TESTNET ONLY: stablecoin units per 1 ZETAPHY, used only while testnetFixedPrices is on.
    function setTestnetFixedPrice(address token, uint256 price) external onlyOwner {
        testnetFixedPrice[token] = price;
        emit TestnetFixedPriceSet(token, price);
    }

    /// Stablecoin proceeds go to the treasury the operator names.
    function sweep(address token, address to, uint256 amount) external onlyOwner {
        require(IERC20Permit(token).transfer(to, amount), "transfer failed");
    }

    function withdrawReserve(address payable to, uint256 amount) external onlyOwner {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "transfer failed");
    }

    /// Where quote() takes its price from.
    function priceSource() external view returns (string memory) {
        if (testnetFixedPrices) return "TESTNET FIXED PRICE (set by governance, not a market price)";
        if (address(oracle) == address(0)) return "none";
        return "ZetaphyOracle";
    }

    /// Stablecoin cost of a job fee, rounded up.
    function quote(address token, uint256 fee) public view returns (uint256) {
        TokenConfig memory t = tokens[token];
        if (!t.accepted) revert NotAccepted();
        if (testnetFixedPrices) {
            uint256 p = testnetFixedPrice[token];
            if (p == 0) revert NotAccepted();
            return (fee * p + 1e18 - 1) / 1e18;
        }
        if (address(oracle) == address(0)) revert NoPriceSource();
        uint256 zetaUsd = _price(zetaAsset);
        uint256 tokenUsd = t.oraclePriced ? _price(token) : 1e18;
        // fee (18 decimals) x ZETAPHY's USD price / the token's USD price, in the token's units, rounded up
        uint256 usd = fee * zetaUsd;                       // USD x 1e36
        uint256 den = tokenUsd * 1e18;
        return (usd * (10 ** uint256(t.decimals)) + den - 1) / den;
    }

    function _price(address asset) private view returns (uint256 v) {
        try oracle.price(asset) returns (uint256 value, uint256) { v = value; } catch (bytes memory reason) { revert PriceUnavailable(reason); }
        if (v == 0) revert PriceUnavailable("");
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function hashRequest(JobRequest calldata q) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(), keccak256(abi.encode(
            REQUEST_TYPEHASH, q.user, q.token, q.chain, keccak256(bytes(q.target)), q.fee, q.tip, q.maxCost, q.nonce, q.deadline))));
    }

    /// The user already approved this gateway for the stablecoin.
    function request(JobRequest calldata q, bytes calldata sig) external returns (uint256) {
        return _request(q, sig);
    }

    /// Same, with an EIP-2612 permit so the user needs no approve transaction (no gas at all).
    function requestWithPermit(JobRequest calldata q, bytes calldata sig, Permit calldata p) external returns (uint256) {
        // A failed permit is fine if an allowance already exists (e.g. someone front-ran the permit).
        try IERC20Permit(q.token).permit(q.user, address(this), p.value, p.deadline, p.v, p.r, p.s) {} catch {}
        return _request(q, sig);
    }

    function _request(JobRequest calldata q, bytes calldata sig) private returns (uint256 jobId) {
        if (paused) revert GatewayPaused();
        if (block.timestamp > q.deadline) revert Expired();
        if (q.nonce != nonces[q.user]) revert BadNonce();
        if (_recover(hashRequest(q), sig) != q.user) revert BadSignature();
        nonces[q.user] = q.nonce + 1;

        uint256 cost = quote(q.token, q.fee);
        if (cost + q.tip > q.maxCost) revert TooExpensive();
        if (address(this).balance < q.fee) revert ReserveLow();

        require(IERC20Permit(q.token).transferFrom(q.user, address(this), cost), "payment failed");
        if (q.tip > 0) require(IERC20Permit(q.token).transferFrom(q.user, msg.sender, q.tip), "tip failed");
        jobId = jobs.requestFor{value: q.fee}(q.user, q.chain, q.target);
        emit Paid(jobId, q.user, q.token, cost, q.tip, msg.sender);
    }

    function _recover(bytes32 digest, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(digest, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes("ZETAPHY StableGateway")), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/TestStable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title TestStable: testnet-only stand-in for USDC / USDT on ZETAPHY testnet
/// @notice Worthless by design. Anyone can take 1,000 from the faucet once a
///         day. Real USDC arrives only through the bridge in stage 3.
///         ERC-20 + EIP-2612 permit, 6 decimals like USDC/USDT.
contract TestStable {
    string public name;
    string public symbol;
    uint8 public constant decimals = 6;
    uint256 public constant FAUCET_AMOUNT = 1_000 * 10 ** 6;
    uint256 public constant FAUCET_EVERY = 1 days;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public nonces;
    mapping(address => uint256) public lastFaucet;

    bytes32 public constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    function faucet() external {
        _drip(msg.sender);
    }

    /// Lets a relay pay the gas for someone who has no ZETAPHY yet.
    function faucetTo(address to) external {
        _drip(to);
    }

    function _drip(address to) private {
        require(to != address(0), "to zero");
        require(block.timestamp >= lastFaucet[to] + FAUCET_EVERY, "faucet: once a day");
        lastFaucet[to] = block.timestamp;
        totalSupply += FAUCET_AMOUNT;
        balanceOf[to] += FAUCET_AMOUNT;
        emit Transfer(address(0), to, FAUCET_AMOUNT);
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _move(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            require(a >= value, "allowance");
            allowance[from][msg.sender] = a - value;
        }
        _move(from, to, value);
        return true;
    }

    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        require(block.timestamp <= deadline, "permit: expired");
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(),
            keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))));
        require(uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0, "permit: bad s");
        address signer = ecrecover(digest, v, r, s);
        require(signer != address(0) && signer == owner, "permit: bad signature");
        allowance[owner][spender] = value;
        emit Approval(owner, spender, value);
    }

    function _move(address from, address to, uint256 value) private {
        require(to != address(0), "to zero");
        uint256 b = balanceOf[from];
        require(b >= value, "balance");
        unchecked { balanceOf[from] = b - value; }
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes(name)), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/ThreatRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// The parts of NeuroIdentity (ERC-8004 identity registry) this registry reads:
/// who has claimed the identity of a target ("eip155:<id>:0x<lowercase hex>").
interface IIdentityOwners {
    function agentOfTarget(bytes32 caip10Hash) external view returns (uint256);
    function ownerOf(uint256 agentId) external view returns (address);
}

/// @title ThreatRegistry: Neuro's immune system (stage 4)
/// @notice A flag here states a reproducible fact about code, not guilt: what
///         the code can do, or did in a reproducible test (Reason), with the
///         evidence that shows it (a Neuro reportHash or the hash of another
///         reproducible report, plus a short URI). Active, bonded NeuroJobs
///         runners with a track record vote to flag a key. At QUORUM distinct
///         votes the key is flagged, and every Neuro instance that reads this
///         registry warns about it, on every chain. A flag is cleared the same
///         way (QUORUM votes to clear).
///
///         Keys:
///           - a code fingerprint (Neuro's fp1: sha256 of the code with
///             addresses/immutables masked), so every copy of the code is found
///           - codeKey(h):         EVM code with extcodehash h on ZETAPHY
///           - addressKey(id, a):  address a on the chain with EVM id `id`
///         voteBatch lets a runner vote on a fingerprint together with the code
///         hashes and addresses it found for it, in one tx (one evidence for the
///         batch); each key still needs its own quorum. BridgeAirlock / BridgeGuard
///         hold (and, once enforced, refuse) flagged sources and recipients, and
///         the ZETAPHY wallet refuses to sign calls to code with an enforced flag.
///
///         Evidence: every flag vote carries one (reportHash != 0, uri at most
///         MAX_URI bytes); every vote's evidence is in its Voted event, and the
///         evidence of the round's first flag vote (the one whose reason the flag
///         shows) is stored: evidenceOf(key).
///
///         Right of reply: the parties behind a key may post responses (at most
///         MAX_RESPONSE bytes each) that wallets show next to the flag, each with
///         its author's address. Responses are kept per (key, author): an author
///         changes or removes (empty text) only its own, never another's; at most
///         MAX_RESPONSES per key (a new author past that replaces the oldest one,
///         never the governance-assigned responder's). responseAt(key, i) lists
///         them: the governance-assigned responder's first, then newest first;
///         responseOf(key) is responseAt(key, 0).
///         Who may answer for a key (respond / appeal, `mayAnswer`):
///           - addressKey(block.chainid, a) for an address a on ZETAPHY: a itself or,
///             for a contract, its current owner();
///           - addressKey(id, a) on any EVM chain (and on ZETAPHY): the owner of
///             the claimed ERC-8004 identity of "eip155:<id>:<a>" in NeuroIdentity
///             (optional: `identity`, zero = off);
///           - codeKey(h) and fp1 keys: ONLY the responder governance assigned to
///             the key (`responder`). Anyone can deploy a contract with the same
///             code and an owner() of their choosing, so code and fingerprint keys
///             have no on-chain owner to ask;
///           - any key: once governance assigned a responder, only it may answer
///             for that key (setResponder(key, 0) gives address keys back to the
///             routes above). Others' existing responses stay until their authors
///             remove them.
///         A response never changes the flag.
///
///         Appeal: whoever may answer for a flagged key (mayAnswer: so for code and
///         fp1 keys only their assigned responder) may appeal(key), paying
///         `appealBond` (appeals are off until governance sets a community fund).
///         That opens an appeal round, voted with voteAppeal, by runners who
///         neither voted for the flag nor backed it (voted/backed of the round that
///         set it, `flagRound`): fresh eyes. The appellant cannot vote in it.
///           - QUORUM appeal votes to clear: the flag is cleared, the bond is
///             refunded, and each runner who set the flag gets a strike
///             (`strikes`, a public record only: see below).
///           - QUORUM appeal votes to keep: the flag stands; the bond goes to the
///             community fund (not to the voters, so reviewers gain nothing by
///             keeping a flag).
///           - Neither within `appealWindow`: anyone may expireAppeal; the bond is
///             refunded (nobody reviewed it: not the appellant's fault).
///           - The flag cleared otherwise meanwhile (the normal clear vote,
///             governance protecting the key): the bond is refunded.
///         Funds are never pushed inside these calls: refunds are credited
///         (`owed`, taken with withdraw) and the fund's share with payFund, so
///         a failing receiver cannot block a vote. payFund pays the last non-zero
///         community fund governance set (`fundPayee`), so turning appeals off
///         (fund = 0) never sends kept bonds to address(0). Strikes slash nothing: the
///         runners' bonds are in NeuroJobs, and an automatic penalty would let a
///         colluding appeal quorum silence honest runners; governance and the
///         runners' tools can read them.
///
///         Checks on the runners (a small quorum must not freeze bridges or wallets):
///           - Warning, hold and enforcement. isFlagged / is*Flagged answer at
///             once (Neuro warns, the wallet shows a warning). is*Held answer true
///             once a flag is `holdDelay` old (a governance knob, e.g. 10 minutes,
///             below enforceDelay), or at once when it is fast (below) or a guardian
///             or governance called holdNow(key). Things that only HOLD (reversible:
///             BridgeAirlock's release, BridgeGuard's inbound queue and outbound)
///             read those, so two runners alone cannot freeze anyone's bridging
///             at once: governance and guardians get holdDelay to look. is*Enforced
///             answer true only once a flag is `enforceDelay` old; everything that
///             REFUSES (BridgeAirlock's ThreatFlagged, NeuroLane watchers, the
///             wallet's refusal) reads those.
///             What ends a hold: the flag cleared (QUORUM clear votes, or an upheld
///             appeal) or governance protecting the key. Nothing else does: a
///             source-chain LockBox has no refund path, so a held transfer waits
///             in BridgeAirlock (and a held mint in BridgeGuard's queue) until then.
///           - Fast lane. A flag is enforced at once (no enforceDelay) when
///             `fastQuorum` distinct runners stand behind it (a supermajority,
///             governance's knob, default 2 x quorum; runners can still add
///             their vote to a flag that is already standing), or when
///             governance or a guardian calls enforceNow(key) (which holds at once
///             too). Clearing (same quorum) or protecting the key lifts it as before.
///           - Protected keys. Governance (the chain's gov module through
///             MsgEVMCall, or a multisig) can protect keys, e.g. the bridge's
///             own contracts and code hashes or a common token's code. A
///             protected key cannot be flagged; protecting a flagged key clears it.
contract ThreatRegistry {
    IRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed; // verdicts a runner must have had accepted to vote

    /// What the code does, or did in a reproducible test. Never a claim about intent.
    enum Reason {
        None,
        CannotSellInSimulation,   // a simulated buy worked, the sell failed or returned almost nothing
        UnlimitedMint,            // an address can mint new tokens without a cap
        OwnerCanBlockTransfers,   // an owner/admin can stop holders from transferring or selling
        OwnerCanMoveHolderFunds,  // an owner/admin can move or burn tokens or funds held by others
        SameNameAsKnownToken,     // same name/symbol as a known token, at a different address
        SweepsApprovedTokens,     // in a test, moved tokens approved to it to an address the holder did not choose
        Other                     // another code fact: see the evidence
    }

    struct Entry {
        bool flagged;
        Reason reason;
        uint64 updatedAt;
        uint32 round;        // bumps on every flag/clear so old votes stop counting
        uint8 votes;
        bool fast;           // enforced at once (fastQuorum or enforceNow)
        uint8 support;       // distinct runners behind the standing flag
        uint64 fastAt;       // when it went fast
    }

    struct Evidence {
        bytes32 reportHash;  // Neuro reportHash, or the hash of another reproducible report
        address by;          // the runner who gave it
        uint64 at;
        string uri;          // where the report can be read (at most MAX_URI bytes)
    }

    struct Response {
        address by;
        uint64 at;
        uint256 chainId;     // the subject answered for (0: a governance-assigned responder)
        address account;
        string text;         // at most MAX_RESPONSE bytes
    }

    struct Appeal {
        address appellant;   // zero: no appeal open
        uint64 openedAt;
        uint32 flagRound;    // the round that set the flag: its voters and backers may not vote
        uint8 clearVotes;
        uint8 keepVotes;
        uint128 bond;
    }

    bytes16 private constant HEX = "0123456789abcdef";
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_RESPONSE = 500;
    uint256 public constant MAX_RESPONSES = 8;     // per key
    uint256 public constant MAX_APPEAL_BOND = 1000 ether;
    uint64 public constant MIN_APPEAL_WINDOW = 1 days;
    uint64 public constant MAX_APPEAL_WINDOW = 90 days;

    mapping(bytes32 => Entry) public entries;
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public voted;
    /// Runners who backed a standing flag after it was set (fast lane); kept apart
    /// from `voted`, which stays exactly the quorum that set it (ThreatReports pays those).
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public backed;
    bytes32[] public flaggedList;
    mapping(bytes32 => Evidence) private _evidence;
    /// Flag voters per round (at most quorum each): the runners an upheld appeal strikes.
    mapping(bytes32 => mapping(uint32 => address[])) private _flaggers;

    /// The chain's gov module (MsgEVMCall) or a multisig.
    address public governance;
    /// Seconds a flag waits before the is*Enforced views (which block) report it.
    uint64 public enforceDelay;
    uint64 public constant MAX_ENFORCE_DELAY = 30 days;
    /// Keys governance vouched for: never flagged.
    mapping(bytes32 => bool) public protectedKey;
    /// Distinct flag votes that enforce a standing flag at once (0: off).
    uint8 public fastQuorum;
    /// Guardians (set by governance) may enforceNow / holdNow; they cannot flag, clear or protect.
    mapping(address => bool) public guardian;
    /// Seconds a flag waits before the is*Held views (which hold bridging) report it.
    uint64 public holdDelay;
    /// A guardian's (or governance's) holdNow: the flag's round it holds at once, and when.
    struct HoldNow { uint32 round; uint64 at; }
    mapping(bytes32 => HoldNow) public heldNow;

    // ---- right of reply and appeal ----
    IIdentityOwners public identity;               // zero: the identity route is off
    mapping(bytes32 => address) public responder;  // governance-assigned; exclusive once set
    mapping(bytes32 => mapping(address => Response)) private _responses; // per (key, author)
    mapping(bytes32 => address[]) private _authors;                      // authors with a response, least recently updated first
    uint128 public appealBond;
    uint64 public appealWindow = 14 days;
    address public communityFund;                  // zero: appeals off
    address public fundPayee;                      // the last non-zero communityFund: where payFund sends
    mapping(bytes32 => Appeal) public appeals;
    mapping(bytes32 => uint32) public appealCount; // appeal ids per key, from 1
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public appealVoted;
    mapping(address => uint32) public strikes;
    mapping(address => uint256) public owed;       // refunds, taken with withdraw()
    uint256 public fundOwed;                       // the community fund's share, sent with payFund()

    event Voted(bytes32 indexed fingerprint, address indexed runner, bool flag, Reason reason, bytes32 reportHash, string uri);
    event Flagged(bytes32 indexed fingerprint, Reason reason);
    event Cleared(bytes32 indexed fingerprint);
    event Protected(bytes32 indexed key, bool on);
    event EnforceDelaySet(uint64 delay);
    event GovernanceSet(address governance);
    event Supported(bytes32 indexed key, address indexed runner, uint8 support, bytes32 reportHash);
    event FastEnforced(bytes32 indexed key, address indexed by);
    event FastQuorumSet(uint8 fastQuorum);
    event GuardianSet(address indexed who, bool on);
    event Responded(bytes32 indexed key, address indexed by, uint256 chainId, address account, string text);
    event ResponderSet(bytes32 indexed key, address responder);
    event IdentitySet(address identity);
    event AppealsSet(uint128 bond, uint64 window, address fund);
    event Appealed(bytes32 indexed key, uint32 indexed id, address indexed appellant, uint128 bond);
    event AppealVoted(bytes32 indexed key, uint32 indexed id, address indexed runner, bool clear, bytes32 reportHash, string uri);
    event AppealClosed(bytes32 indexed key, uint32 indexed id, uint8 outcome); // 1 cleared, 2 kept, 3 expired, 4 flag cleared otherwise
    event Struck(address indexed runner, bytes32 indexed key, uint32 strikes);
    event Paid(address indexed to, uint256 amount);
    event HoldDelaySet(uint64 delay);
    event HeldNow(bytes32 indexed key, address indexed by);

    error NotRunner();
    error AlreadyVoted();
    error NoChange();
    error NotGovernance();
    error ProtectedKey(bytes32 key);
    error NotGuardian();
    error NotFlagged();
    error NoEvidence();
    error TooLong();
    error NotResponder();
    error AppealsOff();
    error BadBond(uint256 bond);
    error AppealOpen();
    error NoAppeal();
    error AppealExpired();
    error NotYet();
    error NotFresh();
    error PayFailed();
    error NoFund();

    constructor(IRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_, uint64 enforceDelay_) {
        require(quorum_ >= 2, "quorum");
        require(governance_ != address(0), "governance");
        require(enforceDelay_ <= MAX_ENFORCE_DELAY, "delay");
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
        enforceDelay = enforceDelay_;
        fastQuorum = quorum_ > 127 ? 255 : quorum_ * 2;
        holdDelay = enforceDelay_ >= 20 minutes ? 10 minutes : enforceDelay_ / 2;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    /// Applies to flags already standing too (they are measured from when they were set).
    function setEnforceDelay(uint64 d) external onlyGov {
        require(d <= MAX_ENFORCE_DELAY, "delay");
        require(holdDelay == 0 || d > holdDelay, "holdDelay"); // holds start before enforcement
        enforceDelay = d;
        emit EnforceDelaySet(d);
    }

    /// Seconds before a flag holds bridging (is*Held), unless fast or held now.
    /// Below enforceDelay (or 0: a flag holds at once). Applies to standing flags too.
    function setHoldDelay(uint64 d) external onlyGov {
        require(d == 0 || d < enforceDelay, "holdDelay");
        holdDelay = d;
        emit HoldDelaySet(d);
    }

    /// Fast lane: this many distinct runners behind a flag enforce it at once.
    /// Above quorum (a supermajority), or 0 to turn the fast lane off.
    function setFastQuorum(uint8 f) external onlyGov {
        require(f == 0 || f > quorum, "fastQuorum");
        fastQuorum = f;
        emit FastQuorumSet(f);
    }

    function setGuardian(address who, bool on) external onlyGov {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// NeuroIdentity, for the identity route of the right of reply (zero: off).
    function setIdentity(IIdentityOwners i) external onlyGov {
        identity = i;
        emit IdentitySet(address(i));
    }

    /// The only party that may answer for `key` (zero: the on-chain routes again).
    function setResponder(bytes32 key, address who) external onlyGov {
        responder[key] = who;
        emit ResponderSet(key, who);
    }

    /// Appeal bond, window and the community fund that keeps bonds of appeals
    /// that confirmed the flag. A zero fund turns appeals off (open ones still
    /// close normally); a new bond applies to new appeals only.
    function setAppeals(uint128 bond, uint64 window, address fund) external onlyGov {
        require(bond <= MAX_APPEAL_BOND, "bond");
        require(window >= MIN_APPEAL_WINDOW && window <= MAX_APPEAL_WINDOW, "window");
        appealBond = bond;
        appealWindow = window;
        communityFund = fund;
        if (fund != address(0)) fundPayee = fund;
        emit AppealsSet(bond, window, fund);
    }

    /// Governance or a guardian enforces a standing flag at once (money moving
    /// now). Only a flag the runners' quorum already set; protected keys can
    /// never be flagged, so never enforced either.
    function enforceNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast) revert NoChange();
        _fast(e, key);
    }

    /// Governance or a guardian holds a standing flag at once (no holdDelay):
    /// bridging of its party stops now, as reversible as any hold. Only a flag
    /// the runners' quorum already set; it ends with the flag (clear / protect).
    function holdNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast || heldNow[key].round == e.round) revert NoChange();
        heldNow[key] = HoldNow(e.round, uint64(block.timestamp));
        emit HeldNow(key, msg.sender);
    }

    function _fast(Entry storage e, bytes32 key) private {
        e.fast = true;
        e.fastAt = uint64(block.timestamp);
        emit FastEnforced(key, msg.sender);
    }

    /// Protect (or unprotect) keys. Protecting clears a flag at once and drops
    /// any votes in progress; unprotecting does not flag anything back.
    function setProtected(bytes32[] calldata keys, bool on) external onlyGov {
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            protectedKey[k] = on;
            emit Protected(k, on);
            if (!on) continue;
            Entry storage e = entries[k];
            if (e.flagged || e.votes != 0) {
                bool was = e.flagged;
                _reset(e, k);
                e.round += 1;
                e.updatedAt = uint64(block.timestamp);
                if (was) emit Cleared(k);
            }
        }
    }

    /// keccak256 of empty code: every account without code has it, so it is never a threat.
    bytes32 public constant EMPTY_CODEHASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    /// The key under which EVM code with this extcodehash is flagged.
    function codeKey(bytes32 codeHash) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.code", codeHash));
    }

    /// The key under which an address on a given chain (EVM chain id) is flagged.
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.address", chainId, who));
    }

    function _checkRunner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function _checkEvidence(bool required, bytes32 reportHash, string calldata uri) private pure {
        if (required && reportHash == bytes32(0)) revert NoEvidence();
        if (bytes(uri).length > MAX_URI) revert TooLong();
    }

    /// Vote to flag (flag = true, with a reason and its evidence) or to clear
    /// (flag = false; evidence optional). `fingerprint` is any key: a fp1
    /// fingerprint, codeKey(..) or addressKey(..).
    function vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && protectedKey[fingerprint]) revert ProtectedKey(fingerprint);
        if (!_vote(fingerprint, flag, reason, reportHash, uri)) revert NoChange();
    }

    /// One runner's votes on several keys at once, e.g. a fingerprint plus the
    /// code hashes and addresses of its copies, with one evidence for the batch.
    /// Keys already in that state, or already voted on by this runner this
    /// round, are skipped (not an error), so the same list can be sent again as
    /// copies are found. Protected keys are skipped when flagging. On a key
    /// already flagged, a flag vote adds this runner's support (toward
    /// fastQuorum) once.
    function voteBatch(bytes32[] calldata keys, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external returns (uint256 counted) {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && reason == Reason.None) revert NoChange();
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            Entry storage e = entries[k];
            if (flag && protectedKey[k]) continue;
            if (flag && e.flagged) { if (_support(e, k, reportHash)) counted++; continue; }
            if (e.flagged == flag || voted[k][e.round][msg.sender]) continue;
            _vote(k, flag, reason, reportHash, uri);
            counted++;
        }
        if (counted == 0) revert NoChange();
    }

    /// A flag vote on a standing flag: one more runner behind it (once per
    /// runner, counting the quorum that set it). False when nothing changed.
    function _support(Entry storage e, bytes32 key, bytes32 reportHash) private returns (bool) {
        if (e.fast || e.support == type(uint8).max) return false;
        uint32 r = e.round - 1; // the round that set the flag
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender]) return false;
        backed[key][r][msg.sender] = true;
        e.support += 1;
        emit Supported(key, msg.sender, e.support, reportHash);
        if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, key);
        return true;
    }

    /// The flag (or the votes in progress) is gone: an open appeal ends with its bond refunded.
    function _reset(Entry storage e, bytes32 key) private {
        e.flagged = false;
        e.reason = Reason.None;
        e.votes = 0;
        e.fast = false;
        e.support = 0;
        e.fastAt = 0;
        delete _evidence[key];
        if (appeals[key].appellant != address(0)) _closeAppeal(key, 4);
    }

    function _vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) private returns (bool) {
        Entry storage e = entries[fingerprint];
        if (flag && reason == Reason.None) return false;
        if (flag && e.flagged) {
            if (voted[fingerprint][e.round - 1][msg.sender] || backed[fingerprint][e.round - 1][msg.sender]) revert AlreadyVoted();
            return _support(e, fingerprint, reportHash);
        }
        if (e.flagged == flag) return false;
        if (voted[fingerprint][e.round][msg.sender]) revert AlreadyVoted();
        voted[fingerprint][e.round][msg.sender] = true;
        e.votes += 1;
        if (flag) {
            _flaggers[fingerprint][e.round].push(msg.sender);
            if (e.reason == Reason.None) { // the round's first flag vote: its reason and evidence are what the flag shows
                e.reason = reason;
                _evidence[fingerprint] = Evidence(reportHash, msg.sender, uint64(block.timestamp), uri);
            }
        }
        emit Voted(fingerprint, msg.sender, flag, reason, reportHash, uri);
        if (e.votes >= quorum) {
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            if (flag) {
                e.flagged = true;
                e.support = e.votes;
                e.votes = 0;
                flaggedList.push(fingerprint);
                emit Flagged(fingerprint, e.reason);
                if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, fingerprint);
            } else {
                _reset(e, fingerprint);
                emit Cleared(fingerprint);
            }
        }
        return true;
    }

    // ---- right of reply ----

    /// "eip155:<chainId>:0x<lowercase hex>", NeuroIdentity's spelling of an EVM target.
    function _caip10(uint256 chainId, address a) private pure returns (bytes memory out) {
        bytes memory digits = new bytes(78);
        uint256 n = 78;
        uint256 v = chainId;
        do { digits[--n] = bytes1(uint8(48 + v % 10)); v /= 10; } while (v != 0);
        bytes memory id = new bytes(78 - n);
        for (uint256 i = 0; i < id.length; i++) id[i] = digits[n + i];
        bytes memory hexa = new bytes(40);
        uint160 x = uint160(a);
        for (uint256 i = 40; i > 0; i--) { hexa[i - 1] = HEX[x & 15]; x >>= 4; }
        out = abi.encodePacked("eip155:", id, ":0x", hexa);
    }

    /// The claimed owner of the identity of `account` on chain `chainId` (zero: none, unclaimed or off).
    function _identityOwner(uint256 chainId, address account) private view returns (address) {
        IIdentityOwners idr = identity;
        if (address(idr) == address(0)) return address(0);
        try idr.agentOfTarget(keccak256(_caip10(chainId, account))) returns (uint256 agentId) {
            if (agentId == 0) return address(0);
            try idr.ownerOf(agentId) returns (address o) { return o == address(idr) ? address(0) : o; } catch { return address(0); }
        } catch { return address(0); }
    }

    /// The `owner()` of a contract on this chain (zero: none).
    function _ownerOf(address a) private view returns (address) {
        if (a.code.length == 0) return address(0);
        (bool ok, bytes memory r) = a.staticcall{gas: 50_000}(abi.encodeWithSignature("owner()"));
        if (!ok || r.length < 32) return address(0);
        uint256 w = abi.decode(r, (uint256));
        return w >> 160 == 0 ? address(uint160(w)) : address(0);
    }

    /// May `who` answer for `key` as the party behind (chainId, account)? (See the notice.)
    /// Code keys and fp1 keys: only their governance-assigned responder.
    function mayAnswer(bytes32 key, uint256 chainId, address account, address who) public view returns (bool) {
        address r = responder[key];
        if (r != address(0) || chainId == 0) return r != address(0) && who == r;
        if (who == address(0) || key != addressKey(chainId, account)) return false;
        if (chainId == block.chainid && (who == account || who == _ownerOf(account))) return true;
        return who == _identityOwner(chainId, account);
    }

    /// Post or replace msg.sender's own response to the flag on `key`, as the
    /// party behind (chainId, account) (see the notice). Empty text removes
    /// msg.sender's own response (always allowed to its author). Never changes the flag.
    function respond(bytes32 key, uint256 chainId, address account, string calldata text) external {
        if (bytes(text).length > MAX_RESPONSE) revert TooLong();
        Response storage cur = _responses[key][msg.sender];
        bool had = cur.by != address(0);
        if (bytes(text).length == 0) {
            if (!had) revert NoChange();
            emit Responded(key, msg.sender, cur.chainId, cur.account, text);
            delete _responses[key][msg.sender];
            _dropAuthor(key, msg.sender);
            return;
        }
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        if (had) _dropAuthor(key, msg.sender);
        else if (_authors[key].length >= MAX_RESPONSES) _evictOldest(key);
        _authors[key].push(msg.sender);
        _responses[key][msg.sender] = Response(msg.sender, uint64(block.timestamp), chainId, account, text);
        emit Responded(key, msg.sender, chainId, account, text);
    }

    function _dropAuthor(bytes32 key, address who) private {
        address[] storage a = _authors[key];
        uint256 n = a.length;
        for (uint256 i = 0; i < n; i++) {
            if (a[i] != who) continue;
            for (uint256 j = i + 1; j < n; j++) a[j - 1] = a[j]; // keep the order
            a.pop();
            return;
        }
    }

    /// Full: the least recently updated response goes, never the assigned responder's.
    function _evictOldest(bytes32 key) private {
        address[] storage a = _authors[key];
        address keep = responder[key];
        for (uint256 i = 0; i < a.length; i++) {
            if (a[i] == keep) continue;
            address old = a[i];
            delete _responses[key][old];
            _dropAuthor(key, old);
            return;
        }
    }

    /// How many responses `key` has (at most MAX_RESPONSES, plus none).
    function responseCount(bytes32 key) external view returns (uint256) {
        return _authors[key].length;
    }

    /// The i-th response to `key`: the governance-assigned responder's first (if
    /// it posted one), then the others newest first. Past the end: all zero.
    function responseAt(bytes32 key, uint256 i) public view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        address[] storage a = _authors[key];
        address r = responder[key];
        bool rFirst = r != address(0) && _responses[key][r].by != address(0);
        address who;
        if (rFirst && i == 0) who = r;
        else {
            uint256 k = rFirst ? i - 1 : i; // index among the others, newest first
            for (uint256 j = a.length; j > 0; j--) {
                if (rFirst && a[j - 1] == r) continue;
                if (k == 0) { who = a[j - 1]; break; }
                k--;
            }
        }
        if (who == address(0)) return ("", address(0), 0, 0, address(0));
        Response storage x = _responses[key][who];
        return (x.text, x.by, x.at, x.chainId, x.account);
    }

    /// The first response (responseAt(key, 0)): the assigned responder's, else the newest.
    function responseOf(bytes32 key) external view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        return responseAt(key, 0);
    }

    /// `who`'s own response to `key` (empty: none).
    function responseBy(bytes32 key, address who) external view returns (string memory text, uint64 at, uint256 chainId, address account) {
        Response storage x = _responses[key][who];
        return (x.text, x.at, x.chainId, x.account);
    }

    /// The evidence of the flag on `key` (of the round's first flag vote; while
    /// a flag round is still open, that vote's). Zero when there is none.
    function evidenceOf(bytes32 key) external view returns (bytes32 reportHash, string memory uri, address by, uint64 at) {
        Evidence storage v = _evidence[key];
        return (v.reportHash, v.uri, v.by, v.at);
    }

    // ---- appeal ----

    /// Appeal the standing flag on `key` as the party behind (chainId, account),
    /// paying exactly appealBond. Opens an appeal round (voteAppeal).
    function appeal(bytes32 key, uint256 chainId, address account) external payable returns (uint32 id) {
        if (communityFund == address(0)) revert AppealsOff();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (appeals[key].appellant != address(0)) revert AppealOpen();
        if (msg.value != appealBond) revert BadBond(appealBond);
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        id = ++appealCount[key];
        appeals[key] = Appeal(msg.sender, uint64(block.timestamp), e.round - 1, 0, 0, uint128(msg.value));
        emit Appealed(key, id, msg.sender, uint128(msg.value));
    }

    /// A fresh runner's vote in the open appeal on `key`: clear the flag (clear =
    /// true) or keep it, with its own evidence (the reproduction it ran).
    /// Runners who voted for or backed the flag, and the appellant, cannot vote.
    function voteAppeal(bytes32 key, bool clear, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(true, reportHash, uri);
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp >= uint256(a.openedAt) + appealWindow) revert AppealExpired();
        uint32 r = a.flagRound;
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender] || msg.sender == a.appellant) revert NotFresh();
        uint32 id = appealCount[key];
        if (appealVoted[key][id][msg.sender]) revert AlreadyVoted();
        appealVoted[key][id][msg.sender] = true;
        emit AppealVoted(key, id, msg.sender, clear, reportHash, uri);
        if (clear) {
            if (++a.clearVotes < quorum) return;
            address[] storage fl = _flaggers[key][r];
            for (uint256 i = 0; i < fl.length; i++) emit Struck(fl[i], key, ++strikes[fl[i]]);
            _closeAppeal(key, 1);
            Entry storage e = entries[key];
            _reset(e, key);
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            emit Cleared(key);
        } else if (++a.keepVotes >= quorum) {
            _closeAppeal(key, 2);
        }
    }

    /// Nobody decided within appealWindow: the bond is refunded, the flag stands.
    function expireAppeal(bytes32 key) external {
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp < uint256(a.openedAt) + appealWindow) revert NotYet();
        _closeAppeal(key, 3);
    }

    /// outcome 2 (kept): the bond to the community fund; otherwise refunded.
    function _closeAppeal(bytes32 key, uint8 outcome) private {
        Appeal memory a = appeals[key];
        delete appeals[key];
        if (outcome == 2) fundOwed += a.bond;
        else owed[a.appellant] += a.bond;
        emit AppealClosed(key, appealCount[key], outcome);
    }

    /// Take refunded bonds.
    function withdraw() external {
        uint256 amount = owed[msg.sender];
        owed[msg.sender] = 0;
        _pay(msg.sender, amount);
    }

    /// Send kept bonds to the community fund (anyone may call it): the last
    /// non-zero fund governance set, even after appeals were turned off.
    function payFund() external {
        uint256 amount = fundOwed;
        if (amount == 0) return;
        address to = fundPayee;
        if (to == address(0)) revert NoFund();
        fundOwed = 0;
        _pay(to, amount);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
        emit Paid(to, amount);
    }

    // ---- warning views: true as soon as the quorum flagged (Neuro warns on these) ----

    function isFlagged(bytes32 fingerprint) public view returns (bool, Reason) {
        Entry storage e = entries[fingerprint];
        return (e.flagged, e.reason);
    }

    /// EVM code with this code hash (extcodehash) is flagged. Empty code never is.
    function isCodeFlagged(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isFlagged(codeKey(codeHash));
    }

    function isAddressFlagged(uint256 chainId, address who) public view returns (bool, Reason) {
        return isFlagged(addressKey(chainId, who));
    }

    /// For contracts on this chain: `who` itself is flagged, or the code at it is.
    function isContractFlagged(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressFlagged(block.chainid, who);
        if (f) return (f, r);
        return isCodeFlagged(who.codehash);
    }

    // ---- hold views: true once the flag is holdDelay old, at once through the fast
    //      lane or holdNow (these hold bridging, reversibly) ----

    /// When a standing flag starts to hold (0: not flagged).
    function heldFrom(bytes32 key) public view returns (uint64 from) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        from = e.updatedAt + holdDelay;
        if (e.fast && e.fastAt < from) from = e.fastAt;
        HoldNow storage h = heldNow[key];
        if (h.round == e.round && h.at < from) from = h.at;
    }

    function isHeld(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged) return (false, Reason.None);
        if (e.fast || heldNow[key].round == e.round || block.timestamp >= uint256(e.updatedAt) + holdDelay) return (true, e.reason);
        return (false, Reason.None);
    }

    function isCodeHeld(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isHeld(codeKey(codeHash));
    }

    function isAddressHeld(uint256 chainId, address who) public view returns (bool, Reason) {
        return isHeld(addressKey(chainId, who));
    }

    function isContractHeld(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressHeld(block.chainid, who);
        if (f) return (f, r);
        return isCodeHeld(who.codehash);
    }

    // ---- enforcement views: true only once the flag is enforceDelay old, or at once
    //      through the fast lane (these block) ----

    /// When a standing flag starts to be enforced (0: not flagged).
    function enforcedFrom(bytes32 key) public view returns (uint64) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        uint64 normal = e.updatedAt + enforceDelay;
        return e.fast && e.fastAt < normal ? e.fastAt : normal;
    }

    function isEnforced(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged || (!e.fast && block.timestamp < uint256(e.updatedAt) + enforceDelay)) return (false, Reason.None);
        return (true, e.reason);
    }

    function isCodeEnforced(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isEnforced(codeKey(codeHash));
    }

    function isAddressEnforced(uint256 chainId, address who) public view returns (bool, Reason) {
        return isEnforced(addressKey(chainId, who));
    }

    function isContractEnforced(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressEnforced(block.chainid, who);
        if (f) return (f, r);
        return isCodeEnforced(who.codehash);
    }

    function flaggedCount() external view returns (uint256) {
        return flaggedList.length;
    }
}

