// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Test-only recipients for RewardVault.

/// Refuses every payment.
contract RefusingRecipient {
    receive() external payable { revert("no"); }
}

interface IVault {
    function applyShares() external;
    function release() external returns (uint256);
}

/// Tries to re-enter the vault while being paid.
contract ReentrantRecipient {
    IVault public vault;
    uint256 public attempts;
    function setVault(address v) external { vault = IVault(v); }
    receive() external payable {
        attempts += 1;
        try vault.applyShares() {} catch {}
        try vault.release() {} catch {}
    }
}

contracts/VulnerableVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title VulnerableVault: a DELIBERATELY VULNERABLE contract for the bug-hunting prototype
/// @notice TEST ONLY. Never deploy it with anything of value. It is the target of the first
///         BugBounty on the testnet (zetaphy-hub/bounties/vulnerable-vault.json), so that the
///         browser fuzzer, the commit-reveal of findings and the runners' verification can be
///         shown end to end on a bug that really exists.
///
///         The bug: `initialize()` was meant to run once, from the deployment script, but the
///         deployment never calls it and it has no access control. Whoever calls it first
///         becomes the owner and can `sweep` every depositor's money.
contract VulnerableVault {
    address public owner;
    mapping(address => uint256) public balances;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function withdraw(uint256 amount) external {
        require(balances[msg.sender] >= amount, "balance");
        balances[msg.sender] -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "send");
    }

    /// BUG (deliberate): anyone may call this while no owner is set.
    function initialize() external {
        require(owner == address(0), "done");
        owner = msg.sender;
    }

    function sweep(address to) external {
        require(msg.sender == owner, "owner");
        (bool ok, ) = to.call{value: address(this).balance}("");
        require(ok, "send");
    }
}

contracts/WebAuthnVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title WebAuthnVerifier: checks a passkey (WebAuthn) assertion on chain
/// @notice Stateless helper shared by LabelRegistry (human labels) and
///         AgentPolicyWallet (emergency freeze by the owner's passkey).
///         The P-256 (secp256r1) signature is checked by the precompile at
///         0x…0100 that cosmos/evm ships (RIP-7212 interface: input
///         hash ‖ r ‖ s ‖ x ‖ y, output 32 bytes = 1 when valid, empty
///         otherwise). ZETAPHY's genesis enables it (active_static_precompiles
///         in zetaphy-chain/setup-node.sh).
///
///         What is checked, as a relying party would (WebAuthn §7.2):
///           - clientDataJSON has "type":"webauthn.get" and
///             "challenge":"<base64url of the 32-byte challenge>";
///           - authenticatorData starts with rpIdHash (sha256 of the site's
///             host name; 0 = any site) and has the user-present flag, and
///             the user-verified flag when requireUV;
///           - the signature is over sha256(authenticatorData ‖ sha256(clientDataJSON)).
///         Not checked: the origin inside clientDataJSON (rpIdHash already
///         binds the site), the signature counter (passkeys that sync keep it
///         at 0), and attestation (who made the authenticator).
contract WebAuthnVerifier {
    address public constant P256 = 0x0000000000000000000000000000000000000100;

    bytes1 private constant FLAG_UP = 0x01;
    bytes1 private constant FLAG_UV = 0x04;

    /// A passkey's answer to navigator.credentials.get(): the authenticator
    /// data, the client data JSON and the signature as (r, s).
    struct Assertion {
        bytes authenticatorData;
        bytes clientDataJSON;
        uint256 r;
        uint256 s;
    }

    /// True when `a` is a valid assertion of the passkey (x, y) over `challenge`.
    function verify(bytes32 challenge, Assertion calldata a, uint256 x, uint256 y, bytes32 rpIdHash, bool requireUV)
        external view returns (bool)
    {
        if (!_flagsOk(a.authenticatorData, rpIdHash, requireUV)) return false;
        if (!_contains(a.clientDataJSON, bytes('"type":"webauthn.get"'))) return false;
        if (!_contains(a.clientDataJSON, abi.encodePacked('"challenge":"', base64url(challenge), '"'))) return false;
        bytes32 h = sha256(abi.encodePacked(a.authenticatorData, sha256(a.clientDataJSON)));
        (bool ok, bytes memory ret) = P256.staticcall(abi.encode(h, a.r, a.s, x, y));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _flagsOk(bytes calldata authData, bytes32 rpIdHash, bool requireUV) private pure returns (bool) {
        if (authData.length < 37) return false;
        if (rpIdHash != bytes32(0) && bytes32(authData[0:32]) != rpIdHash) return false;
        bytes1 flags = authData[32];
        if (flags & FLAG_UP == 0) return false;
        if (requireUV && flags & FLAG_UV == 0) return false;
        return true;
    }

    /// base64url without padding of 32 bytes (43 characters), as WebAuthn
    /// writes the challenge in clientDataJSON.
    function base64url(bytes32 data) public pure returns (string memory) {
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
        bytes memory out = new bytes(43);
        uint256 v = uint256(data);
        // 32 bytes = 256 bits = 42 full 6-bit groups + 4 bits (padded with 2 zero bits)
        for (uint256 i = 0; i < 42; i++) {
            out[i] = table[(v >> (250 - 6 * i)) & 63];
        }
        out[42] = table[(v & 15) << 2];
        return string(out);
    }

    function _contains(bytes calldata hay, bytes memory needle) private pure returns (bool) {
        uint256 n = needle.length;
        if (hay.length < n) return false;
        bytes32 nh = keccak256(needle);
        for (uint256 i = 0; i + n <= hay.length; i++) {
            if (hay[i] == needle[0] && keccak256(hay[i:i + n]) == nh) return true;
        }
        return false;
    }
}

contracts/WorkerReputation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// NeuroJobs' runner record (read-only; the runner's NeuroJobs history counts too).
interface IRepRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// The identity registry (NeuroIdentity, ERC-8004 Identity Registry) a worker may link.
interface IRepIdentity {
    function ownerOf(uint256 tokenId) external view returns (address);
}

/// @title WorkerReputation: on-chain track record of useful-work workers and Neuro runners
/// @notice An ERC-8004-style Reputation Registry for the workers of ZETAPHY's useful-work
///         markets (UsefulWork scan jobs, BugBounty findings) and, read-only, the bonded
///         NeuroJobs runners. Feedback is NOT free text from anyone: only contracts that
///         governance names as reporters (the markets themselves) write outcomes, and each
///         outcome is the result of a commit-reveal round they settled on-chain:
///           - agreed:     the worker's revealed answer matched the accepted result
///           - disagreed:  it revealed a different answer
///           - missed:     it took a seat and never revealed
///           - slashed:    it answered a known-answer (canary) job wrong, or governance slashed it
///           - bugValid / bugInvalid: a bug finding runners accepted / rejected
///         The score (0..1000) is a smoothed success rate:
///             good = agreed + 3*bugValid + NeuroJobs.agreed
///             bad  = disagreed + 2*missed + 5*slashed + 3*bugInvalid + NeuroJobs.rejected
///             score = 1000 * good / (good + bad + PRIOR)
///         PRIOR (5 phantom failures) means a new address starts at 0 and needs a track
///         record before the markets give it important jobs (UsefulWork.minScore). A score
///         is only as good as the markets that feed it: it measures agreement with the
///         other workers (and canaries), not truth.
///
///         Linking: a worker that owns an ERC-8004 agent in NeuroIdentity can link it, and
///         `getSummary(agentId)` then answers in the ERC-8004 reputation shape (count,
///         average 0..100).
///
///         Governance (a ZetaphyTimelock) names reporters and may slash by hand; adding a
///         reporter is a timelocked action, removing one is too (no guardian path: a
///         reporter can only lower or raise scores, it cannot move funds).
contract WorkerReputation {
    uint256 public constant PRIOR = 5;
    uint256 public constant MAX_SCORE = 1000;

    enum Kind { Agreed, Disagreed, Missed, Slashed, BugValid, BugInvalid }

    struct Record {
        uint32 agreed;
        uint32 disagreed;
        uint32 missed;
        uint32 slashed;
        uint32 bugValid;
        uint32 bugInvalid;
        uint64 lastAt;
    }

    address public governance;
    IRepRunners public immutable runners;   // NeuroJobs, or address(0)
    IRepIdentity public immutable identity; // NeuroIdentity, or address(0)
    mapping(address => bool) public reporters;
    mapping(address => Record) private _records;
    mapping(uint256 => address) public workerOfAgent;
    mapping(address => uint256) public agentOfWorker; // 0 = none (agent ids start at 1 in NeuroIdentity)

    event Outcome(address indexed worker, Kind indexed kind, address indexed reporter, bytes32 ref);
    event ReporterSet(address indexed reporter, bool on);
    event AgentLinked(address indexed worker, uint256 indexed agentId);
    event GovernanceChanged(address governance);

    error NotGovernance();
    error NotReporter();
    error NotAgentOwner();
    error ZeroAddress();

    constructor(address governance_, IRepRunners runners_, IRepIdentity identity_) {
        if (governance_ == address(0)) revert ZeroAddress();
        governance = governance_;
        runners = runners_;
        identity = identity_;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---------------------------------------------------------------- writes

    /// A market reports one settled outcome for a worker (ref = the job / finding it was about).
    function record(address worker, Kind kind, bytes32 ref) external {
        if (!reporters[msg.sender]) revert NotReporter();
        _record(worker, kind, ref);
    }

    /// Governance slashes by hand (e.g. proven collusion found off-chain).
    function slash(address worker, bytes32 ref) external onlyGovernance {
        _record(worker, Kind.Slashed, ref);
    }

    function _record(address worker, Kind kind, bytes32 ref) internal {
        Record storage r = _records[worker];
        if (kind == Kind.Agreed) r.agreed++;
        else if (kind == Kind.Disagreed) r.disagreed++;
        else if (kind == Kind.Missed) r.missed++;
        else if (kind == Kind.Slashed) r.slashed++;
        else if (kind == Kind.BugValid) r.bugValid++;
        else r.bugInvalid++;
        r.lastAt = uint64(block.timestamp);
        emit Outcome(worker, kind, msg.sender, ref);
    }

    function setReporter(address reporter, bool on) external onlyGovernance {
        if (reporter == address(0)) revert ZeroAddress();
        reporters[reporter] = on;
        emit ReporterSet(reporter, on);
    }

    function setGovernance(address next) external onlyGovernance {
        if (next == address(0)) revert ZeroAddress();
        governance = next;
        emit GovernanceChanged(next);
    }

    /// Links the caller to an ERC-8004 agent it owns (one agent per worker, one worker per agent).
    function linkAgent(uint256 agentId) external {
        if (address(identity) == address(0) || identity.ownerOf(agentId) != msg.sender) revert NotAgentOwner();
        uint256 old = agentOfWorker[msg.sender];
        if (old != 0) delete workerOfAgent[old];
        address prev = workerOfAgent[agentId];
        if (prev != address(0)) delete agentOfWorker[prev];
        workerOfAgent[agentId] = msg.sender;
        agentOfWorker[msg.sender] = agentId;
        emit AgentLinked(msg.sender, agentId);
    }

    // ---------------------------------------------------------------- reads

    function recordOf(address worker) external view returns (Record memory) {
        return _records[worker];
    }

    /// Good and bad outcome weights (this registry's records plus the NeuroJobs runner record).
    function weights(address worker) public view returns (uint256 good, uint256 bad) {
        Record memory r = _records[worker];
        good = uint256(r.agreed) + 3 * uint256(r.bugValid);
        bad = uint256(r.disagreed) + 2 * uint256(r.missed) + 5 * uint256(r.slashed) + 3 * uint256(r.bugInvalid);
        if (address(runners) != address(0)) {
            try runners.workers(worker) returns (uint128, uint64, bool, uint32 agreed, uint32 rejected) {
                good += agreed;
                bad += rejected;
            } catch {}
        }
    }

    /// 0..1000; 0 for an address with no record.
    function scoreOf(address worker) public view returns (uint256) {
        (uint256 good, uint256 bad) = weights(worker);
        return (MAX_SCORE * good) / (good + bad + PRIOR);
    }

    /// ERC-8004 reputation shape for a linked agent: (outcomes counted, average 0..100).
    function getSummary(uint256 agentId) external view returns (uint64 count, uint8 averageScore) {
        address w = workerOfAgent[agentId];
        if (w == address(0)) return (0, 0);
        (uint256 good, uint256 bad) = weights(w);
        count = uint64(good + bad);
        averageScore = uint8(scoreOf(w) / 10);
    }
}

contracts/ZetaphyOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// Pyth's IPyth read surface, with PythStructs.Price's layout (the real Pyth and ZetaphyPythRelay both answer it).
interface IPythPrice {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
}

/// TwapRecorder's surface.
interface ITwapSource {
    struct Twap {
        uint256 avg0;
        uint256 avg1;
        uint64 from;
        uint64 newest;
        uint16 observations;
        uint128 minDepth;
        uint256 maxSegmentGapBps;
    }
    function consult(address pair, uint32 window) external view returns (Twap memory);
    function record(address pair) external returns (bool);
}

interface IPairTokens {
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IDecimals {
    function decimals() external view returns (uint8);
}

/// @title ZetaphyOracle: one price per asset, or a clear revert
/// @notice price(asset) returns (value, updatedAt): `value` is the asset's price in
///         USD with 18 decimals (1e18 = $1 per whole token), `updatedAt` the oldest
///         source time behind it. When any guard fails it REVERTS with an error
///         naming what failed; it never returns a stale, lopsided or jumped value.
///         Sources, per asset (governance enables one or both):
///           a) a TWAP of a ZETAPHY DEX pair (TwapRecorder observations, the pair's
///              cumulative prices; the other token is a USD stablecoin counted at $1):
///              valid only over at least `window` seconds (from an observation at
///              most 2 x window old), with at least `minObservations` observations
///              in it, a pool depth (quote side, 18 decimals) of at least
///              `minLiquidity` at every observation and now, and no segment
///              between observations averaging more than `maxSegmentGapBps` away
///              from the window's average;
///           b) Pyth (IPyth.getPriceUnsafe; on ZETAPHY a ZetaphyPythRelay until Pyth
///              or a Hyperlane route is here): not older than `maxAge`, not dated
///              in the future, positive, confidence interval at most `maxConfBps`
///              of the price.
///         With both: they must agree within `maxDeviationBps` (else SourcesDeviate);
///         the value is Pyth's, anchored by the TWAP. Decimals are normalized
///         (token decimals, Pyth's exponent) to 18.
///         Circuit breaker: poke(asset) (anyone; a keeper, the relay) records a TWAP
///         observation and, if every guard passes, makes the live price the
///         reference. price() refuses a live price more than `maxChangeBps` from the
///         reference, or more than `maxWindowChangeBps` from the price at the start
///         of the current `changeWindow`. A poke that sees such a jump TRIPS the
///         breaker: the asset has no price until governance resets it (through the
///         timelock). poke() also logs DeviationTripped / StaleFeed / SourceProblem
///         for the bridge monitor (zetaphy bridge monitor).
///         Roles: governance (the ZetaphyTimelock) sets every parameter; guardians
///         (multisigs governance names) may pause a feed at once. Unpausing,
///         resetting a tripped breaker and any setting wait the timelock.
contract ZetaphyOracle {
    struct TwapConfig {
        address pair;            // zero: no TWAP source
        bool assetIsToken0;
        uint8 assetDecimals;
        uint8 quoteDecimals;
        uint32 window;           // seconds
        uint16 minObservations;
        uint16 maxSegmentGapBps;
        uint128 minLiquidity;    // quote-side depth, 18 decimals (USD)
    }
    struct PythConfig {
        bytes32 id;              // zero: no Pyth source
        uint32 maxAge;           // seconds
        uint16 maxConfBps;
    }
    struct Guards {
        uint16 maxDeviationBps;      // between the two sources
        uint16 maxChangeBps;         // from the reference (the last accepted price)
        uint16 maxWindowChangeBps;   // from the price at the start of the change window
        uint32 changeWindow;         // seconds
    }
    struct State {
        uint128 lastPrice;       // the reference (0: none yet, poke first)
        uint64 lastAt;
        bool paused;
        bool tripped;
        uint128 windowPrice;
        uint64 windowStart;
    }

    /// What went wrong with the live price (poke logs it; price() reverts with the matching error).
    enum Problem { None, NotConfigured, TwapUnavailable, TwapStale, TooFewObservations, LowLiquidity, TwapSpike,
        PythUnavailable, PythStale, PythInvalid, PythConfidence, SourcesDeviate }

    ITwapSource public immutable recorder;
    IPythPrice public pyth;
    address public governance;
    mapping(address => bool) public guardian;

    mapping(address => TwapConfig) public twapOf;
    mapping(address => PythConfig) public pythOf;
    mapping(address => Guards) public guardsOf;
    mapping(address => State) public stateOf;
    address[] private _assets;
    mapping(address => bool) public listed;

    uint256 public constant MAX_FUTURE = 60;   // seconds a Pyth publishTime may run ahead (clock skew)
    uint256 private constant BPS = 10_000;

    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event PythSet(address pyth);
    event TwapConfigured(address indexed asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity);
    event PythConfigured(address indexed asset, bytes32 id, uint32 maxAge, uint16 maxConfBps);
    event GuardsSet(address indexed asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow);
    event FeedPaused(address indexed asset, address indexed by);
    event FeedUnpaused(address indexed asset);
    event CircuitBreakerReset(address indexed asset);
    event Poked(address indexed asset, uint256 price, uint256 updatedAt);
    event DeviationTripped(address indexed asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    event StaleFeed(address indexed asset, uint8 source, uint256 updatedAt);   // source 1 TWAP, 2 Pyth
    event SourceProblem(address indexed asset, uint8 problem, uint256 a, uint256 b);
    event CircuitBreakerTripped(address indexed asset, uint256 price, uint256 ref, uint256 bps);

    error NotGovernance();
    error NotGuardian();
    error UnknownAsset(address asset);
    error FeedIsPaused(address asset);
    error BreakerTripped(address asset);
    error NoReference(address asset);
    error PriceJump(address asset, uint256 price, uint256 ref, uint256 bps);
    /// No source enabled, or no guards set (setGuards is required).
    error NotConfigured(address asset);
    error TwapUnavailable(address asset);
    error TwapStale(address asset, uint256 from);
    error TooFewObservations(address asset, uint256 have, uint256 need);
    error LowLiquidity(address asset, uint256 depth, uint256 need);
    error TwapSpike(address asset, uint256 bps, uint256 most);
    error PythUnavailable(address asset);
    error PythStale(address asset, uint256 publishTime);
    error PythInvalid(address asset);
    error PythConfidence(address asset, uint256 bps, uint256 most);
    error SourcesDeviate(address asset, uint256 twapPrice, uint256 pythPrice, uint256 bps);
    error BadConfig();

    constructor(address governance_, ITwapSource recorder_, IPythPrice pyth_) {
        if (governance_ == address(0) || address(recorder_) == address(0)) revert BadConfig();
        governance = governance_;
        recorder = recorder_;
        pyth = pyth_;
        emit GovernanceSet(governance_);
        emit PythSet(address(pyth_));
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    // ---- governance (the timelock) ----

    function setGovernance(address g) external onlyGov { if (g == address(0)) revert BadConfig(); governance = g; emit GovernanceSet(g); }
    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }
    /// The Pyth contract (ZetaphyPythRelay now; Pyth itself once deployed on ZETAPHY). Zero: no Pyth.
    function setPyth(IPythPrice p) external onlyGov { pyth = p; emit PythSet(address(p)); }

    /// The TWAP source of `asset`: a DEX pair of `asset` and a USD stablecoin (pair zero: off).
    function setTwap(address asset, address pair, uint32 window, uint16 minObservations, uint16 maxSegmentGapBps, uint128 minLiquidity) external onlyGov {
        TwapConfig memory c;
        if (pair != address(0)) {
            address t0 = IPairTokens(pair).token0();
            address t1 = IPairTokens(pair).token1();
            if (asset != t0 && asset != t1) revert BadConfig();
            if (window < 60 || minObservations < 2 || maxSegmentGapBps == 0 || minLiquidity == 0) revert BadConfig();
            c = TwapConfig(pair, asset == t0, IDecimals(asset).decimals(), IDecimals(asset == t0 ? t1 : t0).decimals(),
                window, minObservations, maxSegmentGapBps, minLiquidity);
            if (c.quoteDecimals > 18 || c.assetDecimals > 30) revert BadConfig();
        }
        twapOf[asset] = c;
        _configured(asset);
        emit TwapConfigured(asset, pair, window, minObservations, maxSegmentGapBps, minLiquidity);
    }

    /// The Pyth feed of `asset` (id zero: off).
    function setPythFeed(address asset, bytes32 id, uint32 maxAge, uint16 maxConfBps) external onlyGov {
        if (id != bytes32(0) && (maxAge == 0 || maxConfBps == 0 || maxConfBps > BPS)) revert BadConfig();
        pythOf[asset] = PythConfig(id, maxAge, maxConfBps);
        _configured(asset);
        emit PythConfigured(asset, id, maxAge, maxConfBps);
    }

    function setGuards(address asset, uint16 maxDeviationBps, uint16 maxChangeBps, uint16 maxWindowChangeBps, uint32 changeWindow) external onlyGov {
        if (maxDeviationBps == 0 || maxChangeBps == 0 || maxWindowChangeBps < maxChangeBps || changeWindow == 0
            || maxDeviationBps > BPS || maxWindowChangeBps > BPS) revert BadConfig();
        guardsOf[asset] = Guards(maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
        _configured(asset);
        emit GuardsSet(asset, maxDeviationBps, maxChangeBps, maxWindowChangeBps, changeWindow);
    }

    /// Lifts a pause.
    function unpauseFeed(address asset) external onlyGov { stateOf[asset].paused = false; emit FeedUnpaused(asset); }

    /// Clears a tripped breaker and the reference: the next poke starts from the live price again.
    function resetCircuitBreaker(address asset) external onlyGov {
        State storage s = stateOf[asset];
        s.tripped = false;
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
        emit CircuitBreakerReset(asset);
    }

    function _configured(address asset) private {
        if (!listed[asset]) { listed[asset] = true; _assets.push(asset); }
        // A new source or guard starts from a fresh reference (the next poke).
        State storage s = stateOf[asset];
        s.lastPrice = 0; s.lastAt = 0; s.windowPrice = 0; s.windowStart = 0;
    }

    // ---- emergency: a guardian (or governance) stops a feed at once ----

    function pauseFeed(address asset) external {
        if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian();
        stateOf[asset].paused = true;
        emit FeedPaused(asset, msg.sender);
    }

    // ---- consumers ----

    function assets() external view returns (address[] memory) { return _assets; }

    /// The asset's price in USD (18 decimals) and the time of its oldest source, or a revert naming why not.
    function price(address asset) external view returns (uint256 value, uint256 updatedAt) {
        if (!listed[asset]) revert UnknownAsset(asset);
        State memory s = stateOf[asset];
        if (s.paused) revert FeedIsPaused(asset);
        if (s.tripped) revert BreakerTripped(asset);
        Problem p; uint256 a; uint256 b;
        (value, updatedAt, p, a, b) = _live(asset);
        if (p != Problem.None) _fail(asset, p, a, b);
        if (s.lastPrice == 0) revert NoReference(asset);
        (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
        if (!ok) revert PriceJump(asset, value, ref, bps);
    }

    /// The live price and what is wrong with it, without the circuit breaker (for monitors and tests).
    function livePrice(address asset) external view returns (uint256 value, uint256 updatedAt, Problem problem, uint256 a, uint256 b) {
        return _live(asset);
    }

    /// Anyone: records a TWAP observation and, when every guard passes, moves the reference
    /// to the live price. A jump beyond the change limits trips the breaker. Returns whether
    /// the reference moved.
    function poke(address asset) external returns (bool) {
        if (!listed[asset]) revert UnknownAsset(asset);
        address pair = twapOf[asset].pair;
        if (pair != address(0)) { try recorder.record(pair) {} catch {} }
        State storage s = stateOf[asset];
        if (s.paused || s.tripped) return false;
        (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) = _live(asset);
        if (p != Problem.None) {
            if (p == Problem.SourcesDeviate) emit DeviationTripped(asset, a, b, _bps(a, b));
            else if (p == Problem.TwapStale) emit StaleFeed(asset, 1, a);
            else if (p == Problem.PythStale) emit StaleFeed(asset, 2, a);
            else emit SourceProblem(asset, uint8(p), a, b);
            return false;
        }
        if (s.lastPrice != 0) {
            if (block.timestamp >= uint256(s.windowStart) + guardsOf[asset].changeWindow) {
                s.windowPrice = s.lastPrice;
                s.windowStart = uint64(block.timestamp);
            }
            (uint256 ref, uint256 bps, bool ok) = _change(asset, s, value);
            if (!ok) {
                s.tripped = true;
                emit CircuitBreakerTripped(asset, value, ref, bps);
                return false;
            }
        } else {
            s.windowPrice = uint128(value);
            s.windowStart = uint64(block.timestamp);
        }
        s.lastPrice = uint128(value);
        s.lastAt = uint64(at);
        emit Poked(asset, value, at);
        return true;
    }

    // ---- internals ----

    /// (reference, bps, ok): the live value against the reference and the window's start price.
    function _change(address asset, State memory s, uint256 value) private view returns (uint256, uint256, bool) {
        Guards memory g = guardsOf[asset];
        uint256 bps = _bps(value, s.lastPrice);
        if (bps > g.maxChangeBps) return (s.lastPrice, bps, false);
        if (s.windowPrice != 0 && block.timestamp < uint256(s.windowStart) + g.changeWindow) {
            uint256 wb = _bps(value, s.windowPrice);
            if (wb > g.maxWindowChangeBps) return (s.windowPrice, wb, false);
        }
        return (s.lastPrice, bps, true);
    }

    function _live(address asset) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        TwapConfig memory t = twapOf[asset];
        PythConfig memory y = pythOf[asset];
        if (t.pair == address(0) && (y.id == bytes32(0) || address(pyth) == address(0))) return (0, 0, Problem.NotConfigured, 0, 0);
        if (guardsOf[asset].maxChangeBps == 0) return (0, 0, Problem.NotConfigured, 0, 0); // guards are required
        uint256 twapValue; uint256 twapAt;
        if (t.pair != address(0)) {
            (twapValue, twapAt, p, a, b) = _twap(t);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        uint256 pythValue; uint256 pythAt;
        if (y.id != bytes32(0) && address(pyth) != address(0)) {
            (pythValue, pythAt, p, a, b) = _pyth(y);
            if (p != Problem.None) return (0, 0, p, a, b);
        }
        if (twapValue != 0 && pythValue != 0) {
            uint256 dev = _bps(twapValue, pythValue);
            if (dev > guardsOf[asset].maxDeviationBps) return (0, 0, Problem.SourcesDeviate, twapValue, pythValue);
            return (pythValue, pythAt < twapAt ? pythAt : twapAt, Problem.None, 0, 0);
        }
        return pythValue != 0 ? (pythValue, pythAt, Problem.None, 0, 0) : (twapValue, twapAt, Problem.None, 0, 0);
    }

    function _twap(TwapConfig memory t) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        ITwapSource.Twap memory w;
        try recorder.consult(t.pair, t.window) returns (ITwapSource.Twap memory r) { w = r; } catch { return (0, 0, Problem.TwapUnavailable, 0, 0); }
        if (block.timestamp - w.from > 2 * uint256(t.window)) return (0, 0, Problem.TwapStale, w.from, 0);
        if (w.observations < t.minObservations) return (0, 0, Problem.TooFewObservations, w.observations, t.minObservations);
        if (w.maxSegmentGapBps > t.maxSegmentGapBps) return (0, 0, Problem.TwapSpike, w.maxSegmentGapBps, t.maxSegmentGapBps);
        uint256 avg = t.assetIsToken0 ? w.avg0 : w.avg1;   // quote (raw) per asset (raw), UQ112x112
        if (avg == 0) return (0, 0, Problem.TwapUnavailable, 0, 0);
        // depth: sqrt(r0 r1) * sqrt(quote per asset) = the quote reserve; then 18 decimals
        uint256 depth = (uint256(w.minDepth) * _sqrt(avg)) >> 56;
        depth = depth * (10 ** uint256(18 - t.quoteDecimals));
        if (depth < t.minLiquidity) return (0, 0, Problem.LowLiquidity, depth, t.minLiquidity);
        value = _mulDiv(avg, 10 ** (uint256(t.assetDecimals) + 18), (10 ** uint256(t.quoteDecimals)) << 112);
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.TwapUnavailable, 0, 0);
        return (value, w.newest, Problem.None, 0, 0);
    }

    function _pyth(PythConfig memory y) private view returns (uint256 value, uint256 at, Problem p, uint256 a, uint256 b) {
        IPythPrice.Price memory q;
        try pyth.getPriceUnsafe(y.id) returns (IPythPrice.Price memory r) { q = r; } catch { return (0, 0, Problem.PythUnavailable, 0, 0); }
        if (q.publishTime > block.timestamp + MAX_FUTURE) return (0, 0, Problem.PythInvalid, q.publishTime, 0);
        if (block.timestamp > q.publishTime && block.timestamp - q.publishTime > y.maxAge) return (0, 0, Problem.PythStale, q.publishTime, 0);
        if (q.price <= 0 || q.expo < -30 || q.expo > 12) return (0, 0, Problem.PythInvalid, 0, 0);
        uint256 raw = uint256(uint64(q.price));
        uint256 confBps = _mulDiv(uint256(q.conf), BPS, raw);
        if (confBps > y.maxConfBps) return (0, 0, Problem.PythConfidence, confBps, y.maxConfBps);
        int256 e = int256(q.expo) + 18;
        value = e >= 0 ? raw * (10 ** uint256(e)) : raw / (10 ** uint256(-e));
        if (value == 0 || value > type(uint128).max) return (0, 0, Problem.PythInvalid, 0, 0);
        return (value, q.publishTime > block.timestamp ? block.timestamp : q.publishTime, Problem.None, 0, 0);
    }

    function _fail(address asset, Problem p, uint256 a, uint256 b) private pure {
        if (p == Problem.NotConfigured) revert NotConfigured(asset);
        if (p == Problem.TwapUnavailable) revert TwapUnavailable(asset);
        if (p == Problem.TwapStale) revert TwapStale(asset, a);
        if (p == Problem.TooFewObservations) revert TooFewObservations(asset, a, b);
        if (p == Problem.LowLiquidity) revert LowLiquidity(asset, a, b);
        if (p == Problem.TwapSpike) revert TwapSpike(asset, a, b);
        if (p == Problem.PythUnavailable) revert PythUnavailable(asset);
        if (p == Problem.PythStale) revert PythStale(asset, a);
        if (p == Problem.PythInvalid) revert PythInvalid(asset);
        if (p == Problem.PythConfidence) revert PythConfidence(asset, a, b);
        revert SourcesDeviate(asset, a, b, _bps(a, b));
    }

    /// |x - y| / min(x, y), in bps.
    function _bps(uint256 x, uint256 y) private pure returns (uint256) {
        uint256 lo = x < y ? x : y;
        if (lo == 0) return type(uint256).max;
        return _mulDiv(x > y ? x - y : y - x, BPS, lo);
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        z = x;
        uint256 y = x / 2 + 1;
        while (y < z) { z = y; y = (x / y + y) / 2; }
    }

    /// floor(a * b / d) with a 512-bit product (Remco Bloemen's mulDiv, MIT).
    function _mulDiv(uint256 a, uint256 b, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(a, b, not(0))
                prod0 := mul(a, b)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }
            if (prod1 == 0) return prod0 / d;
            require(d > prod1, "mulDiv");
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }
            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            inv *= 2 - d * inv; inv *= 2 - d * inv; inv *= 2 - d * inv;
            result = prod0 * inv;
        }
    }
}

contracts/ZetaphyPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title BZTPHY: ZETAPHY testnet reward points
/// @notice People who run ZETAPHY validators and Neuro runners on the testnet earn BZTPHY.
///         When mainnet launches, BZTPHY balances at the freeze become ZETAPHY at mainnet genesis
///         (a share of a fixed pool; see zetaphy-chain/rewards/README.md).
///         BZTPHY cannot be transferred, approved or sold: it shows who did the work, not who bought it.
///         Wallets still show the balance (balanceOf, totalSupply, name, symbol, decimals, Transfer events).
contract ZetaphyPoints {
    string public constant name = "ZETAPHY Testnet Reward Points";
    string public constant symbol = "BZTPHY";
    uint8 public constant decimals = 18;

    address public owner;          // governance: sets the minter, the cap, revokes, freezes
    address public pendingOwner;
    address public minter;         // the daily award job
    uint256 public epochCap;       // most BZTPHY one epoch (UTC day) may award in total
    bool public frozen;            // after the freeze nothing changes: the balances are the snapshot

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(uint32 => uint256) public awardedInEpoch;
    mapping(uint32 => mapping(address => bool)) public awarded;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Awarded(uint32 indexed epoch, address indexed to, uint256 amount, bytes32 reason);
    event Revoked(address indexed from, uint256 amount, bytes32 reason);
    event MinterSet(address minter);
    event EpochCapSet(uint256 cap);
    event OwnershipTransferStarted(address indexed to);
    event OwnershipTransferred(address indexed from, address indexed to);
    event Frozen(uint256 totalSupply);

    error NotOwner();
    error NotMinter();
    error IsFrozen();
    error NonTransferable();
    error LengthMismatch();
    error AlreadyAwarded(uint32 epoch, address to);
    error OverEpochCap(uint32 epoch);
    error ZeroAddress();

    constructor(address owner_, address minter_, uint256 epochCap_) {
        if (owner_ == address(0)) revert ZeroAddress();
        owner = owner_;
        minter = minter_;
        epochCap = epochCap_;
        emit OwnershipTransferred(address(0), owner_);
        emit MinterSet(minter_);
        emit EpochCapSet(epochCap_);
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier notFrozen() {
        if (frozen) revert IsFrozen();
        _;
    }

    /// @notice Awards one epoch's points. Each address gets at most one award per epoch, so a
    ///         job that runs twice cannot pay twice, and an epoch never exceeds epochCap (a stolen
    ///         minter key can mint at most one cap per day, and the owner can revoke it).
    function award(uint32 epoch, address[] calldata to, uint256[] calldata amounts, bytes32 reason) external notFrozen {
        if (msg.sender != minter) revert NotMinter();
        if (to.length != amounts.length) revert LengthMismatch();
        uint256 before = awardedInEpoch[epoch];
        uint256 total = before;
        for (uint256 i = 0; i < to.length; i++) {
            address a = to[i];
            if (a == address(0)) revert ZeroAddress();
            if (awarded[epoch][a]) revert AlreadyAwarded(epoch, a);
            awarded[epoch][a] = true;
            total += amounts[i];
            balanceOf[a] += amounts[i];
            emit Transfer(address(0), a, amounts[i]);
            emit Awarded(epoch, a, amounts[i], reason);
        }
        if (total > epochCap) revert OverEpochCap(epoch);
        awardedInEpoch[epoch] = total;
        totalSupply += total - before;
    }

    /// @notice Takes points back (cheating, e.g. one person running many fake validators).
    function revoke(address from, uint256 amount, bytes32 reason) external onlyOwner notFrozen {
        uint256 b = balanceOf[from];
        if (amount > b) amount = b;
        balanceOf[from] = b - amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
        emit Revoked(from, amount, reason);
    }

    function setMinter(address m) external onlyOwner notFrozen {
        minter = m;
        emit MinterSet(m);
    }

    function setEpochCap(uint256 cap) external onlyOwner notFrozen {
        epochCap = cap;
        emit EpochCapSet(cap);
    }

    /// @notice Ends the program for good: the balances now are what mainnet genesis uses.
    function freeze() external onlyOwner notFrozen {
        frozen = true;
        minter = address(0);
        emit Frozen(totalSupply);
    }

    function transferOwnership(address to) external onlyOwner {
        pendingOwner = to;
        emit OwnershipTransferStarted(to);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotOwner();
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    // ---- ERC-20 surface that refuses to move points --------------------------------------
    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function transfer(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }

    function approve(address, uint256) external pure returns (bool) {
        revert NonTransferable();
    }
}

contracts/ZetaphyPythRelay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice The part of Pyth's IPyth (pyth-sdk-solidity) ZETAPHY reads and writes,
///         with Pyth's own struct layout (PythStructs.Price / PriceFeed): the
///         ABI is the same as the real Pyth contract's, so ZetaphyOracle can be
///         pointed at real Pyth later (ZetaphyOracle.setPyth, through the timelock).
interface IPythLike {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }
    struct PriceFeed {
        bytes32 id;
        Price price;
        Price emaPrice;
    }
    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory);
    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory);
    function priceFeedExists(bytes32 id) external view returns (bool);
    function getUpdateFee(bytes[] calldata updateData) external view returns (uint256);
    function updatePriceFeeds(bytes[] calldata updateData) external payable;
}

/// @title ZetaphyPythRelay: Pyth prices on ZETAPHY before Pyth itself is here
/// @notice Pyth has no contract on ZETAPHY yet. Real Pyth checks each update
///         against Wormhole guardian signatures; this relay instead accepts an
///         update only when `threshold` distinct relayers (keys governance names)
///         submitted exactly the same one. Updates use Pyth's public format, the
///         one Pyth's MockPyth.createPriceFeedUpdateData builds:
///             abi.encode(PythStructs.PriceFeed feed, uint64 prevPublishTime)
///         so a relayer forwards what it reads from Pyth (Hermes) unchanged.
///         Like Pyth: an older update than the stored one is ignored (not an
///         error), the PriceFeedUpdate event is Pyth's, and reads revert with
///         PriceFeedNotFound / StalePrice. Unlike Pyth: the update fee is 0 and
///         sending value is refused.
///         Trust: the relayers (and governance, which names them) can publish any
///         price. ZetaphyOracle does not trust it alone: it checks staleness, the
///         confidence interval, the deviation from the DEX TWAP and a circuit
///         breaker. Later, either point ZetaphyOracle at real Pyth, or make a
///         Hyperlane receiver (a contract whose handle() takes Pyth updates from
///         a Hyperlane message out of a chain where Pyth verified them) the only
///         relayer, with threshold 1. Docs: zetaphy-network/README.md (oracle).
///         Governance: the ZetaphyTimelock.
contract ZetaphyPythRelay is IPythLike {
    address public governance;
    mapping(address => bool) public isRelayer;
    uint256 public relayerCount;
    uint8 public threshold;
    /// The furthest in the future a publishTime may be (clock skew).
    uint256 public constant MAX_FUTURE = 60;

    mapping(bytes32 => PriceFeed) private _feeds;
    /// keccak256(update) => relayer => submitted (an update is accepted once threshold relayers sent it)
    mapping(bytes32 => mapping(address => bool)) public submitted;
    /// Who submitted each update, so only those still relayers count
    /// (submissions()): a relayer governance removes no longer counts.
    mapping(bytes32 => address[]) private _submitters;

    event PriceFeedUpdate(bytes32 indexed id, uint64 publishTime, int64 price, uint64 conf);
    event RelayerSet(address indexed relayer, bool on);
    event ThresholdSet(uint8 threshold);
    event GovernanceSet(address governance);
    event Submitted(bytes32 indexed id, bytes32 indexed update, address indexed relayer, uint8 count);

    error NotGovernance();
    error NotRelayer();
    error PriceFeedNotFound();
    error StalePrice();
    error InvalidUpdateData();
    error NoFee();

    constructor(address governance_, address[] memory relayers, uint8 threshold_) {
        require(governance_ != address(0), "governance");
        governance = governance_;
        for (uint256 i = 0; i < relayers.length; i++) _setRelayer(relayers[i], true);
        require(threshold_ >= 1, "threshold");
        threshold = threshold_;
        emit GovernanceSet(governance_);
        emit ThresholdSet(threshold_);
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setRelayer(address who, bool on) external onlyGov { _setRelayer(who, on); }
    function setThreshold(uint8 t) external onlyGov { require(t >= 1, "threshold"); threshold = t; emit ThresholdSet(t); }
    function setGovernance(address g) external onlyGov { require(g != address(0), "governance"); governance = g; emit GovernanceSet(g); }

    function _setRelayer(address who, bool on) private {
        require(who != address(0), "relayer");
        if (on != isRelayer[who]) { if (on) relayerCount += 1; else relayerCount -= 1; }
        isRelayer[who] = on;
        emit RelayerSet(who, on);
    }

    // ---- Pyth's interface ----

    function getUpdateFee(bytes[] calldata) external pure returns (uint256) { return 0; }

    function updatePriceFeeds(bytes[] calldata updateData) external payable {
        if (msg.value != 0) revert NoFee();
        if (!isRelayer[msg.sender]) revert NotRelayer();
        for (uint256 i = 0; i < updateData.length; i++) {
            (PriceFeed memory f, ) = abi.decode(updateData[i], (PriceFeed, uint64));
            if (f.id == bytes32(0) || f.price.publishTime > block.timestamp + MAX_FUTURE) revert InvalidUpdateData();
            if (f.price.publishTime <= _feeds[f.id].price.publishTime) continue; // older or same: ignored, as Pyth does
            bytes32 u = keccak256(updateData[i]);
            uint8 n = submissions(u);
            if (!submitted[u][msg.sender]) {
                submitted[u][msg.sender] = true;
                _submitters[u].push(msg.sender);
                n += 1;
                emit Submitted(f.id, u, msg.sender, n);
            }
            if (n < threshold) continue;
            _feeds[f.id] = f;
            emit PriceFeedUpdate(f.id, uint64(f.price.publishTime), f.price.price, f.price.conf);
        }
    }

    /// How many current relayers submitted this update (keccak256 of it).
    function submissions(bytes32 u) public view returns (uint8 n) {
        address[] storage s = _submitters[u];
        for (uint256 i = 0; i < s.length; i++) if (isRelayer[s[i]]) n += 1;
    }

    function priceFeedExists(bytes32 id) public view returns (bool) { return _feeds[id].price.publishTime != 0; }

    function getPriceUnsafe(bytes32 id) public view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].price;
    }

    function getEmaPriceUnsafe(bytes32 id) external view returns (Price memory) {
        if (!priceFeedExists(id)) revert PriceFeedNotFound();
        return _feeds[id].emaPrice;
    }

    function getPriceNoOlderThan(bytes32 id, uint256 age) external view returns (Price memory p) {
        p = getPriceUnsafe(id);
        if (block.timestamp > p.publishTime && block.timestamp - p.publishTime > age) revert StalePrice();
    }
}
